import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data for demonstration purposes
const appointments = [
  { id: "1", patientId: "101", doctorId: "201", date: "2023-10-15", time: "09:00" },
  { id: "2", patientId: "102", doctorId: "201", date: "2023-10-15", time: "10:00" },
];

// Helper function to check for time conflicts
const hasTimeConflict = (newAppointment: any, existingAppointments: any[]) => {
  return existingAppointments.some(appointment => 
    appointment.doctorId === newAppointment.doctorId &&
    appointment.date === newAppointment.date &&
    appointment.time === newAppointment.time
  );
};

// GET /appointments - List all appointments
router.get("/appointments", (req: Request, res: Response) => {
  res.json(appointments);
});

// GET /appointments/:id - Get one appointment by ID
router.get("/appointments/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const appointment = appointments.find(a => a.id === id);

  if (!appointment) {
    return res.status(404).json({ error: "Appointment not found" });
  }

  res.json(appointment);
});

// POST /appointments - Create a new appointment
router.post("/appointments", (req: Request, res: Response) => {
  const { patientId, doctorId, date, time } = req.body;

  // Validate required fields
  if (!patientId || !doctorId || !date || !time) {
    return res.status(400).json({ error: "Missing required fields: patientId, doctorId, date, time" });
  }

  // Check for time conflicts
  const newAppointment = { id: String(appointments.length + 1), patientId, doctorId, date, time };

  if (hasTimeConflict(newAppointment, appointments)) {
    return res.status(400).json({ error: "Time slot already booked for this doctor" });
  }

  // Add new appointment
  appointments.push(newAppointment);

  res.status(201).json(newAppointment);
});

// PUT /appointments/:id - Update an existing appointment
router.put("/appointments/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const { patientId, doctorId, date, time } = req.body;

  // Validate required fields
  if (!patientId || !doctorId || !date || !time) {
    return res.status(400).json({ error: "Missing required fields: patientId, doctorId, date, time" });
  }

  const appointmentIndex = appointments.findIndex(a => a.id === id);

  if (appointmentIndex === -1) {
    return res.status(404).json({ error: "Appointment not found" });
  }

  // Check for time conflicts (excluding current appointment)
  const updatedAppointment = { id, patientId, doctorId, date, time };

  if (hasTimeConflict(updatedAppointment, appointments.filter(a => a.id !== id))) {
    return res.status(400).json({ error: "Time slot already booked for this doctor" });
  }

  // Update appointment
  appointments[appointmentIndex] = updatedAppointment;

  res.json(updatedAppointment);
});

// DELETE /appointments/:id - Delete an appointment
router.delete("/appointments/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const appointmentIndex = appointments.findIndex(a => a.id === id);

  if (appointmentIndex === -1) {
    return res.status(404).json({ error: "Appointment not found" });
  }

  appointments.splice(appointmentIndex, 1);

  res.json({ message: "Appointment deleted successfully" });
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  { id: 1, username: "admin", password: "password123", role: "admin" },
  { id: 2, username: "doctor", password: "docpass456", role: "doctor" },
  { id: 3, username: "patient", password: "patpass789", role: "patient" }
];

// Mock session storage
const sessions = new Map<string, { userId: number; role: string; expiresAt: Date }>();

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate session token
  const token = Math.random().toString(36).substring(2, 15);
  const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000); // 24 hours

  sessions.set(token, {
    userId: user.id,
    role: user.role,
    expiresAt
  });

  return res.status(200).json({ token, role: user.role });
});

// Logout endpoint
router.post("/logout", (req: Request, res: Response) => {
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    return res.status(400).json({ error: "No token provided" });
  }

  if (!sessions.has(token)) {
    return res.status(401).json({ error: "Invalid token" });
  }

  sessions.delete(token);
  return res.status(200).json({ message: "Logged out successfully" });
});

// Middleware to verify session
const authenticate = (req: Request, res: Response, next: () => void) => {
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "No token provided" });
  }

  const session = sessions.get(token);

  if (!session) {
    return res.status(401).json({ error: "Invalid token" });
  }

  // Check if session has expired
  if (new Date() > session.expiresAt) {
    sessions.delete(token);
    return res.status(401).json({ error: "Session expired" });
  }

  // Attach user info to request
  (req as any).user = session;
  next();
};

// Get current user info
router.get("/me", authenticate, (req: Request, res: Response) => {
  const user = (req as any).user;
  return res.status(200).json({ id: user.userId, role: user.role });
});

// Check authorization based on role
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: () => void) => {
    const user = (req as any).user;

    if (!roles.includes(user.role)) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }

    next();
  };
};

// Admin-only route example
router.get("/admin", authenticate, authorize(["admin"]), (req: Request, res: Response) => {
  return res.status(200).json({ message: "Admin access granted" });
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-protected routes
  if (!req.path.startsWith('/api/')) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Missing or invalid authorization header' });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: 'Server configuration error' });
    return;
  }

  // Simple token verification (in a real app, use proper JWT library)
  const [payload, signature] = token.split('.');
  if (!payload || !signature) {
    res.status(401).json({ error: 'Invalid token format' });
    return;
  }

  try {
    const expectedSignature = createHmac('sha256', secret)
      .update(payload)
      .digest('base64url');

    const expectedBuffer = Buffer.from(expectedSignature, 'base64url');
    const actualBuffer = Buffer.from(signature, 'base64url');

    if (actualBuffer.length !== expectedBuffer.length || 
        !timingSafeEqual(actualBuffer, expectedBuffer)) {
      res.status(401).json({ error: 'Invalid token signature' });
      return;
    }

    // Decode payload (simplified for this example)
    const decodedPayload = JSON.parse(Buffer.from(payload, 'base64url').toString());
    const userRole = decodedPayload.role;
    const userId = decodedPayload.userId;

    // Check role-based access control
    if (userRole === 'admin') {
      // Admin has full access
      next();
      return;
    }

    // For non-admin roles, check specific permissions
    if (userRole === 'doctor') {
      // Doctor can only access their own patients
      if (req.path.includes('/patients/') && req.params.patientId) {
        const patientId = req.params.patientId;
        // In a real implementation, we'd check if doctor owns this patient
        // For now, we'll just allow access to the path
        next();
        return;
      }

      // Allow read-only access to own schedule
      if (req.path.includes('/schedule/') && req.method === 'GET') {
        next();
        return;
      }

      // Reject other operations
      res.status(403).json({ error: 'Access denied' });
      return;
    }

    if (userRole === 'nurse') {
      // Nurse can manage all appointments
      if (req.path.includes('/appointments/')) {
        next();
        return;
      }

      // Allow read-only access to schedule
      if (req.path.includes('/schedule/') && req.method === 'GET') {
        next();
        return;
      }

      // Reject other operations
      res.status(403).json({ error: 'Access denied' });
      return;
    }

    // Unauthorized role
    res.status(403).json({ error: 'Access denied' });
  } catch (error) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip authentication for health check endpoints
  if (req.method === "GET" && req.path === "/health") {
    next();
    return;
  }

  // Only protect POST requests to booking endpoints
  if (!(req.method === "POST" && req.path.startsWith("/bookings"))) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT_SECRET not configured" });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify the JWT signature)
  const expectedSignature = createHmac("sha256", secret)
    .update(token)
    .digest();

  const providedSignature = Buffer.from(token, "hex");

  try {
    if (timingSafeEqual(expectedSignature, providedSignature)) {
      next();
    } else {
      res.status(401).json({ error: "Unauthorized: Invalid token" });
    }
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

import { useEffect, useState } from "react";

interface Appointment {
  id: number;
  patientName: string;
  doctorName: string;
  date: string;
  time: string;
  status: string;
}

export function AppointmentListPage() {
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    fetchAppointments();
  }, []);

  const fetchAppointments = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/appointments');
      if (!response.ok) {
        throw new Error('Failed to fetch appointments');
      }
      const data = await response.json();
      setAppointments(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/appointments/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error('Failed to delete appointment');
      }
      // Refresh the list after deletion
      fetchAppointments();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const filteredAppointments = appointments.filter(appointment =>
    appointment.patientName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    appointment.doctorName.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Appointment List</h1>

      <div style={{ marginBottom: '20px' }}>
        <input
          type="text"
          placeholder="Search by patient or doctor name..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{
            width: '100%',
            padding: '10px',
            borderRadius: '4px',
            border: '1px solid #ccc',
            fontSize: '16px'
          }}
        />
      </div>

      {filteredAppointments.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No appointments found.</p>
      ) : (
        <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '20px' }}>
            <thead>
              <tr style={{ backgroundColor: '#f2f2f2' }}>
                <th style={{ border: '1px solid #ddd', padding: '12px', textAlign: 'left' }}>Patient Name</th>
                <th style={{ border: '1px solid #ddd', padding: '12px', textAlign: 'left' }}>Doctor</th>
                <th style={{ border: '1px solid #ddd', padding: '12px', textAlign: 'left' }}>Date</th>
                <th style={{ border: '1px solid #ddd', padding: '12px', textAlign: 'left' }}>Time</th>
                <th style={{ border: '1px solid #ddd', padding: '12px', textAlign: 'left' }}>Status</th>
                <th style={{ border: '1px solid #ddd', padding: '12px', textAlign: 'left' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredAppointments.map((appointment) => (
                <tr key={appointment.id} style={{ borderBottom: '1px solid #ddd' }}>
                  <td style={{ border: '1px solid #ddd', padding: '12px' }}>{appointment.patientName}</td>
                  <td style={{ border: '1px solid #ddd', padding: '12px' }}>{appointment.doctorName}</td>
                  <td style={{ border: '1px solid #ddd', padding: '12px' }}>{appointment.date}</td>
                  <td style={{ border: '1px solid #ddd', padding: '12px' }}>{appointment.time}</td>
                  <td style={{ border: '1px solid #ddd', padding: '12px' }}>{appointment.status}</td>
                  <td style={{ border: '1px solid #ddd', padding: '12px' }}>
                    <button 
                      onClick={() => {
                        // In a real app, this would navigate to an edit page
                        alert(`Edit appointment ${appointment.id}`);
                      }}
                      style={{
                        marginRight: '10px',
                        padding: '5px 10px',
                        backgroundColor: '#007bff',
                        color: 'white',
                        border: 'none',
                        borderRadius: '4px',
                        cursor: 'pointer'
                      }}
                    >
                      Edit
                    </button>
                    <button 
                      onClick={() => handleDelete(appointment.id)}
                      style={{
                        padding: '5px 10px',
                        backgroundColor: '#dc3545',
                        color: 'white',
                        border: 'none',
                        borderRadius: '4px',
                        cursor: 'pointer'
                      }}
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

