import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes and methods
  const protectedPaths = ["/admin", "/users", "/bookings"];
  const protectedMethods = ["POST", "PUT", "DELETE"];

  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath || !protectedMethods.includes(req.method)) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);

  // Verify JWT signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  try {
    // Simple verification - in a real system, use a proper JWT library
    const [header, payload, signature] = token.split(".");

    if (!header || !payload || !signature) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    // Create expected signature
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (signatureBuffer.length !== expectedSignatureBuffer.length ||
        !timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // Decode payload to get user role
    const payloadDecoded = Buffer.from(payload, "base64url").toString("utf-8");
    const payloadObj = JSON.parse(payloadDecoded);

    // Check if user has required role
    const requiredRole = getRequiredRole(req.path, req.method);
    if (!payloadObj.role || payloadObj.role !== requiredRole) {
      res.status(403).json({ error: "Forbidden: Insufficient permissions" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

function getRequiredRole(path: string, method: string): string {
  // Define role requirements based on path and method
  if (path.startsWith("/admin") && method === "POST") {
    return "admin";
  } else if (path.startsWith("/users") && method === "PUT") {
    return "admin";
  } else if (path.startsWith("/bookings") && method === "DELETE") {
    return "admin";
  }

  // Default to authenticated user
  return "authenticated";
}

