    fetchCars();
  }, []);

  const fetchCars = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/cars");
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setCars(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFilter({
      ...filter,
      [name]: value,
    });
  };

  const filteredCars = cars.filter(car => {
    const makeMatch = filter.make === "" || car.make.toLowerCase().includes(filter.make.toLowerCase());
    const modelMatch = filter.model === "" || car.model.toLowerCase().includes(filter.model.toLowerCase());
    const yearMatch = 
      (filter.minYear === "" || car.year >= parseInt(filter.minYear)) &&
      (filter.maxYear === "" || car.year <= parseInt(filter.maxYear));
    const rateMatch = 
      (filter.minRate === "" || car.dailyRate >= parseFloat(filter.minRate)) &&
      (filter.maxRate === "" || car.dailyRate <= parseFloat(filter.maxRate));

    return makeMatch && modelMatch && yearMatch && rateMatch;
  });

  const handleBook = async (carId: number) => {
    try {
      const response = await fetch(`/api/cars/${carId}/book`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ carId }),
      });
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      // Refresh the car list after booking
      await fetchCars();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "system-ui, sans-serif" }}>
