import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  const protectedPaths = ["/jobs", "/staff", "/reports"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has proper role permissions
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (!userRole) {
    res.status(401).json({ error: "Unauthorized: Missing role header" });
    return;
  }

  // Define role permissions
  const rolePermissions: Record<string, string[]> = {
    admin: ["GET", "POST", "PUT", "DELETE"],
    technician: ["GET", "PUT"],
    manager: ["GET", "POST", "PUT", "DELETE"],
    receptionist: ["GET", "POST"]
  };

  const allowedMethods = rolePermissions[userRole] || [];
  const currentMethod = req.method;

  if (!allowedMethods.includes(currentMethod)) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const ACTIVE_SESSIONS = new Map<string, { expiresAt: number }>();
const SESSION_TIMEOUT_MS = 30 * 60 * 1000; // 30 minutes

function isValidToken(token: string): boolean {
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return false;
  }

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) {
      return false;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests with a token in the header
  if (req.method !== "POST" || !req.header("Authorization")) {
    return next();
  }

  const authHeader = req.header("Authorization");
  const token = authHeader.startsWith("Bearer ") ? authHeader.substring(7) : null;

  if (!token) {
    return res.status(401).json({ error: "Invalid token" });
  }

  if (!isValidToken(token)) {
    return res.status(401).json({ error: "Invalid token" });
  }

  const session = ACTIVE_SESSIONS.get(token);
  if (!session) {
    return res.status(401).json({ error: "Invalid token" });
  }

  if (Date.now() > session.expiresAt) {
    ACTIVE_SESSIONS.delete(token);
    return res.status(401).json({ error: "Session expired" });
  }

  // Refresh session timeout
  session.expiresAt = Date.now() + SESSION_TIMEOUT_MS;

  next();
}

