import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  const protectedPaths = ["/results", "/results/"];
  const isProtectedPath = protectedPaths.some(path => 
    req.path.startsWith(path) || req.path === path
  );

  // Skip validation for non-protected routes
  if (!isProtectedPath) {
    next();
    return;
  }

  // Check HTTP method
  const allowedMethods = ["GET", "POST", "PUT", "DELETE"];
  if (!allowedMethods.includes(req.method)) {
    next();
    return;
  }

  // For demonstration purposes, we'll assume a simple role check
  // In a real implementation, this would check a JWT or session
  const userRole = req.headers["x-user-role"] as string | undefined;

  // Define role permissions
  const rolePermissions: Record<string, string[]> = {
    admin: ["GET", "POST", "PUT", "DELETE"],
    teacher: ["GET", "POST", "PUT"],
    student: ["GET"]
  };

  // If no role is provided, deny access
  if (!userRole) {
    res.status(403).json({ error: "Access denied: Role required" });
    return;
  }

  // Check if the user's role has permission for this method
  const permissions = rolePermissions[userRole] || [];
  if (!permissions.includes(req.method)) {
    res.status(403).json({ error: "Access denied: Insufficient permissions" });
    return;
  }

  // If we reach here, the user has proper permissions
  next();
}

