import { useEffect, useState } from "react";

interface ExamResult {
  id: number;
  subject: string;
  score: number;
  date: string;
}

interface StudentProfile {
  id: number;
  name: string;
  email: string;
  enrollmentDate: string;
  results: ExamResult[];
}

export function StudentProfilePage({ studentId }: { studentId: string }) {
  const [student, setStudent] = useState<StudentProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchStudentProfile = async () => {
      try {
        const response = await fetch(`/api/students/${studentId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch student: ${response.status}`);
        }
        const data = await response.json();
        setStudent(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchStudentProfile();
  }, [studentId]);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (!student) {
    return <div style={{ textAlign: "center", padding: "20px" }}>No student found</div>;
  }

  const calculateAverage = () => {
    if (student.results.length === 0) return 0;
    const total = student.results.reduce((sum, result) => sum + result.score, 0);
    return Math.round((total / student.results.length) * 100) / 100;
  };

  const averageScore = calculateAverage();

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Student Profile</h1>

      <div style={{ marginBottom: "30px", padding: "20px", borderRadius: "8px", backgroundColor: "#f5f5f5" }}>
        <h2>{student.name}</h2>
        <p><strong>Email:</strong> {student.email}</p>
        <p><strong>Enrollment Date:</strong> {student.enrollmentDate}</p>
        <p><strong>Average Score:</strong> {averageScore}%</p>
      </div>

      <h2>Exam Results</h2>
      {student.results.length === 0 ? (
        <p>No exam results available</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {student.results.map((result) => (
            <div key={result.id} style={{ padding: "15px", border: "1px solid #ddd", borderRadius: "4px" }}>
              <div style={{ display: "flex", justifyContent: "space-between" }}>
                <span><strong>{result.subject}</strong></span>
                <span>{result.score}%</span>
              </div>
              <div style={{ marginTop: "5px", fontSize: "0.9em", color: "#666" }}>
                {new Date(result.date).toLocaleDateString()}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// Mock session store - in a real implementation this would connect to a database
const sessionStore: Map<string, { userId: string; expiresAt: number }> = new Map();

function isValidToken(token: string): boolean {
  // Basic token format validation
  const parts = token.split(".");
  if (parts.length !== 3) return false;

  try {
    // Decode the header and payload (base64url)
    const header = Buffer.from(parts[0], "base64").toString("utf-8");
    const payload = Buffer.from(parts[1], "base64").toString("utf-8");

    // Verify the signature
    const secret = process.env.JWT_SECRET;
    if (!secret) {
      return false;
    }

    const signature = parts[2];
    const expectedSignature = createHmac("sha256", secret)
      .update(`${parts[0]}.${parts[1]}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    return timingSafeEqual(
      Buffer.from(signature, "base64url"),
      Buffer.from(expectedSignature, "base64url")
    );
  } catch (err) {
    return false;
  }
}

function getSessionIdFromToken(token: string): string | null {
  try {
    const payload = Buffer.from(token.split(".")[1], "base64").toString("utf-8");
    const parsedPayload = JSON.parse(payload);
    return parsedPayload.sessionId || null;
  } catch (err) {
    return null;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (!(req.method === "POST" && req.path === "/login")) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader) {
    return res.status(401).json({ error: "Authorization token required" });
  }

  // Extract token from header
  const token = authHeader.startsWith("Bearer ") ? authHeader.substring(7) : authHeader;

  // Validate token format
  if (!token || !isValidToken(token)) {
    return res.status(401).json({ error: "Invalid or tampered token" });
  }

  // Get session ID from token
  const sessionId = getSessionIdFromToken(token);
  if (!sessionId) {
    return res.status(401).json({ error: "Invalid token format" });
  }

  // Check if session exists
  const session = sessionStore.get(sessionId);
  if (!session) {
    return res.status(401).json({ error: "Session not found" });
  }

  // Check if session has expired
  if (Date.now() > session.expiresAt) {
    sessionStore.delete(sessionId); // Clean up expired session
    return res.status(401).json({ error: "Session expired" });
  }

  // If we get here, the session is valid
  next();
}

