export const router = Router();

// Mock invoice data storage
let invoices: any[] = [];
let nextId = 1;

// Helper function to calculate total
const calculateTotal = (items: any[]) => {
  return items.reduce((total, item) => total + (item.price * item.quantity), 0);
};

// GET /invoices - List all invoices
router.get("/invoices", (req: Request, res: Response) => {
  res.json(invoices);
});

// GET /invoices/:id - Get one invoice by ID
router.get("/invoices/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const invoice = invoices.find(inv => inv.id === id);

  if (!invoice) {
    return res.status(404).json({ error: "Invoice not found" });
  }

  res.json(invoice);
});

// POST /invoices - Create a new invoice
router.post("/invoices", (req: Request, res: Response) => {
  const { customerName, items, dueDate } = req.body;

  // Basic validation
  if (!customerName || !items || !Array.isArray(items) || items.length === 0) {
    return res.status(400).json({ error: "Invalid invoice data" });
  }

  // Validate items
  for (const item of items) {
    if (!item.description || item.price === undefined || item.quantity === undefined) {
      return res.status(400).json({ error: "Each item must have description, price, and quantity" });
    }

    if (typeof item.price !== "number" || typeof item.quantity !== "number") {
      return res.status(400).json({ error: "Price and quantity must be numbers" });
    }

    if (item.price < 0 || item.quantity < 0) {
      return res.status(400).json({ error: "Price and quantity must be non-negative" });
    }
  }

  const total = calculateTotal(items);

  const newInvoice = {
    id: nextId++,
    customerName,
    items,
    total,
    dueDate,
    createdAt: new Date().toISOString()
  };

  invoices.push(newInvoice);

  res.status(201).json(newInvoice);
});

// PUT /invoices/:id - Update an existing invoice
router.put("/invoices/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { customerName, items, dueDate } = req.body;

  const invoiceIndex = invoices.findIndex(inv => inv.id === id);

  if (invoiceIndex === -1) {
    return res.status(404).json({ error: "Invoice not found" });
  }

  // Basic validation
  if (!customerName || !items || !Array.isArray(items) || items.length === 0) {
    return res.status(400).json({ error: "Invalid invoice data" });
  }

  // Validate items
  for (const item of items) {
    if (!item.description || item.price === undefined || item.quantity === undefined) {
      return res.status(400).json({ error: "Each item must have description, price, and quantity" });
    }

    if (typeof item.price !== "number" || typeof item.quantity !== "number") {
      return res.status(400).json({ error: "Price and quantity must be numbers" });
    }

    if (item.price < 0 || item.quantity < 0) {
      return res.status(400).json({ error: "Price and quantity must be non-negative" });
    }
  }

  const total = calculateTotal(items);

  const updatedInvoice = {
    ...invoices[invoiceIndex],
    customerName,
    items,
    total,
    dueDate
  };

  invoices[invoiceIndex] = updatedInvoice;

  res.json(updatedInvoice);
});

