import { useEffect, useState } from "react";

interface Invoice {
  id: string;
  invoiceNumber: string;
  clientName: string;
  date: string;
  status: "paid" | "pending" | "overdue";
}

export function InvoiceList() {
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [sortConfig, setSortConfig] = useState<{ key: keyof Invoice; direction: 'asc' | 'desc' } | null>(null);

  useEffect(() => {
    const fetchInvoices = async () => {
      try {
        const response = await fetch('/api/invoices');
        if (!response.ok) {
          throw new Error('Failed to fetch invoices');
        }
        const data = await response.json();
        setInvoices(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchInvoices();
  }, []);

  const handleSort = (key: keyof Invoice) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const sortedInvoices = [...invoices];
  if (sortConfig !== null) {
    sortedInvoices.sort((a, b) => {
      if (a[sortConfig.key] < b[sortConfig.key]) {
        return sortConfig.direction === 'asc' ? -1 : 1;
      }
      if (a[sortConfig.key] > b[sortConfig.key]) {
        return sortConfig.direction === 'asc' ? 1 : -1;
      }
      return 0;
    });
  }

  const filteredInvoices = sortedInvoices.filter(invoice =>
    invoice.invoiceNumber.toLowerCase().includes(searchTerm.toLowerCase()) ||
    invoice.clientName.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'paid': return '#4ade80';
      case 'pending': return '#fbbf24';
      case 'overdue': return '#f87171';
      default: return '#6b7280';
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Invoice List</h1>

      <div style={{ marginBottom: '20px' }}>
        <input
          type="text"
          placeholder="Search invoices..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{
            width: '100%',
            padding: '10px',
            borderRadius: '4px',
            border: '1px solid #ccc',
            fontSize: '16px'
          }}
        />
      </div>

      {filteredInvoices.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '20px' }}>No invoices found.</div>
      ) : (
        <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '20px' }}>
            <thead>
              <tr style={{ backgroundColor: '#f3f4f6' }}>
                <th style={{ padding: '12px', textAlign: 'left', borderBottom: '1px solid #ddd', cursor: 'pointer' }} onClick={() => handleSort('invoiceNumber')}>
                  Invoice Number
                </th>
                <th style={{ padding: '12px', textAlign: 'left', borderBottom: '1px solid #ddd', cursor: 'pointer' }} onClick={() => handleSort('clientName')}>
                  Client Name
                </th>
                <th style={{ padding: '12px', textAlign: 'left', borderBottom: '1px solid #ddd', cursor: 'pointer' }} onClick={() => handleSort('date')}>
                  Date
                </th>
                <th style={{ padding: '12px', textAlign: 'left', borderBottom: '1px solid #ddd', cursor: 'pointer' }} onClick={() => handleSort('status')}>
                  Status
                </th>
              </tr>
            </thead>
            <tbody>
              {filteredInvoices.map((invoice) => (
                <tr key={invoice.id} style={{ borderBottom: '1px solid #eee' }}>
                  <td style={{ padding: '12px' }}>{invoice.invoiceNumber}</td>
                  <td style={{ padding: '12px' }}>{invoice.clientName}</td>
                  <td style={{ padding: '12px' }}>{invoice.date}</td>
                  <td style={{ padding: '12px' }}>
                    <span style={{
                      backgroundColor: getStatusColor(invoice.status),
                      color: 'white',
                      padding: '4px 8px',
                      borderRadius: '4px',
                      fontSize: '14px'
                    }}>
                      {invoice.status.charAt(0).toUpperCase() + invoice.status.slice(1)}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from "react";

interface Client {
  id: number;
  name: string;
  email: string;
  address: string;
  phone: string;
}

export function ClientManagement() {
  const [clients, setClients] = useState<Client[]>([]);
  const [formData, setFormData] = useState<Omit<Client, "id">>({ 
    name: "", 
    email: "", 
    address: "", 
    phone: ""
  });
  const [editingId, setEditingId] = useState<number | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Load clients on component mount
  useEffect(() => {
    fetchClients();
  }, []);

  const fetchClients = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/clients");
      if (!response.ok) throw new Error("Failed to fetch clients");
      const data = await response.json();
      setClients(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const url = editingId 
        ? `/api/clients/${editingId}`
        : "/api/clients";

      const method = editingId ? "PUT" : "POST";

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData)
      });

      if (!response.ok) throw new Error("Failed to save client");

      await fetchClients();
      resetForm();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleEdit = (client: Client) => {
    setFormData({ 
      name: client.name, 
      email: client.email, 
      address: client.address, 
      phone: client.phone
    });
    setEditingId(client.id);
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/clients/${id}`, { method: "DELETE" });
      if (!response.ok) throw new Error("Failed to delete client");
      await fetchClients();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const resetForm = () => {
    setFormData({ name: "", email: "", address: "", phone: "" });
    setEditingId(null);
  };

  const formStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "12px",
    marginBottom: "24px",
    padding: "16px",
    border: "1px solid #ddd",
    borderRadius: "8px",
    backgroundColor: "#f9f9f9"
  };

  const inputStyle: React.CSSProperties = {
    padding: "8px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    fontSize: "16px",
    width: "100%"
  };

  const buttonStyle: React.CSSProperties = {
    padding: "8px 16px",
    borderRadius: "4px",
    border: "none",
    backgroundColor: "#007bff",
    color: "white",
    cursor: "pointer",
    fontSize: "16px"
  };

  const listContainerStyle: React.CSSProperties = {
    maxWidth: "800px",
    margin: "0 auto",
    fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
  };

  const clientCardStyle: React.CSSProperties = {
    padding: "16px",
    margin: "8px 0",
    border: "1px solid #ddd",
    borderRadius: "8px",
    backgroundColor: "#fff"
  };

  const buttonGroupStyle: React.CSSProperties = {
    display: "flex",
    gap: "8px",
    justifyContent: "flex-end"
  };

  if (loading) return <div style={listContainerStyle}>Loading...</div>;

  if (error) return <div style={listContainerStyle}>Error: {error}</div>;

  return (
    <div style={listContainerStyle}>
      <h1>Client Management</h1>

      <form onSubmit={handleSubmit} style={formStyle}>
        <h2>{editingId ? "Edit Client" : "Add New Client"}</h2>

        <input
          type="text"
          name="name"
          placeholder="Name"
          value={formData.name}
          onChange={handleChange}
          style={inputStyle}
        />

        <input
          type="email"
          name="email"
          placeholder="Email"
          value={formData.email}
          onChange={handleChange}
          style={inputStyle}
        />

        <textarea
          name="address"
          placeholder="Address"
          value={formData.address}
          onChange={handleChange}
          style={inputStyle}
        />

        <input
          type="tel"
          name="phone"
          placeholder="Phone"
          value={formData.phone}
          onChange={handleChange}
          style={inputStyle}
        />

        <button type="submit" style={buttonStyle}>
          {editingId ? "Update Client" : "Add Client"}
        </button>

        {editingId && (
          <button type="button" onClick={resetForm} style={{...buttonStyle, backgroundColor: "#6c757d"}}>
            Cancel
          </button>
        )}
      </form>

      <h2>Clients</h2>

      {clients.length === 0 ? (
        <p>No clients found.</p>
      ) : (
        <div>
          {clients.map(client => (
            <div key={client.id} style={clientCardStyle}>
              <h3>{client.name}</h3>
              <p><strong>Email:</strong> {client.email}</p>
              <p><strong>Address:</strong> {client.address}</p>
              <p><strong>Phone:</strong> {client.phone}</p>
              <div style={buttonGroupStyle}>
                <button 
                  onClick={() => handleEdit(client)}
                  style={{...buttonStyle, backgroundColor: "#17a2b8"}}
                >
                  Edit
                </button>
                <button 
                  onClick={() => handleDelete(client.id)}
                  style={{...buttonStyle, backgroundColor: "#dc3545"}}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

