  const [taxAmount, setTaxAmount] = useState(0);
  const [total, setTotal] = useState(0);

  // Calculate totals whenever line items or tax rate changes
  useEffect(() => {
    const newSubtotal = lineItems.reduce((sum, item) => {
      return sum + (item.quantity * item.rate);
    }, 0);

    setSubtotal(newSubtotal);

    const newTaxAmount = newSubtotal * (taxRate / 100);
    setTaxAmount(newTaxAmount);

    setTotal(newSubtotal + newTaxAmount);
  }, [lineItems, taxRate]);

  const addLineItem = () => {
    setLineItems([...lineItems, { id: Date.now().toString(), description: "", quantity: 0, rate: 0 }]);
  };

  const removeLineItem = (id: string) => {
    if (lineItems.length <= 1) return;
    setLineItems(lineItems.filter(item => item.id !== id));
  };

  const updateLineItem = (id: string, field: keyof LineItem, value: string | number) => {
    setLineItems(lineItems.map(item => 
      item.id === id ? { ...item, [field]: value } : item
    ));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // In a real app, this would send the data to a backend
    console.log({
      clientName,
