import { useState, useEffect } from "react";

interface Client {
  id: number;
  name: string;
  email: string;
  address: string;
  phone: string;
}

export function ClientManagement() {
  const [clients, setClients] = useState<Client[]>([]);
  const [formData, setFormData] = useState<Omit<Client, "id">>({ 
    name: "", 
    email: "", 
    address: "", 
    phone: ""
  });
  const [editingId, setEditingId] = useState<number | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Load clients on component mount
  useEffect(() => {
    fetchClients();
  }, []);

  const fetchClients = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/clients");
      if (!response.ok) throw new Error("Failed to fetch clients");
      const data = await response.json();
      setClients(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const url = editingId 
        ? `/api/clients/${editingId}`
        : "/api/clients";

      const method = editingId ? "PUT" : "POST";

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData)
      });

      if (!response.ok) throw new Error("Failed to save client");

      await fetchClients();
      resetForm();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleEdit = (client: Client) => {
    setFormData({ 
      name: client.name, 
      email: client.email, 
      address: client.address, 
      phone: client.phone
    });
    setEditingId(client.id);
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/clients/${id}`, { method: "DELETE" });
      if (!response.ok) throw new Error("Failed to delete client");
      await fetchClients();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const resetForm = () => {
    setFormData({ name: "", email: "", address: "", phone: "" });
    setEditingId(null);
  };

  const formStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "12px",
    marginBottom: "24px",
    padding: "16px",
    border: "1px solid #ddd",
    borderRadius: "8px",
    backgroundColor: "#f9f9f9"
  };

  const inputStyle: React.CSSProperties = {
    padding: "8px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    fontSize: "16px",
    width: "100%"
  };

  const buttonStyle: React.CSSProperties = {
    padding: "8px 16px",
    borderRadius: "4px",
    border: "none",
    backgroundColor: "#007bff",
    color: "white",
    cursor: "pointer",
    fontSize: "16px"
  };

  const listContainerStyle: React.CSSProperties = {
    maxWidth: "800px",
    margin: "0 auto",
    fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
  };

  const clientCardStyle: React.CSSProperties = {
    padding: "16px",
    margin: "8px 0",
    border: "1px solid #ddd",
    borderRadius: "8px",
    backgroundColor: "#fff"
  };

  const buttonGroupStyle: React.CSSProperties = {
    display: "flex",
    gap: "8px",
    justifyContent: "flex-end"
  };

  if (loading) return <div style={listContainerStyle}>Loading...</div>;

  if (error) return <div style={listContainerStyle}>Error: {error}</div>;

  return (
    <div style={listContainerStyle}>
      <h1>Client Management</h1>

      <form onSubmit={handleSubmit} style={formStyle}>
        <h2>{editingId ? "Edit Client" : "Add New Client"}</h2>

        <input
          type="text"
          name="name"
          placeholder="Name"
          value={formData.name}
          onChange={handleChange}
          style={inputStyle}
        />

        <input
          type="email"
          name="email"
          placeholder="Email"
          value={formData.email}
          onChange={handleChange}
          style={inputStyle}
        />

        <textarea
          name="address"
          placeholder="Address"
          value={formData.address}
          onChange={handleChange}
          style={inputStyle}
        />

        <input
          type="tel"
          name="phone"
          placeholder="Phone"
          value={formData.phone}
          onChange={handleChange}
          style={inputStyle}
        />

        <button type="submit" style={buttonStyle}>
          {editingId ? "Update Client" : "Add Client"}
        </button>

        {editingId && (
          <button type="button" onClick={resetForm} style={{...buttonStyle, backgroundColor: "#6c757d"}}>
            Cancel
          </button>
        )}
      </form>

      <h2>Clients</h2>

      {clients.length === 0 ? (
        <p>No clients found.</p>
      ) : (
        <div>
          {clients.map(client => (
            <div key={client.id} style={clientCardStyle}>
              <h3>{client.name}</h3>
              <p><strong>Email:</strong> {client.email}</p>
              <p><strong>Address:</strong> {client.address}</p>
              <p><strong>Phone:</strong> {client.phone}</p>
              <div style={buttonGroupStyle}>
                <button 
                  onClick={() => handleEdit(client)}
                  style={{...buttonStyle, backgroundColor: "#17a2b8"}}
                >
                  Edit
                </button>
                <button 
                  onClick={() => handleDelete(client.id)}
                  style={{...buttonStyle, backgroundColor: "#dc3545"}}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  {
    id: 1,
    username: "admin",
    password: "admin123",
    role: "admin"
  },
  {
    id: 2,
    username: "resident",
    password: "resident123",
    role: "resident"
  }
];

// Registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role } = req.body;

  // Validate input
  if (!username || !password || !role) {
    return res.status(400).json({ message: "Username, password, and role are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ message: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    username,
    password,
    role
  };

  users.push(newUser);

  return res.status(201).json(newUser);
});

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  // Validate input
  if (!username || !password) {
    return res.status(400).json({ message: "Username and password are required" });
  }

  // Find user
  const user = users.find(u => u.username === username && u.password === password);
  if (!user) {
    return res.status(401).json({ message: "Invalid credentials" });
  }

  // Return user info (excluding password)
  const { password: _, ...userWithoutPassword } = user;
  return res.json(userWithoutPassword);
});

// Role-based access control middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    const userRole = (req as any).user?.role;
    if (!userRole || !roles.includes(userRole)) {
      return res.status(403).json({ message: "Insufficient permissions" });
    }
    next();
  };
};

// Protected route example
router.get("/admin", authorize(["admin"]), (req: Request, res: Response) => {
  return res.json({ message: "Admin access granted" });
});

