import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "No token provided" });
  }

  if (!process.env.JWT_SECRET) {
    return res.status(500).json({ error: "Server configuration error" });
  }

  const parts = token.split(".");
  if (parts.length !== 3) {
    return res.status(401).json({ error: "Invalid token format" });
  }

  const [header, payload, signature] = parts;
  const expectedSignature = createHmac("sha256", process.env.JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  const signatureBuffer = Buffer.from(signature, "base64url");
  const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

  try {
    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      return res.status(401).json({ error: "Invalid token signature" });
    }
  } catch {
    return res.status(401).json({ error: "Invalid token signature" });
  }

  // Basic token validation (check expiration and timeout)
  try {
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
    const now = Math.floor(Date.now() / 1000);
    if (decodedPayload.exp < now) {
      return res.status(401).json({ error: "Token expired" });
    }
    if (decodedPayload.timeout < now) {
      return res.status(401).json({ error: "Session timeout" });
    }
  } catch {
    return res.status(401).json({ error: "Invalid token" });
  }

  next();
}

