import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database - in a real app this would be a proper database
const users: { id: number; username: string; password: string }[] = [];
let nextId = 1;

// Mock session storage - in a real app this would be a proper session store
const sessions: { sessionId: string; userId: number }[] = [];

// Helper to generate a simple session ID
const generateSessionId = (): string => {
  return Math.random().toString(36).substring(2, 15);
};

// Registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { username, password } = req.body;

  // Validate input
  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "Username already exists" });
  }

  // Create new user
  const newUser = {
    id: nextId++,
    username,
    password
  };

  users.push(newUser);

  // Return success response
  return res.status(201).json({ message: "User registered successfully" });
});

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  // Validate input
  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Find user
  const user = users.find(u => u.username === username && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate session
  const sessionId = generateSessionId();
  sessions.push({ sessionId, userId: user.id });

  // Set session cookie
  res.cookie("sessionId", sessionId, { httpOnly: true, secure: false });

  // Return success response
  return res.json({ message: "Login successful" });
});

// Logout endpoint
router.post("/logout", (req: Request, res: Response) => {
  // In a real app, you'd invalidate the session
  // For now, we'll just clear the cookie
  res.clearCookie("sessionId");
  return res.json({ message: "Logout successful" });
});

