    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT_SECRET not configured" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify the JWT properly
  // For this example, we'll just check if it matches a known valid token format
  try {
    // This is a simplified version - in practice, you'd want proper JWT verification
    const expectedSignature = createHmac("sha256", secret)
      .update(token.split(".")[0] + "." + token.split(".")[1])
      .digest();

    const providedSignature = Buffer.from(token.split(".")[2], "base64");

    if (expectedSignature.length !== providedSignature.length || 
        !timingSafeEqual(expectedSignature, providedSignature)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  // In a real implementation, you would decode the token to get user roles
  // For now, we'll assume the token contains role information in a standard way
  // This is a placeholder - actual JWT decoding would be more complex
  const decodedToken = token.split(".")[1];
  let userRole = "user"; // Default role

  try {
    const payload = JSON.parse(Buffer.from(decodedToken, "base64").toString());
    userRole = payload.role || "user";
  } catch (err) {
    // If we can't parse the token, treat as regular user
  }

  // Allow users to delete their own comments, but only admins/moderators can delete others
  if (userRole === "admin" || userRole === "moderator") {
    next();
  } else {
    res.status(403).json({ error: "Forbidden: Insufficient permissions to delete comment" });
  }
}

