          value={comment}
          onChange={(e) => setComment(e.target.value)}
          placeholder="Write your comment here..."
          style={{
            width: "100%",
            padding: "10px",
            borderRadius: "4px",
            border: "1px solid #ccc",
            fontFamily: "inherit",
            minHeight: "100px"
          }}
          required
        />
        <button
          type="submit"
