export const router = Router();

// Mock habit data storage
let habits = [
  { id: 1, name: "Morning Meditation", description: "10 minutes daily", completed: false },
  { id: 2, name: "Drink Water", description: "8 glasses per day", completed: true }
];

let nextId = 3;

// Get all habits
router.get("/", (req: Request, res: Response) => {
  res.json(habits);
});

// Get habit by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const habit = habits.find(h => h.id === id);

  if (!habit) {
    return res.status(404).json({ error: "Habit not found" });
  }

  res.json(habit);
});

// Create new habit
router.post("/", (req: Request, res: Response) => {
  const { name, description } = req.body;

  if (!name) {
    return res.status(400).json({ error: "Name is required" });
  }

  const newHabit = {
    id: nextId++,
    name,
    description: description || "",
    completed: false
  };

  habits.push(newHabit);
  res.status(201).json(newHabit);
});

// Update habit
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { name, description, completed } = req.body;

  const habitIndex = habits.findIndex(h => h.id === id);

  if (habitIndex === -1) {
    return res.status(404).json({ error: "Habit not found" });
  }

  if (name !== undefined) {
    habits[habitIndex].name = name;
  }

  if (description !== undefined) {
    habits[habitIndex].description = description;
  }

  if (completed !== undefined) {
    habits[habitIndex].completed = completed;
  }

  res.json(habits[habitIndex]);
});

// Delete habit
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const habitIndex = habits.findIndex(h => h.id === id);

  if (habitIndex === -1) {
    return res.status(404).json({ error: "Habit not found" });
  }

  habits.splice(habitIndex, 1);
  res.json({ message: "Habit deleted successfully" });
});

