import { useEffect, useState } from "react";

interface Habit {
  id: string;
  name: string;
  description: string;
  streak: number;
  history: {
    date: string;
    completed: boolean;
  }[];
}

export function HabitDetail({
  habitId,
}: {
  habitId: string;
}) {
  const [habit, setHabit] = useState<Habit | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchHabit = async () => {
      try {
        const response = await fetch(`/api/habits/${habitId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch habit: ${response.status}`);
        }
        const habitData = await response.json();
        setHabit(habitData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchHabit();
  }, [habitId]);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (!habit) {
    return <div style={{ textAlign: "center", padding: "20px" }}>No habit found</div>;
  }

  return (
    <div
      style={{
        maxWidth: "600px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>{habit.name}</h1>
      <p style={{ textAlign: "center", color: "#666" }}>{habit.description}</p>

      <div style={{ textAlign: "center", margin: "20px 0" }}>
        <span style={{ fontSize: "24px", fontWeight: "bold", color: "#4CAF50" }}>
          {habit.streak} day streak
        </span>
      </div>

      <h2 style={{ marginTop: "30px" }}>History</h2>
      <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
        {habit.history.length === 0 ? (
          <p>No history available</p>
        ) : (
          habit.history.map((entry, index) => (
            <div
              key={index}
              style={{
                border: "1px solid #ddd",
                borderRadius: "8px",
                padding: "10px",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              <span>{new Date(entry.date).toLocaleDateString()}</span>
              <span
                style={{
                  backgroundColor: entry.completed ? "#4CAF50" : "#f44336",
                  color: "white",
