interface ChartPoint {
  date: string;
  completed: number;
}

export function ProgressChart() {
  const [chartData, setChartData] = useState<ChartPoint[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // Simulate fetching habit data
    const fetchData = async () => {
      try {
        // In a real app, this would be an API call
        // const response = await fetch('/api/habits');
        // const data = await response.json();

        // Mock data for demonstration
        const mockData: HabitData[] = [
          { date: '2023-05-01', completed: true },
          { date: '2023-05-02', completed: false },
          { date: '2023-05-03', completed: true },
          { date: '2023-05-04', completed: true },
          { date: '2023-05-05', completed: false },
          { date: '2023-05-06', completed: true },
          { date: '2023-05-07', completed: true },
        ];

        // Process data into chart format
        const processedData: ChartPoint[] = [];
        const today = new Date();

        for (let i = 6; i >= 0; i--) {
          const date = new Date(today);
          date.setDate(date.getDate() - i);
          const dateString = date.toISOString().split('T')[0];

          const dayData = mockData.find(d => d.date === dateString);
          const completed = dayData ? (dayData.completed ? 1 : 0) : 0;

          processedData.push({
            date: dateString,
            completed
          });
        }

        setChartData(processedData);
        setLoading(false);
      } catch (err) {
        setError('Failed to load progress data');
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      <h1 style={{ textAlign: 'center' }}>Habit Completion Progress</h1>

      <div style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'flex-end',
        height: '200px',
        marginTop: '30px',
        border: '1px solid #ddd',
        borderRadius: '8px',
        padding: '10px',
        backgroundColor: '#f9f9f9'
      }}>
        {chartData.map((point, index) => {
          const heightPercentage = point.completed * 100;
          const dateObj = new Date(point.date);
          const dayOfWeek = dateObj.toLocaleDateString('en-US', { weekday: 'short' });
          const monthDay = dateObj.getDate();

          return (
            <div key={index} style={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              height: '100%',
              flex: '1 1 0',
              margin: '0 2px'
            }}>
              <div style={{
                width: '100%',
                height: `${heightPercentage}%`,
