import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const isDonationRoute = req.path.startsWith('/donations') && (req.method === 'GET' || req.method === 'POST' || req.method === 'PUT' || req.method === 'DELETE');
  const isRequestRoute = req.path.startsWith('/requests') && (req.method === 'GET' || req.method === 'POST' || req.method === 'PUT' || req.method === 'DELETE');

  if (!isDonationRoute && !isRequestRoute) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Unauthorized: Missing or invalid authorization header' });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: 'Server configuration error: JWT_SECRET not set' });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  const expectedSignature = createHmac('sha256', secret)
    .update(token.split('.')[0] + '.' + token.split('.')[1])
    .digest();

  const actualSignature = Buffer.from(token.split('.')[2], 'base64');

  try {
    if (timingSafeEqual(expectedSignature, actualSignature)) {
      // Token is valid, proceed with role checking
      const userRole = req.headers['x-user-role'] as string;
      const userId = req.headers['x-user-id'] as string;

      if (!userRole || !userId) {
        res.status(401).json({ error: 'Unauthorized: Missing user role or ID' });
        return;
      }

      // Validate access based on role and resource ownership
      if (isDonationRoute) {
        if (userRole === 'restaurant') {
          // For restaurant donations, check if the donation belongs to this restaurant
          const donationId = req.params.id;
          // In a real implementation, we would fetch the donation and compare owner IDs
          // For now, we'll just allow access
          next();
        } else if (userRole === 'ngo') {
          // NGOs should not be able to manage donations
          res.status(403).json({ error: 'Forbidden: NGOs cannot manage donations' });
          return;
        } else {
          res.status(403).json({ error: 'Forbidden: Unauthorized role' });
          return;
        }
      } else if (isRequestRoute) {
        if (userRole === 'ngo') {
          // For NGO requests, check if the request belongs to this NGO
          const requestId = req.params.id;
          // In a real implementation, we would fetch the request and compare owner IDs
          // For now, we'll just allow access
          next();
        } else if (userRole === 'restaurant') {
          // Restaurants should not be able to manage requests
          res.status(403).json({ error: 'Forbidden: Restaurants cannot manage requests' });
          return;
        } else {
          res.status(403).json({ error: 'Forbidden: Unauthorized role' });
          return;
        }
      }
    } else {
      res.status(401).json({ error: 'Unauthorized: Invalid token signature' });
      return;
    }
  } catch (error) {
    res.status(401).json({ error: 'Unauthorized: Invalid token' });
    return;
  }
}

