];

const mentees = [
  {
    id: 1,
    name: "Charlie Brown",
    expertise: ["JavaScript", "React"],
    interests: ["Web Development", "UI/UX"],
    availability: ["Monday", "Friday"]
  },
  {
    id: 2,
    name: "Diana Prince",
    expertise: ["Python", "Flask"],
    interests: ["Backend Development", "Machine Learning"],
    availability: ["Tuesday", "Saturday"]
  }
];

// Match mentors and mentees based on compatibility factors
router.get("/match", (req: Request, res: Response) => {
  // Get query parameters
  const { expertiseWeight = 0.4, interestWeight = 0.3, availabilityWeight = 0.3 } = req.query;

  // Convert weights to numbers
  const weight1 = Number(expertiseWeight);
  const weight2 = Number(interestWeight);
  const weight3 = Number(availabilityWeight);

  // Validate weights
  if (isNaN(weight1) || isNaN(weight2) || isNaN(weight3)) {
    return res.status(400).json({ error: "Invalid weight values provided." });
  }

  if (weight1 + weight2 + weight3 !== 1) {
    return res.status(400).json({ error: "Weights must sum to 1." });
  }

  // Initialize array to store matches
  const matches: Array<{ mentorId: number; menteeId: number; score: number }> = [];

  // Iterate through each mentor and mentee combination
  mentors.forEach(mentor => {
    mentees.forEach(mentee => {
      // Calculate expertise match
      const expertiseMatch = mentor.expertise.filter((expertise: string) => mentee.expertise.includes(expertise));
      const expertiseScore = expertiseMatch.length / Math.max(mentor.expertise.length, mentee.expertise.length);

      // Calculate interest match
      const interestMatch = mentor.interests.filter((interest: string) => mentee.interests.includes(interest));
      const interestScore = interestMatch.length / Math.max(mentor.interests.length, mentee.interests.length);

      // Calculate availability match
      const availabilityMatch = mentor.availability.filter((day: string) => mentee.availability.includes(day));
      const availabilityScore = availabilityMatch.length / Math.max(mentor.availability.length, mentee.availability.length);

      // Calculate overall score
      const score = weight1 * expertiseScore + weight2 * interestScore + weight3 * availabilityScore;

      // Add match to results
      matches.push({
        mentorId: mentor.id,
        menteeId: mentee.id,
        score
      });
    });
  });

  // Sort matches by score descending
  matches.sort((a, b) => b.score - a.score);

  // Return top matches
  return res.json(matches);
});

