import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;

  if (!jwtSecret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // In a real implementation, we would verify the JWT token here
  // For now, we'll just simulate the verification process
  // This is a placeholder implementation

  // Simulate token verification
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    res.status(401).json({ error: "No token provided" });
    return;
  }

  try {
    // In a real implementation, we would decode and verify the JWT token
    // This is a simplified version for demonstration purposes

    // Verify the token signature using HMAC-SHA256
    const secretBuffer = Buffer.from(jwtSecret);
    const tokenParts = token.split(".");

    if (tokenParts.length < 2) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const headerAndPayload = tokenParts[0] + "." + tokenParts[1];
    const expectedSignature = createHmac("sha256", secretBuffer)
      .update(headerAndPayload)
      .digest("base64url");

    const actualSignature = tokenParts[2];

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(expectedSignature),
      Buffer.from(actualSignature)
    );

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // If we get here, the token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Token verification failed" });
  }
}

