  if (!req.path.startsWith('/api/profile') && !req.path.startsWith('/api/messages')) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: 'Server configuration error' });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify properly
  // For this implementation, we'll just check basic structure
  const parts = token.split('.');
  if (parts.length !== 3) {
    res.status(401).json({ error: 'Invalid token format' });
    return;
  }

  try {
    // In a real implementation, we would verify the signature here
    // This is a simplified version for demonstration purposes
    const payload = JSON.parse(Buffer.from(parts[1], 'base64').toString());

    // Check if user has proper role for the requested resource
    if (req.path.startsWith('/api/profile')) {
      // Profile access should be restricted to the owner
      const userIdFromToken = payload.userId;
      const userIdFromPath = req.params.id;

      if (userIdFromToken !== userIdFromPath) {
        res.status(403).json({ error: 'Forbidden: Access denied' });
        return;
      }
    }

    if (req.path.startsWith('/api/messages')) {
      // Message access should be restricted to the owner
      const userIdFromToken = payload.userId;
      const userIdFromPath = req.params.userId;

      if (userIdFromToken !== userIdFromPath) {
        res.status(403).json({ error: 'Forbidden: Access denied' });
        return;
      }
    }

    next();
  } catch (error) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

