import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes
const AUTH_HEADER_PREFIX = "Bearer ";

interface SessionData {
  userId: string;
  sessionId: string;
  createdAt: number;
}

// In-memory storage for sessions (in production, use Redis or similar)
const activeSessions = new Map<string, SessionData>();

function verifyTokenSignature(token: string, secret: string): boolean {
  const [header, payload, signature] = token.split(".");
  if (!header || !payload || !signature) return false;

  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");
    return timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests with a body (assuming this is for login)
  if (req.method !== "POST" || !req.body) {
    return next();
  }

  const authHeader = req.header("Authorization");
  if (!authHeader || !authHeader.startsWith(AUTH_HEADER_PREFIX)) {
    return next();
  }

  const token = authHeader.substring(AUTH_HEADER_PREFIX.length);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    return next();
  }

  if (!verifyTokenSignature(token, secret)) {
    return next();
  }

  // Parse the token (simplified - in reality, decode without verification first)
  try {
    const [_, payload] = token.split(".");
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
    const { userId, sessionId, createdAt } = decodedPayload;

    if (!userId || !sessionId || !createdAt) {
      return next();
    }

    const session = activeSessions.get(sessionId);
    if (!session) {
      return next();
    }

    if (Date.now() - session.createdAt > SESSION_TIMEOUT) {
      activeSessions.delete(sessionId);
      return next();
    }

    // Update session timestamp
    activeSessions.set(sessionId, {
      ...session,
      createdAt: Date.now()
    });

    // Attach user info to request
    (req as any).user = { userId, sessionId };

    return next();
  } catch (err) {
    return next();
  }
}

import { useEffect, useState } from "react";

interface Patient {
  id: number;
  firstName: string;
  lastName: string;
  dateOfBirth: string;
  gender: string;
  address: string;
  phoneNumber: string;
}

export function PatientManagementPage() {
  const [patients, setPatients] = useState<Patient[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchPatients();
  }, []);

  const fetchPatients = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/patients`);
      if (!response.ok) {
        throw new Error(`Failed to fetch patients: ${response.status}`);
      }
      const data = await response.json();
      setPatients(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const filteredPatients = patients.filter(patient =>
    patient.firstName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    patient.lastName.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleDelete = async (id: number) => {
    if (!window.confirm("Are you sure you want to delete this patient?")) return;

    try {
      const response = await fetch(`/api/patients/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to delete patient: ${response.status}`);
      }
      fetchPatients(); // Refresh the list
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Patient Management</h1>

      <div style={{ marginBottom: "20px", display: "flex", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search patients..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ flex: 1, padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        />
        <a href="/patients/new" style={{ padding: "10px 20px", backgroundColor: "#007bff", color: "white", textDecoration: "none", borderRadius: "4px", fontWeight: "bold" }}>
          Add New Patient
        </a>
      </div>

      {filteredPatients.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No patients found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {filteredPatients.map((patient) => (
            <div key={patient.id} style={{ border: "1px solid #ddd", borderRadius: "8px", padding: "15px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <h3>{patient.firstName} {patient.lastName}</h3>
                <p><strong>DOB:</strong> {patient.dateOfBirth}</p>
                <p><strong>Gender:</strong> {patient.gender}</p>
                <p><strong>Address:</strong> {patient.address}</p>
                <p><strong>Phone:</strong> {patient.phoneNumber}</p>
              </div>
              <div style={{ display: "flex", gap: "10px" }}>
                <a 
                  href={`/patients/${patient.id}/edit`} 
                  style={{ padding: "8px 12px", backgroundColor: "#28a745", color: "white", textDecoration: "none", borderRadius: "4px" }}
                >
                  Edit
                </a>
                <button 
                  onClick={() => handleDelete(patient.id)}
                  style={{ padding: "8px 12px", backgroundColor: "#dc3545", color: "white", border: "none", borderRadius: "4px" }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

