import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes
const AUTH_HEADER_PREFIX = "Bearer ";

interface SessionData {
  userId: string;
  sessionId: string;
  createdAt: number;
}

// In-memory storage for sessions (in production, use Redis or similar)
const activeSessions = new Map<string, SessionData>();

function verifyTokenSignature(token: string, secret: string): boolean {
  const [header, payload, signature] = token.split(".");
  if (!header || !payload || !signature) return false;

  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");
    return timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests with a body (assuming this is for login)
  if (req.method !== "POST" || !req.body) {
    return next();
  }

  const authHeader = req.header("Authorization");
  if (!authHeader || !authHeader.startsWith(AUTH_HEADER_PREFIX)) {
    return next();
  }

  const token = authHeader.substring(AUTH_HEADER_PREFIX.length);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    return next();
  }

  if (!verifyTokenSignature(token, secret)) {
    return next();
  }

  // Parse the token (simplified - in reality, decode without verification first)
  try {
    const [_, payload] = token.split(".");
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
    const { userId, sessionId, createdAt } = decodedPayload;

    if (!userId || !sessionId || !createdAt) {
      return next();
    }

    const session = activeSessions.get(sessionId);
    if (!session) {
      return next();
    }

    if (Date.now() - session.createdAt > SESSION_TIMEOUT) {
      activeSessions.delete(sessionId);
      return next();
    }

    // Update session timestamp
    activeSessions.set(sessionId, {
      ...session,
      createdAt: Date.now()
    });

    // Attach user info to request
    (req as any).user = { userId, sessionId };

    return next();
  } catch (err) {
    return next();
  }
}

