  { id: 2, title: "Parking Issue", description: "Illegal parking", status: "Closed", date: "2023-01-02" }
];

let nextId = 3;

// GET /complaints - List all complaints
router.get("/complaints", (req: Request, res: Response) => {
  res.json(complaints);
});

// GET /complaints/:id - Get one complaint by ID
router.get("/complaints/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const complaint = complaints.find(c => c.id === id);

  if (!complaint) {
    return res.status(404).json({ error: "Complaint not found" });
  }

  res.json(complaint);
});

// POST /complaints - Create a new complaint
router.post("/complaints", (req: Request, res: Response) => {
  const { title, description, status, date } = req.body;

  // Basic validation
  if (!title || !description || !status || !date) {
    return res.status(400).json({ error: "Title, description, status, and date are required" });
  }

  const newComplaint = {
    id: nextId++,
    title,
    description,
    status,
    date
  };

  complaints.push(newComplaint);
  res.status(201).json(newComplaint);
});

// PUT /complaints/:id - Update a complaint
router.put("/complaints/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { title, description, status, date } = req.body;

  const complaintIndex = complaints.findIndex(c => c.id === id);

  if (complaintIndex === -1) {
    return res.status(404).json({ error: "Complaint not found" });
  }

  // Basic validation
  if (!title || !description || !status || !date) {
    return res.status(400).json({ error: "Title, description, status, and date are required" });
  }

  complaints[complaintIndex] = {
    id,
    title,
    description,
    status,
    date
  };

  res.json(complaints[complaintIndex]);
});

// DELETE /complaints/:id - Delete a complaint
router.delete("/complaints/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const complaintIndex = complaints.findIndex(c => c.id === id);

  if (complaintIndex === -1) {
    return res.status(404).json({ error: "Complaint not found" });
  }

  complaints.splice(complaintIndex, 1);
  res.json({ message: "Complaint deleted successfully" });
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to complaint-related routes
  if (!req.path.startsWith("/complaints")) {
    next();
    return;
  }

  // For demonstration purposes, we'll simulate role checking
  // In a real implementation, this would check actual user roles from a token or session

  // Simulate a basic role check - in reality this would come from authenticated user context
  const userRole = req.headers["x-user-role"] as string || "public";

  // Define role permissions
  const permissions: Record<string, string[]> = {
    admin: ["GET", "POST", "PUT", "DELETE"],
    officer: ["GET", "POST", "PUT"],
    public: ["GET"]
  };

  const allowedMethods = permissions[userRole] || [];

  // Allow access if user has appropriate role for the HTTP method
  if (allowedMethods.includes(req.method)) {
    next();
    return;
  }

  // If user doesn't have permission, send forbidden response
  res.status(403).json({ error: "Forbidden: Insufficient permissions" });
}

import type { Request, Response, NextFunction } from "express";
import { createHash, randomBytes } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to the /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  // Hash the password using SHA-256 with a salt
  const salt = randomBytes(32).toString("hex");
  const hashedPassword = createHash("sha256")
    .update(req.body.password + salt)
    .digest("hex");

  // Replace the password with the hashed version and add salt
  req.body.hashedPassword = hashedPassword;
  req.body.salt = salt;
  delete req.body.password;

  next();
}

