import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  const protectedPaths = [
    /^\/residents\/.+/, // All resident-related routes
    /^\/care-plans\/.+/, // All care plan routes
    /^\/staff\/.+/, // All staff-related routes
  ];

  const isProtectedPath = protectedPaths.some(path => path.test(req.path));

  // Skip RBAC for non-protected paths
  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  // If no role header, deny access
  if (!userRole) {
    res.status(403).json({ error: "Access denied: Role not provided" });
    return;
  }

  // Define role requirements for different endpoints
  const roleRequirements: Record<string, string[]> = {
    "/residents": ["admin", "nurse", "caregiver"],
    "/care-plans": ["admin", "nurse"],
    "/staff": ["admin"],
  };

  // Determine required role based on endpoint
  let requiredRoles: string[] = [];

  // Check for specific endpoint matches
  if (req.path.startsWith("/residents/")) {
    requiredRoles = ["admin", "nurse", "caregiver"];
  } else if (req.path.startsWith("/care-plans/")) {
    requiredRoles = ["admin", "nurse"];
  } else if (req.path.startsWith("/staff/")) {
    requiredRoles = ["admin"];
  } else {
    // For general protected paths
    requiredRoles = ["admin", "nurse", "caregiver"];
  }

  // Validate user role
  if (!requiredRoles.includes(userRole)) {
    res.status(403).json({ error: "Access denied: Insufficient permissions" });
    return;
  }

  // If we get here, user has proper role
  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHash, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to the /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  // Hash the password using SHA-256
  const hashedPassword = createHash("sha256").update(req.body.password).digest("hex");

  // Replace the plain text password with the hashed version
  req.body.password = hashedPassword;

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// In-memory storage for sessions (in production, use a proper database)
const sessions = new Map<string, { userId: string; expiresAt: number }>();

// Helper to generate a secure token
function generateToken(userId: string): string {
  const timestamp = Date.now().toString();
  const payload = `${userId}.${timestamp}`;
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    throw new Error("JWT_SECRET environment variable is not set");
  }

  const signature = createHmac("sha256", secret)
    .update(payload)
    .digest("hex");

  return `${payload}.${signature}`;
}

// Helper to verify token signature
function verifyToken(token: string): { userId: string; isValid: boolean } | null {
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    return null;
  }

  try {
    const [payload, signature] = token.split(".");
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("hex");

    const expectedBuffer = Buffer.from(expectedSignature);
    const actualBuffer = Buffer.from(signature);

    const isValid = timingSafeEqual(expectedBuffer, actualBuffer);

    if (!isValid) {
      return { userId: "", isValid: false };
    }

    const [userId, timestamp] = payload.split(".");
    const expiresAt = parseInt(timestamp) + 30 * 60 * 1000; // 30 minutes expiry

    return { userId, isValid: true };
  } catch (err) {
    return { userId: "", isValid: false };
  }
}

// Middleware function
export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "No token provided" });
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  const verificationResult = verifyToken(token);

  if (!verificationResult) {
    return res.status(401).json({ error: "Invalid token" });
  }

  if (!verificationResult.isValid) {
    return res.status(401).json({ error: "Invalid token" });
  }

  const { userId } = verificationResult;

  // Check if session exists and is valid
  const session = sessions.get(token);

  if (!session) {
    return res.status(401).json({ error: "Session not found" });
  }

  if (Date.now() > session.expiresAt) {
    sessions.delete(token);
    return res.status(401).json({ error: "Session expired" });
  }

  // Attach user info to request object
  (req as any).user = { id: userId };

  next();
}

