              {residents.map(resident => (
                <option key={resident.id} value={resident.id}>{resident.name}</option>
              ))}
            </select>
          </div>

          <div>
            <label>Activity Type:</label>
            <select
              name="activityType"
              value={formData.activityType}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px', marginTop: '5px' }}
              required
            >
              <option value="">Select Type</option>
              <option value="Medication">Medication</option>
              <option value="Meal">Meal</option>
              <option value="Therapy">Therapy</option>
              <option value="Other">Other</option>
            </select>
          </div>

          <div>
            <label>Staff Member:</label>
            <select
              name="staffId"
              value={formData.staffId}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px', marginTop: '5px' }}
              required
            >
              <option value="">Select Staff</option>
              {staff.map(member => (
                <option key={member.id} value={member.id}>{member.name}</option>
              ))}
            </select>
          </div>

          <div>
            <label>Notes:</label>
            <textarea
              name="notes"
              value={formData.notes}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px', marginTop: '5px', minHeight: '60px' }}
            />
          </div>

          <button 
            type="submit" 
            style={{ 
              padding: '10px 15px', 
              backgroundColor: '#007bff', 
              color: 'white', 
              border: 'none', 
              borderRadius: '4px', 
              cursor: 'pointer' 
            }}
          >
            Log Activity
          </button>
        </form>
      </div>

      <div>
        <h2>Recent Activities</h2>
        {activities.length === 0 ? (
          <p style={{ textAlign: 'center', padding: '20px' }}>No activities logged yet.</p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
            {activities.map(activity => {
              const resident = residents.find(r => r.id === activity.residentId);
              const staffMember = staff.find(s => s.id === activity.staffId);

              return (
                <div 
                  key={activity.id} 
                  style={{ 
                    border: '1px solid #ddd', 
                    borderRadius: '8px', 
                    padding: '15px', 
                    backgroundColor: '#f9f9f9' 
                  }}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                    <strong>{activity.activityType}</strong>
                    <span>{new Date(activity.timestamp).toLocaleString()}</span>
                  </div>
                  <div style={{ marginTop: '10px' }}>
                    <p><strong>Resident:</strong> {resident?.name || 'Unknown'}</p>
                    <p><strong>Staff:</strong> {staffMember?.name || 'Unknown'}</p>
                    <p><strong>Notes:</strong> {activity.notes}</p>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

