import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// In-memory storage for sessions (in production, use a proper database)
const sessions = new Map<string, { userId: string; expiresAt: number }>();

// Helper to generate a secure token
function generateToken(userId: string): string {
  const timestamp = Date.now().toString();
  const payload = `${userId}.${timestamp}`;
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    throw new Error("JWT_SECRET environment variable is not set");
  }

  const signature = createHmac("sha256", secret)
    .update(payload)
    .digest("hex");

  return `${payload}.${signature}`;
}

// Helper to verify token signature
function verifyToken(token: string): { userId: string; isValid: boolean } | null {
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    return null;
  }

  try {
    const [payload, signature] = token.split(".");
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("hex");

    const expectedBuffer = Buffer.from(expectedSignature);
    const actualBuffer = Buffer.from(signature);

    const isValid = timingSafeEqual(expectedBuffer, actualBuffer);

    if (!isValid) {
      return { userId: "", isValid: false };
    }

    const [userId, timestamp] = payload.split(".");
    const expiresAt = parseInt(timestamp) + 30 * 60 * 1000; // 30 minutes expiry

    return { userId, isValid: true };
  } catch (err) {
    return { userId: "", isValid: false };
  }
}

// Middleware function
export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "No token provided" });
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  const verificationResult = verifyToken(token);

  if (!verificationResult) {
    return res.status(401).json({ error: "Invalid token" });
  }

  if (!verificationResult.isValid) {
    return res.status(401).json({ error: "Invalid token" });
  }

  const { userId } = verificationResult;

  // Check if session exists and is valid
  const session = sessions.get(token);

  if (!session) {
    return res.status(401).json({ error: "Session not found" });
  }

  if (Date.now() > session.expiresAt) {
    sessions.delete(token);
    return res.status(401).json({ error: "Session expired" });
  }

  // Attach user info to request object
  (req as any).user = { id: userId };

  next();
}

