        type="text"
        placeholder="Search books..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
        style={inputStyle}
      />
      <div style={bookListStyle}>
        {filteredBooks.length > 0 ? (
          filteredBooks.map(book => (
            <div key={book.id} style={cardStyle}>
              <h3>{book.title}</h3>
