import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockReviews = [
  { id: 1, productId: 1, customerId: 1, rating: 5, comment: "Great product!" },
  { id: 2, productId: 1, customerId: 2, rating: 4, comment: "Good value." }
];

const findReviewById = (id: number) => {
  return mockReviews.find(review => review.id === id);
};

const createReview = (review: any) => {
  const newId = Math.max(0, ...mockReviews.map(r => r.id)) + 1;
  const newReview = { ...review, id: newId };
  mockReviews.push(newReview);
  return newReview;
};

const updateReview = (id: number, updatedFields: any) => {
  const index = mockReviews.findIndex(review => review.id === id);
  if (index === -1) return null;
  mockReviews[index] = { ...mockReviews[index], ...updatedFields };
  return mockReviews[index];
};

const deleteReview = (id: number) => {
  const index = mockReviews.findIndex(review => review.id === id);
  if (index === -1) return false;
  mockReviews.splice(index, 1);
  return true;
};

// List all reviews
router.get("/", (req: Request, res: Response) => {
  res.json(mockReviews);
});

// Get a specific review by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid review ID" });
  }

  const review = findReviewById(id);
  if (!review) {
    return res.status(404).json({ error: "Review not found" });
  }

  res.json(review);
});

// Create a new review
router.post("/", (req: Request, res: Response) => {
  const { productId, customerId, rating, comment } = req.body;

  if (!productId || !customerId || !rating || !comment) {
    return res.status(400).json({ error: "Missing required fields: productId, customerId, rating, comment" });
  }

  if (typeof rating !== "number" || rating < 1 || rating > 5) {
    return res.status(400).json({ error: "Rating must be a number between 1 and 5" });
  }

  const newReview = createReview({ productId, customerId, rating, comment });
  res.status(201).json(newReview);
});

// Update an existing review
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid review ID" });
  }

  const { rating, comment } = req.body;

  if ((rating !== undefined && typeof rating !== "number") || (rating && (rating < 1 || rating > 5))) {
    return res.status(400).json({ error: "Rating must be a number between 1 and 5" });
  }

  const updatedReview = updateReview(id, { rating, comment });

  if (!updatedReview) {
    return res.status(404).json({ error: "Review not found" });
  }

  res.json(updatedReview);
});

// Delete a review
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid review ID" });
  }

  const deleted = deleteReview(id);

  if (!deleted) {
    return res.status(404).json({ error: "Review not found" });
  }

  res.json({ message: "Review deleted successfully" });
});

