import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply authentication check to review-related routes
  if (!req.path.startsWith("/reviews")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  // Check if JWT_SECRET is set
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify the JWT properly)
  // For this example, we'll assume a basic format and verify signature
  try {
    // Split token into parts (header.payload.signature)
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    const [header, payload, signature] = parts;

    // Recreate the signature using the same algorithm
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const expectedBuffer = Buffer.from(expectedSignature);
    const actualBuffer = Buffer.from(signature);

    if (!timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // If we get here, the token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Token verification failed" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only validate POST requests to the reviews endpoint
  if (req.method !== "POST" || !req.path?.startsWith("/reviews")) {
    next();
    return;
  }

  // Validate and sanitize review data
  const { title, content, rating } = req.body;

  // Check required fields
  if (!title || typeof title !== "string" || !content || typeof content !== "string" || !rating || typeof rating !== "number") {
    res.status(400).json({ error: "Invalid review data: title, content, and rating are required" });
    return;
  }

  // Sanitize title and content
  const sanitizedTitle = title.trim().substring(0, 100);
  const sanitizedContent = content.trim().substring(0, 1000);

  // Validate rating
  if (rating < 1 || rating > 5 || !Number.isInteger(rating)) {
    res.status(400).json({ error: "Invalid rating: must be an integer between 1 and 5" });
    return;
  }

  // Replace the request body with sanitized data
  req.body = {
    title: sanitizedTitle,
    content: sanitizedContent,
    rating: rating
  };

  next();
}

