import { useEffect, useState } from "react";

interface StaffMember {
  id: number;
  name: string;
  email: string;
  role: string;
}

export function StaffManagement() {
  const [staff, setStaff] = useState<StaffMember[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    role: "",
  });
  const [editingId, setEditingId] = useState<number | null>(null);

  useEffect(() => {
    fetchStaff();
  }, []);

  const fetchStaff = async () => {
    try {
      const response = await fetch("/api/staff");
      if (!response.ok) throw new Error("Failed to fetch staff");
      const data = await response.json();
      setStaff(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId !== null) {
      // Update existing staff member
      const response = await fetch(`/api/staff/${editingId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });
      if (response.ok) {
        fetchStaff();
        setEditingId(null);
        setFormData({ name: "", email: "", role: "" });
      }
    } else {
      // Add new staff member
      const response = await fetch("/api/staff", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });
      if (response.ok) {
        fetchStaff();
        setFormData({ name: "", email: "", role: "" });
      }
    }
  };

  const handleEdit = (staffMember: StaffMember) => {
    setFormData({
      name: staffMember.name,
      email: staffMember.email,
      role: staffMember.role,
    });
    setEditingId(staffMember.id);
  };

  const handleDelete = async (id: number) => {
    const response = await fetch(`/api/staff/${id}`, {
      method: "DELETE",
    });
    if (response.ok) {
      fetchStaff();
    }
  };

  const handleCancel = () => {
    setEditingId(null);
    setFormData({ name: "", email: "", role: "" });
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  const formStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
    marginBottom: "20px",
    padding: "15px",
    border: "1px solid #ccc",
    borderRadius: "5px",
    backgroundColor: "#f9f9f9",
  };

  const inputStyle: React.CSSProperties = {
    padding: "8px",
    borderRadius: "4px",
    border: "1px solid #ddd",
    width: "100%",
    boxSizing: "border-box",
  };

  const buttonStyle: React.CSSProperties = {
    padding: "8px 12px",
    borderRadius: "4px",
    border: "none",
    backgroundColor: "#007bff",
    color: "white",
    cursor: "pointer",
    marginRight: "5px",
  };

  const listStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
  };

  const cardStyle: React.CSSProperties = {
    padding: "10px",
    border: "1px solid #ddd",
    borderRadius: "5px",
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
  };

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "Arial, sans-serif" }}>
      <h1>Staff Management</h1>

      <form onSubmit={handleSubmit} style={formStyle}>
        <input
          type="text"
          placeholder="Name"
          value={formData.name}
          onChange={(e) => setFormData({ ...formData, name: e.target.value })}
          style={inputStyle}
        />
        <input
          type="email"
          placeholder="Email"
          value={formData.email}
          onChange={(e) => setFormData({ ...formData, email: e.target.value })}
          style={inputStyle}
        />
        <select
          value={formData.role}
          onChange={(e) => setFormData({ ...formData, role: e.target.value })}
          style={inputStyle}
        >
          <option value="">Select Role</option>
          <option value="dentist">Dentist</option>
          <option value="hygienist">Hygienist</option>
          <option value="receptionist">Receptionist</option>
          <option value="admin">Admin</option>
        </select>
        <button type="submit" style={buttonStyle}>{editingId ? "Update" : "Add"} Staff</button>
        {editingId && (
          <button type="button" onClick={handleCancel} style={{ ...buttonStyle, backgroundColor: "#6c757d" }}>
            Cancel
          </button>
        )}
      </form>

      <h2>Staff List</h2>
      <div style={listStyle}>
        {staff.length === 0 ? (
          <p>No staff members found.</p>
        ) : (
          staff.map((member) => (
            <div key={member.id} style={cardStyle}>
              <div>
                <strong>{member.name}</strong> - {member.email} ({member.role})
              </div>
              <div>
                <button
                  onClick={() => handleEdit(member)}
                  style={{ ...buttonStyle, backgroundColor: "#17a2b8" }}
                >
                  Edit
                </button>
                <button
                  onClick={() => handleDelete(member.id)}
                  style={{ ...buttonStyle, backgroundColor: "#dc3545" }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// Define role-based permissions
const allowedRoles = {
  appointments: ["admin", "dentist", "hygienist", "receptionist"],
  staff: ["admin"],
  patients: ["admin", "dentist", "hygienist", "receptionist"]
};

// Type definitions
interface DecodedToken {
  userId: string;
  role: string;
}

function verifyToken(token: string, secret: string): DecodedToken | null {
  // Basic token structure validation
  const parts = token.split(".");
  if (parts.length !== 3) return null;

  try {
    // Decode the payload (simplified)
    const payload = Buffer.from(parts[1], "base64").toString();
    const decoded: DecodedToken = JSON.parse(payload);

    // Verify signature
    const signature = parts[2];
    const expectedSignature = createHmac("sha256", secret)
      .update(`${parts[0]}.${parts[1]}`)
      .digest("base64");

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(signature, "base64"),
      Buffer.from(expectedSignature, "base64")
    );

    return isValid ? decoded : null;
  } catch (err) {
    return null;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply authorization checks to protected routes
  const protectedPaths = ["/appointments", "/staff", "/patients"];
  const isProtectedPath = protectedPaths.some(path => 
    req.path.startsWith(path) || req.path === path
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  const decoded = verifyToken(token, secret);
  if (!decoded) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  const userRole = decoded.role;
  const requiredRole = getRequiredRole(req.path);

  // Check if user has permission
  if (requiredRole && !allowedRoles[requiredRole as keyof typeof allowedRoles]?.includes(userRole)) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  // Attach user info to request for downstream middleware/routes
  (req as any).user = {
    id: decoded.userId,
    role: userRole
  };

  next();
}

function getRequiredRole(path: string): string | null {
  if (path.startsWith("/appointments")) return "appointments";
  if (path.startsWith("/staff")) return "staff";
  if (path.startsWith("/patients")) return "patients";
  return null;
}

