  const staffUser = users.find(u => u.role === "staff");

  if (!staffUser) {
    return res.status(403).json({ error: "Access denied. Staff only." });
  }

  return res.json({ 
    message: "Staff dashboard accessed successfully",
    staffData: "This is sensitive staff information"
  });
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for public routes
  if (req.method === "GET" && (req.path.startsWith("/public") || req.path === "/")) {
    return next();
  }

  // Skip validation for non-protected routes
  if (!req.path.startsWith("/api/")) {
    return next();
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    return res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
  }

  try {
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      return res.status(401).json({ error: "Unauthorized: Invalid token format" });
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      return res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    }

    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
    const userRole = decodedPayload.role;

    if (!userRole) {
      return res.status(401).json({ error: "Unauthorized: User role not specified" });
    }

    // Staff can access all features
    if (userRole === "staff") {
      return next();
    }

    // Customer restrictions
    if (userRole === "customer") {
      // Allow read access to public data
      if (req.method === "GET") {
        return next();
      }

      // Deny modification of bike records
      if (req.path.includes("/bikes") && (req.method === "POST" || req.method === "PUT" || req.method === "DELETE")) {
        return res.status(403).json({ error: "Forbidden: Customers cannot modify bike records" });
      }

      // Deny access to other users' profiles
      if (req.path.includes("/users/")) {
        const userId = req.params.id || req.params.userId;
        if (userId && userId !== decodedPayload.id) {
          return res.status(403).json({ error: "Forbidden: Access denied to this profile" });
        }
      }

      // Allow customers to access their own data
      return next();
    }

    return res.status(403).json({ error: "Forbidden: Unknown user role" });
  } catch (error) {
    return res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHash, scrypt, randomBytes, timingSafeEqual } from "node:crypto";

const SALT_LENGTH = 32;
const HASH_LENGTH = 64;
const KEY_LENGTH = 64;

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to hash passwords during user registration
  // It should only process POST requests to the /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  const password = req.body.password;

  // Generate salt
  const salt = randomBytes(SALT_LENGTH);

  // Hash password with scrypt
  scrypt(password, salt, KEY_LENGTH, (err, key) => {
    if (err) {
      next(err);
      return;
    }

    // Combine salt and hash
    const hash = Buffer.concat([salt, key]);

    // Store hashed password in request body
    req.body.hashedPassword = hash.toString("hex");

    next();
  });
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SECRET = process.env.JWT_SECRET;

function isValidToken(token: string): boolean {
  if (!SECRET) return false;

  const parts = token.split(".");
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;

  const expectedSignature = createHmac("sha256", SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(signature, "base64url");
    return timingSafeEqual(expectedBuffer, actualBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check sessions for protected routes
  if (req.method === "GET" && req.path === "/") {
    return next();
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Missing or invalid authorization header" });
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  if (!isValidToken(token)) {
    return res.status(401).json({ error: "Invalid token" });
  }

  // Token is valid, proceed to next middleware/route handler
  next();
}

import { useEffect, useState } from "react";

interface Bike {
  id: number;
  type: string;
  brand: string;
  model: string;
  size: string;
  color: string;
  dailyRate: number;
  isAvailable: boolean;
}

export function BikeManagementPage() {
  const [bikes, setBikes] = useState<Bike[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [filter, setFilter] = useState("all");

  // Form state
  const [newBike, setNewBike] = useState({
    type: "",
    brand: "",
    model: "",
    size: "",
    color: "",
    dailyRate: 0,
    isAvailable: true
  });

  // Fetch bikes
  useEffect(() => {
    const fetchBikes = async () => {
      try {
        const response = await fetch('/api/bikes');
        if (!response.ok) {
          throw new Error('Failed to fetch bikes');
        }
        const data = await response.json();
        setBikes(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    };

    fetchBikes();
  }, []);

  // Handle form input changes
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as HTMLInputElement | HTMLSelectElement;
    const checked = (e.target as HTMLInputElement).checked;

    setNewBike(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  // Add new bike
  const handleAddBike = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = await fetch('/api/bikes', {
        method: 'POST',
