      // Refresh the list
      const updatedResponse = await fetch('/api/bikes');
      const updatedData = await updatedResponse.json();
      setBikes(updatedData);

      // Reset form
      setNewBike({
        type: "",
        brand: "",
        model: "",
        size: "",
        color: "",
        dailyRate: 0,
        isAvailable: true
