      <div style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <h2>Add New Bike</h2>
        <form onSubmit={handleAddBike}>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              name="type"
              placeholder="Type (e.g., Mountain, Road)"
              value={newBike.type}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px' }}
              required
            />
          </div>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              name="brand"
              placeholder="Brand"
              value={newBike.brand}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px' }}
              required
            />
          </div>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              name="model"
              placeholder="Model"
              value={newBike.model}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px' }}
              required
            />
          </div>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              name="size"
              placeholder="Size"
              value={newBike.size}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px' }}
              required
            />
          </div>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              name="color"
              placeholder="Color"
              value={newBike.color}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px' }}
