import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for public routes
  if (req.method === "GET" && (req.path.startsWith("/public") || req.path === "/")) {
    return next();
  }

  // Skip validation for non-protected routes
  if (!req.path.startsWith("/api/")) {
    return next();
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    return res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
  }

  try {
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      return res.status(401).json({ error: "Unauthorized: Invalid token format" });
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      return res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    }

    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
    const userRole = decodedPayload.role;

    if (!userRole) {
      return res.status(401).json({ error: "Unauthorized: User role not specified" });
    }

    // Staff can access all features
    if (userRole === "staff") {
      return next();
    }

    // Customer restrictions
    if (userRole === "customer") {
      // Allow read access to public data
      if (req.method === "GET") {
        return next();
      }

      // Deny modification of bike records
      if (req.path.includes("/bikes") && (req.method === "POST" || req.method === "PUT" || req.method === "DELETE")) {
        return res.status(403).json({ error: "Forbidden: Customers cannot modify bike records" });
      }

      // Deny access to other users' profiles
      if (req.path.includes("/users/")) {
        const userId = req.params.id || req.params.userId;
        if (userId && userId !== decodedPayload.id) {
          return res.status(403).json({ error: "Forbidden: Access denied to this profile" });
        }
      }

      // Allow customers to access their own data
      return next();
    }

    return res.status(403).json({ error: "Forbidden: Unknown user role" });
  } catch (error) {
    return res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

