import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to job card related routes
  const jobCardRoutes = /^\/job-cards(\/|$)/i;

  if (!jobCardRoutes.test(req.path)) {
    next();
    return;
  }

  // Check if user has required role for the operation
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (!userRole) {
    res.status(401).json({ error: "Unauthorized: Role not provided" });
    return;
  }

  const allowedRoles: Record<string, string[]> = {
    "GET": ["admin", "mechanic", "manager"],
    "POST": ["admin", "manager"],
    "PUT": ["admin", "manager"],
    "DELETE": ["admin"]
  };

  const method = req.method;
  const allowedRolesForMethod = allowedRoles[method] || [];

  if (!allowedRolesForMethod.includes(userRole)) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHash, scryptSync, randomBytes, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to handle password hashing operations
  // It should only process POST requests to the /auth/register endpoint
  if (req.method !== "POST" || req.path !== "/auth/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  // Hash the password using scrypt
  const salt = randomBytes(16).toString("hex");
  const key = scryptSync(req.body.password, salt, 32);
  const hashedPassword = key.toString("hex");

  // Replace the password with the hashed version
  req.body.password = hashedPassword;
  req.body.salt = salt;

  next();
}

