import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  { id: 1, username: "teacher1", password: "pass123", role: "teacher" },
  { id: 2, username: "student1", password: "pass456", role: "student" }
];

// Registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role } = req.body;

  // Validate input
  if (!username || !password || !role) {
    return res.status(400).json({ error: "Username, password, and role are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    username,
    password,
    role
  };

  users.push(newUser);

  return res.status(201).json({
    id: newUser.id,
    username: newUser.username,
    role: newUser.role
  });
});

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  // Validate input
  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Find user
  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Return user info (in a real app, this would be a JWT token)
  return res.json({
    id: user.id,
    username: user.username,
    role: user.role
  });
});

// Role-based access control middleware
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    // In a real implementation, this would check the JWT token
    // For now, we'll simulate checking via a mock header
    const userRole = req.headers["x-user-role"] as string;

    if (userRole !== requiredRole) {
      return res.status(403).json({ error: "Access denied" });
    }

    next();
  };
};

// Protected route for teachers
router.get("/teacher-dashboard", requireRole("teacher"), (req: Request, res: Response) => {
  return res.json({ message: "Welcome to the teacher dashboard" });
});

// Protected route for students
router.get("/student-dashboard", requireRole("student"), (req: Request, res: Response) => {
  return res.json({ message: "Welcome to the student dashboard" });
});

