  { id: 1, quizId: 1, studentId: 1, score: 85, totalQuestions: 10 },
  { id: 2, quizId: 1, studentId: 2, score: 92, totalQuestions: 10 },
  { id: 3, quizId: 2, studentId: 1, score: 78, totalQuestions: 10 },
];

// Mock function to simulate fetching quiz results
const fetchQuizResults = (quizId: number) => {
  return mockQuizResults.filter(result => result.quizId === quizId);
};

// Mock function to calculate average score
const calculateAverageScore = (results: any[]) => {
  if (results.length === 0) return 0;
  const totalScore = results.reduce((sum, result) => sum + result.score, 0);
  return Math.round((totalScore / results.length) * 100) / 100;
};

// Mock function to calculate pass rate
const calculatePassRate = (results: any[], passingScore: number = 70) => {
  if (results.length === 0) return 0;
  const passed = results.filter(result => result.score >= passingScore).length;
  return Math.round((passed / results.length) * 100) / 100;
};

// Route to generate performance report for a specific quiz
router.get("/quiz/:quizId", (req: Request, res: Response) => {
  const quizId = Number(req.params.quizId);

  if (isNaN(quizId)) {
    return res.status(400).json({ error: "Invalid quiz ID" });
  }

  const results = fetchQuizResults(quizId);

  if (results.length === 0) {
    return res.status(404).json({ error: "No results found for this quiz" });
  }

  const averageScore = calculateAverageScore(results);
  const passRate = calculatePassRate(results);

  const report = {
    quizId,
    totalStudents: results.length,
    averageScore,
    passRate,
    highestScore: Math.max(...results.map(r => r.score)),
    lowestScore: Math.min(...results.map(r => r.score)),
  };

  res.json(report);
});

// Route to get detailed results for a specific quiz
router.get("/quiz/:quizId/results", (req: Request, res: Response) => {
  const quizId = Number(req.params.quizId);

  if (isNaN(quizId)) {
    return res.status(400).json({ error: "Invalid quiz ID" });
  }

  const results = fetchQuizResults(quizId);

  if (results.length === 0) {
    return res.status(404).json({ error: "No results found for this quiz" });
  }

  res.json(results);
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-protected routes
  if (!req.path.startsWith('/api/')) {
    next();
    return;
  }

  // Check if user is authenticated
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: 'Server configuration error' });
    return;
  }

  // Simple token verification (in a real app, use a proper JWT library)
  try {
    const [payload, signature] = token.split('.');
    if (!payload || !signature) {
      res.status(401).json({ error: 'Invalid token format' });
      return;
    }

    // Create expected signature
    const expectedSignature = createHmac('sha256', secret)
      .update(payload)
      .digest('base64url');

    // Compare signatures safely
    const expectedBuffer = Buffer.from(expectedSignature, 'base64url');
    const actualBuffer = Buffer.from(signature, 'base64url');

    if (expectedBuffer.length !== actualBuffer.length || 
        !timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: 'Invalid token signature' });
      return;
    }

    // Decode payload to get role and userId
    const payloadDecoded = Buffer.from(payload, 'base64url').toString('utf8');
    const { role, userId } = JSON.parse(payloadDecoded);

    // Store user info in request for later use
    (req as any).user = { role, userId };

    // Validate access based on role
    if (role === 'teacher') {
      // Teacher can only access their own quizzes and student data
      if (req.path.includes('/quizzes/') && req.params.userId && req.params.userId !== userId) {
        res.status(403).json({ error: 'Forbidden: Access denied' });
        return;
      }

      if (req.path.includes('/students/') && req.params.teacherId && req.params.teacherId !== userId) {
        res.status(403).json({ error: 'Forbidden: Access denied' });
        return;
      }
    } else if (role === 'student') {
      // Student can only take assigned quizzes
      if (req.path.includes('/quizzes/') && req.params.studentId && req.params.studentId !== userId) {
        res.status(403).json({ error: 'Forbidden: Access denied' });
        return;
      }
    }

    next();
  } catch (error) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHash, randomBytes } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to handle password hashing for user registration
  // It should only process POST requests to the /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  // Hash the password using SHA-256 with a salt
  const salt = randomBytes(32).toString("hex");
  const hashedPassword = createHash("sha256")
    .update(req.body.password + salt)
    .digest("hex");

  // Replace the password with the hashed version in the request body
  req.body.password = hashedPassword;
  req.body.salt = salt;

  next();
}

