import { useState } from "react";

export function QuizCreationPage() {
  const [quizTitle, setQuizTitle] = useState("");
  const [questions, setQuestions] = useState([
    {
      id: 1,
      questionText: "",
      options: ["", "", "", ""],
      correctAnswerIndex: 0
    }
  ]);

  const handleAddQuestion = () => {
    const newQuestion = {
      id: questions.length + 1,
      questionText: "",
      options: ["", "", "", ""],
      correctAnswerIndex: 0
    };
    setQuestions([...questions, newQuestion]);
  };

  const handleQuestionChange = (questionId: number, text: string) => {
    setQuestions(questions.map(q => 
      q.id === questionId ? { ...q, questionText: text } : q
    ));
  };

  const handleOptionChange = (questionId: number, optionIndex: number, text: string) => {
    setQuestions(questions.map(q => {
      if (q.id === questionId) {
        const newOptions = [...q.options];
        newOptions[optionIndex] = text;
        return { ...q, options: newOptions };
      }
      return q;
    }));
  };

  const handleCorrectAnswerChange = (questionId: number, index: number) => {
    setQuestions(questions.map(q => 
      q.id === questionId ? { ...q, correctAnswerIndex: index } : q
    ));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // In a real app, this would send the quiz data to a backend
    console.log("Quiz submitted:", { title: quizTitle, questions });
    alert("Quiz created successfully!");
  };

  const inputStyle = {
    width: "100%",
    padding: "8px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    boxSizing: "border-box"
  };

  return (
    <div style={{
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      maxWidth: "600px",
      margin: "0 auto",
      padding: "20px"
    }}>
      <h1>Create New Quiz</h1>
      <form onSubmit={handleSubmit}>
        <div style={{ marginBottom: "20px" }}>
          <label htmlFor="quizTitle" style={{ display: "block", marginBottom: "5px" }}>
            Quiz Title:
          </label>
          <input
            id="quizTitle"
            type="text"
            value={quizTitle}
            onChange={(e) => setQuizTitle(e.target.value)}
            style={inputStyle}
            placeholder="Enter quiz title"
          />
        </div>

        <h2>Questions</h2>
        {questions.map((question) => (
          <div key={question.id} style={{
            border: "1px solid #eee",
            borderRadius: "8px",
            padding: "15px",
            marginBottom: "20px"
          }}>
            <label htmlFor={`question-${question.id}`} style={{ display: "block", marginBottom: "5px" }}>
              Question {question.id}:
            </label>
            <input
              id={`question-${question.id}`}
              type="text"
              value={question.questionText}
              onChange={(e) => handleQuestionChange(question.id, e.target.value)}
              style={inputStyle}
              placeholder="Enter question text"
            />

            <div style={{ marginTop: "10px" }}>
              <p style={{ margin: "5px 0" }}>Options:</p>
              {question.options.map((option, index) => (
                <div key={index} style={{ display: "flex", alignItems: "center", marginBottom: "5px" }}>
                  <input
                    type="radio"
                    id={`correct-${question.id}-${index}`}
                    name={`correct-answer-${question.id}`}
                    checked={question.correctAnswerIndex === index}
                    onChange={() => handleCorrectAnswerChange(question.id, index)}
                    style={{ marginRight: "5px" }}
                  />
                  <label htmlFor={`correct-${question.id}-${index}`} style={{ marginRight: "10px" }}>
                    Correct Answer
                  </label>
                  <input
                    type="text"
                    value={option}
                    onChange={(e) => handleOptionChange(question.id, index, e.target.value)}
                    style={inputStyle}
                    placeholder={`Option ${index + 1}`}
                  />
                </div>
              ))}
            </div>
          </div>
        ))}

        <button
          type="button"
          onClick={handleAddQuestion}
          style={{
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            borderRadius: "4px",
            padding: "10px 15px",
            cursor: "pointer",
            marginBottom: "20px"
          }}
        >
          Add Question
        </button>

        <button
          type="submit"
          style={{
            backgroundColor: "#28a745",
            color: "white",
            border: "none",
            borderRadius: "4px",
            padding: "10px 15px",
            cursor: "pointer",
            width: "100%"
          }}
        >
          Create Quiz
        </button>
      </form>
    </div>
  );
}

