import { useEffect, useState } from "react";

export function StudentQuizTakerPage() {
  const [quizzes, setQuizzes] = useState<any[]>([]);
  const [selectedQuiz, setSelectedQuiz] = useState<any>(null);
  const [answers, setAnswers] = useState<Record<string, string>>({});
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchQuizzes();
  }, []);

  const fetchQuizzes = async () => {
    try {
      setIsLoading(true);
      const response = await fetch('/api/quizzes');
      if (!response.ok) {
        throw new Error('Failed to fetch quizzes');
      }
      const data = await response.json();
      setQuizzes(data);
    } catch (err) {
      setError('Failed to load quizzes');
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleAnswerChange = (questionId: string, value: string) => {
    setAnswers(prev => ({
      ...prev,
      [questionId]: value
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedQuiz) return;

    try {
      const response = await fetch(`/api/quizzes/${selectedQuiz.id}/submit`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ answers })
      });

      if (!response.ok) {
        throw new Error('Failed to submit quiz');
      }

      // Reset form after successful submission
      setAnswers({});
      setSelectedQuiz(null);

      // Refresh quizzes list
      fetchQuizzes();
    } catch (err) {
      setError('Failed to submit quiz');
      console.error(err);
    }
  };

  if (isLoading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (quizzes.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No quizzes available</div>;
  }

  return (
    <div style={{
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <h1 style={{ textAlign: 'center' }}>Take a Quiz</h1>

      {!selectedQuiz ? (
        <div>
          <h2>Available Quizzes</h2>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
            {quizzes.map(quiz => (
              <div 
                key={quiz.id}
                style={{
                  border: '1px solid #ccc',
                  borderRadius: '8px',
                  padding: '15px',
                  cursor: 'pointer',
                  transition: 'box-shadow 0.2s',
                  backgroundColor: '#f9f9f9'
                }}
                onClick={() => setSelectedQuiz(quiz)}
              >
                <h3>{quiz.title}</h3>
                <p>{quiz.description}</p>
                <p><small>{quiz.questions?.length || 0} questions</small></p>
              </div>
            ))}
          </div>
        </div>
      ) : (
        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: '20px' }}>
            <h2>{selectedQuiz.title}</h2>
            <p>{selectedQuiz.description}</p>
            <button 
              type="button" 
              onClick={() => setSelectedQuiz(null)}
              style={{
                background: 'none',
                border: '1px solid #007bff',
                color: '#007bff',
                padding: '8px 12px',
                borderRadius: '4px',
                cursor: 'pointer',
                marginBottom: '10px'
              }}
            >
              Back to Quiz List
            </button>
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
            {selectedQuiz.questions?.map((question: any) => (
              <div 
                key={question.id}
                style={{
                  border: '1px solid #ddd',
                  borderRadius: '8px',
                  padding: '15px',
                  backgroundColor: '#fff'
                }}
              >
                <h3>{question.text}</h3>
                <div>
                  {question.options?.map((option: any) => (
                    <label key={option.id} style={{ display: 'block', margin: '5px 0' }}>
                      <input
                        type="radio"
                        name={`question-${question.id}`}
                        value={option.id}
                        checked={answers[question.id] === option.id}
                        onChange={(e) => handleAnswerChange(question.id, e.target.value)}
                        style={{ marginRight: '8px' }}
                      />
                      {option.text}
                    </label>
                  ))}
                </div>
              </div>
            ))}
          </div>

          <button 
            type="submit" 
            style={{
              marginTop: '20px',
              background: '#007bff',
              color: 'white',
              border: 'none',
              padding: '12px 20px',
              borderRadius: '4px',
              cursor: 'pointer',
              fontSize: '16px',
              width: '100%'
            }}
          >
            Submit Quiz
          </button>
        </form>
      )}
    </div>
  );
}

