    {
      id: 1,
      questionText: "",
      options: ["", "", "", ""],
      correctAnswerIndex: 0
    }
  ]);

  const handleAddQuestion = () => {
    const newQuestion = {
      id: questions.length + 1,
      questionText: "",
      options: ["", "", "", ""],
      correctAnswerIndex: 0
    };
    setQuestions([...questions, newQuestion]);
  };

  const handleQuestionChange = (questionId: number, text: string) => {
    setQuestions(questions.map(q => 
      q.id === questionId ? { ...q, questionText: text } : q
    ));
  };

  const handleOptionChange = (questionId: number, optionIndex: number, text: string) => {
    setQuestions(questions.map(q => {
      if (q.id === questionId) {
        const newOptions = [...q.options];
        newOptions[optionIndex] = text;
        return { ...q, options: newOptions };
      }
      return q;
    }));
  };

  const handleCorrectAnswerChange = (questionId: number, index: number) => {
    setQuestions(questions.map(q => 
      q.id === questionId ? { ...q, correctAnswerIndex: index } : q
    ));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // In a real app, this would send the quiz data to a backend
