export const router = Router();

/**
 * Calculates EMI based on principal, interest rate, and tenure
 */
function calculateEMI(principal: number, annualInterestRate: number, tenureInMonths: number): number {
  const monthlyInterestRate = annualInterestRate / 12 / 100;

  if (monthlyInterestRate === 0) {
    return principal / tenureInMonths;
  }

  const emi = principal * monthlyInterestRate * Math.pow(1 + monthlyInterestRate, tenureInMonths) /
    (Math.pow(1 + monthlyInterestRate, tenureInMonths) - 1);

  return emi;
}

/**
 * POST /calculate-emi
 * Calculates EMI based on principal, interest rate, and tenure
 */
router.post("/calculate-emi", (req: Request, res: Response) => {
  const { principal, annualInterestRate, tenureInMonths } = req.body;

  // Validate input
  if (!principal || !annualInterestRate || !tenureInMonths) {
    return res.status(400).json({ error: "Principal, interest rate, and tenure are required" });
  }

  const principalNum = Number(principal);
  const interestRateNum = Number(annualInterestRate);
  const tenureNum = Number(tenureInMonths);

  if (isNaN(principalNum) || isNaN(interestRateNum) || isNaN(tenureNum)) {
    return res.status(400).json({ error: "All inputs must be valid numbers" });
  }

  if (principalNum <= 0 || interestRateNum < 0 || tenureNum <= 0) {
    return res.status(400).json({ error: "Principal and tenure must be positive, interest rate can be zero or positive" });
  }

  try {
    const emi = calculateEMI(principalNum, interestRateNum, tenureNum);
    return res.json({ emi: parseFloat(emi.toFixed(2)) });
  } catch (error) {
    return res.status(500).json({ error: "Failed to calculate EMI" });
  }
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check authentication for POST requests to /loan
  if (!(req.method === "POST" && req.path === "/loan")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT_SECRET not configured" });
    return;
  }

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    const [header, payload, signature] = parts;
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    // Use timingSafeEqual to prevent timing attacks
    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // If we get here, the token is valid
    next();
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  const protectedPaths = ["/admin", "/user"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (!userRole) {
    res.status(401).json({ error: "Unauthorized: Missing role header" });
    return;
  }

  // Validate role
  const validRoles = ["admin", "user"];
  if (!validRoles.includes(userRole)) {
    res.status(403).json({ error: "Forbidden: Invalid role" });
    return;
  }

  // For admin-only routes
  if (req.path.startsWith("/admin") && userRole !== "admin") {
    res.status(403).json({ error: "Forbidden: Admin role required" });
    return;
  }

  // For user-only routes
  if (req.path.startsWith("/user") && userRole !== "user") {
    res.status(403).json({ error: "Forbidden: User role required" });
    return;
  }

  // If we reach here, the user has proper access
  next();
}

