import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const ROLES = {
  ADMIN: "admin",
  STAFF: "staff",
};

const ALLOWED_PATHS = [
  "/check-in",
  "/check-out",
  "/visitors",
];

const ALLOWED_METHODS = ["POST", "PUT", "DELETE"];

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-protected routes
  const isProtectedPath = ALLOWED_PATHS.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath || !ALLOWED_METHODS.includes(req.method)) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT_SECRET not set" });
    return;
  }

  try {
    // Simple token structure: base64 encoded role
    const payload = Buffer.from(token, "base64").toString("utf-8");
    const [role] = payload.split(":");

    if (role !== ROLES.ADMIN && role !== ROLES.STAFF) {
      res.status(403).json({ error: "Forbidden: Insufficient permissions" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "No token provided" });
  }

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    return res.status(500).json({ error: "Server configuration error" });
  }

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      return res.status(401).json({ error: "Invalid token" });
    }

    const [header, payload, signature] = parts;

    // Recalculate signature
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      return res.status(401).json({ error: "Invalid token" });
    }

    // If we get here, the token is valid
    next();
  } catch (error) {
    return res.status(401).json({ error: "Invalid token" });
  }
}

import { useEffect, useState } from "react";

interface Visitor {
  id: string;
  name: string;
  company: string;
  checkInTime: string;
  status: "checked-in" | "checked-out";
}

export function VisitorListPage() {
  const [visitors, setVisitors] = useState<Visitor[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchVisitors = async () => {
      try {
        const response = await fetch(`/api/visitors`);
        if (!response.ok) {
          throw new Error(`Failed to fetch visitors: ${response.status}`);
        }
        const data = await response.json();
        setVisitors(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchVisitors();
  }, []);

  const filteredVisitors = visitors.filter(visitor =>
    visitor.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    visitor.company.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Visitor List</h1>

      <input
        type="text"
        placeholder="Search by name or company..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
        style={{
          width: "100%",
          padding: "10px",
          marginBottom: "20px",
          borderRadius: "4px",
          border: "1px solid #ccc",
          boxSizing: "border-box"
        }}
      />

      {filteredVisitors.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No visitors found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {filteredVisitors.map((visitor) => (
            <div 
              key={visitor.id}
              style={{
                border: "1px solid #ddd",
                borderRadius: "8px",
                padding: "15px",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                backgroundColor: "#f9f9f9"
              }}
            >
              <div>
                <h3 style={{ margin: "0 0 5px 0" }}>{visitor.name}</h3>
                <p style={{ margin: "0 0 5px 0", color: "#666" }}>
                  Company: {visitor.company}
                </p>
                <p style={{ margin: "0 0 5px 0", color: "#666" }}>
                  Check-in: {new Date(visitor.checkInTime).toLocaleString()}
                </p>
                <p style={{ margin: "0", color: visitor.status === "checked-in" ? "green" : "red" }}>
                  Status: {visitor.status === "checked-in" ? "Checked In" : "Checked Out"}
                </p>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useState } from "react";

export function VisitorRegistrationForm() {
  const [formData, setFormData] = useState({
    name: "",
    company: "",
    purpose: "",
    departureTime: "",
    contactInfo: ""
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    // In a real app, this would make an API call
    // For now, we'll just simulate success
    await new Promise(resolve => setTimeout(resolve, 500));

    setIsSubmitting(false);
    setSubmitSuccess(true);

    // Reset form after successful submission
    setFormData({
      name: "",
      company: "",
      purpose: "",
      departureTime: "",
      contactInfo: ""
    });

    // Reset success message after 3 seconds
    setTimeout(() => setSubmitSuccess(false), 3000);
