import { FC, useEffect, useState } from "react";

interface Visitor {
  id: string;
  name: string;
  checkInTime: string;
  checkOutTime?: string;
}

export function CheckInCheckOutInterface() {
  const [visitors, setVisitors] = useState<Visitor[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newVisitor, setNewVisitor] = useState({
    name: "",
  });

  useEffect(() => {
    fetchVisitors();
  }, []);

  const fetchVisitors = async () => {
    try {
      const response = await fetch("/api/visitors");
      if (!response.ok) {
        throw new Error("Failed to fetch visitors");
      }
      const data = await response.json();
      setVisitors(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  const handleCheckIn = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/visitors", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: newVisitor.name,
          checkInTime: new Date().toISOString(),
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to check in visitor");
      }

      setNewVisitor({ name: "" });
      fetchVisitors();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleCheckOut = async (id: string) => {
    try {
      const response = await fetch(`/api/visitors/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          checkOutTime: new Date().toISOString(),
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to check out visitor");
      }

      fetchVisitors();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div
      style={{
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Visitor Check-In/Check-Out</h1>

      <form
        onSubmit={handleCheckIn}
        style={{
          marginBottom: "30px",
          padding: "20px",
          border: "1px solid #ccc",
          borderRadius: "8px",
          backgroundColor: "#f9f9f9",
        }}
      >
        <h2>Check In New Visitor</h2>
        <input
          type="text"
          placeholder="Visitor Name"
          value={newVisitor.name}
          onChange={(e) => setNewVisitor({ ...newVisitor, name: e.target.value })}
          style={{
            width: "100%",
            padding: "10px",
            marginBottom: "10px",
            borderRadius: "4px",
            border: "1px solid #ddd",
          }}
          required
        />
        <button
          type="submit"
          style={{
            padding: "10px 20px",
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer",
          }}
        >
          Check In
        </button>
      </form>

      <h2>Current Visitors</h2>
      {visitors.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No visitors currently checked in.</p>
      ) : (
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "15px",
          }}
        >
          {visitors
            .filter((v) => !v.checkOutTime)
            .map((visitor) => (
              <div
                key={visitor.id}
                style={{
                  padding: "15px",
                  border: "1px solid #ddd",
                  borderRadius: "8px",
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                }}
              >
                <div>
                  <strong>{visitor.name}</strong>
                  <br />
                  <small>
                    Checked in: {new Date(visitor.checkInTime).toLocaleString()}
                  </small>
                </div>
                <button
                  onClick={() => handleCheckOut(visitor.id)}
                  style={{
                    padding: "8px 16px",
                    backgroundColor: "#28a745",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    cursor: "pointer",
                  }}
                >
                  Check Out
                </button>
              </div>
            ))}
        </div>
      )}

      <h2>Visitor History</h2>
      {visitors.filter((v) => v.checkOutTime).length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No visitor history yet.</p>
      ) : (
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "15px",
          }}
        >
          {visitors
            .filter((v) => v.checkOutTime)
            .map((visitor) => (
              <div
                key={visitor.id}
                style={{
                  padding: "15px",
                  border: "1px solid #ddd",
                  borderRadius: "8px",
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                }}
              >
                <div>
                  <strong>{visitor.name}</strong>
                  <br />
                  <small>
                    Checked in: {new Date(visitor.checkInTime).toLocaleString()}<br />
                    Checked out: {new Date(visitor.checkOutTime!).toLocaleString()}
                  </small>
                </div>
              </div>
            ))}
        </div>
      )}
    </div>
  );
}

