import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = new Map<string, { email: string; role: string }>();

// Mock session store
const sessions = new Map<string, { userId: string; expiresAt: Date }>();

// Helper to generate session ID
const generateSessionId = () => Math.random().toString(36).substring(2, 15);

// Registration route
router.post("/register", (req: Request, res: Response) => {
  const { email, password, role = "member" } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  if (users.has(email)) {
    return res.status(400).json({ error: "User already exists" });
  }

  users.set(email, { email, role });
  return res.status(201).json({ email, role });
});

// Login route
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  const user = users.get(email);
  if (!user) {
    return res.status(400).json({ error: "Invalid credentials" });
  }

  // In a real app, we'd verify password hash here
  const sessionId = generateSessionId();
  const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000); // 24 hours
  sessions.set(sessionId, { userId: email, expiresAt });

  return res.json({ sessionId });
});

// Get current user info
router.get("/me", (req: Request, res: Response) => {
  const sessionId = req.headers.authorization?.split(" ")[1];

  if (!sessionId) {
    return res.status(401).json({ error: "No session found" });
  }

  const session = sessions.get(sessionId);
  if (!session) {
    return res.status(401).json({ error: "Invalid session" });
  }

  if (new Date() > session.expiresAt) {
    sessions.delete(sessionId);
    return res.status(401).json({ error: "Session expired" });
  }

  const user = users.get(session.userId);
  if (!user) {
    return res.status(401).json({ error: "User not found" });
  }

  return res.json({ email: user.email, role: user.role });
});

// Logout route
router.post("/logout", (req: Request, res: Response) => {
  const sessionId = req.headers.authorization?.split(" ")[1];

  if (sessionId) {
    sessions.delete(sessionId);
  }

  return res.json({ message: "Logged out successfully" });
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would come from a database module
const mockDatabase = {
  posts: [
    { id: 1, title: "Welcome to the forum", content: "This is the first post", authorId: 1, categoryId: 1, createdAt: new Date(), updatedAt: new Date() },
    { id: 2, title: "Another post", content: "This is another post", authorId: 2, categoryId: 1, createdAt: new Date(), updatedAt: new Date() }
  ],
  comments: [
    { id: 1, content: "Great post!", authorId: 2, postId: 1, createdAt: new Date(), updatedAt: new Date() }
  ],
  categories: [
    { id: 1, name: "General", description: "General discussion" },
    { id: 2, name: "Events", description: "Club events" }
  ],

  findPostById: (id: number) => {
    return mockDatabase.posts.find(p => p.id === id);
  },

  findCommentById: (id: number) => {
    return mockDatabase.comments.find(c => c.id === id);
  },

  findCategoryById: (id: number) => {
    return mockDatabase.categories.find(c => c.id === id);
  },

  createPost: (post: any) => {
    const newPost = { ...post, id: mockDatabase.posts.length + 1, createdAt: new Date(), updatedAt: new Date() };
    mockDatabase.posts.push(newPost);
    return newPost;
  },

  createComment: (comment: any) => {
    const newComment = { ...comment, id: mockDatabase.comments.length + 1, createdAt: new Date(), updatedAt: new Date() };
    mockDatabase.comments.push(newComment);
    return newComment;
  },

  updatePost: (id: number, updates: any) => {
    const index = mockDatabase.posts.findIndex(p => p.id === id);
    if (index !== -1) {
      mockDatabase.posts[index] = { ...mockDatabase.posts[index], ...updates, updatedAt: new Date() };
      return mockDatabase.posts[index];
    }
    return null;
  },

  updateComment: (id: number, updates: any) => {
    const index = mockDatabase.comments.findIndex(c => c.id === id);
    if (index !== -1) {
      mockDatabase.comments[index] = { ...mockDatabase.comments[index], ...updates, updatedAt: new Date() };
      return mockDatabase.comments[index];
    }
    return null;
  },

  deletePost: (id: number) => {
    const index = mockDatabase.posts.findIndex(p => p.id === id);
    if (index !== -1) {
      mockDatabase.posts.splice(index, 1);
      return true;
    }
    return false;
  },

  deleteComment: (id: number) => {
    const index = mockDatabase.comments.findIndex(c => c.id === id);
    if (index !== -1) {
      mockDatabase.comments.splice(index, 1);
      return true;
    }
    return false;
  }
};

