import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST, PUT, DELETE, PATCH requests
  if (!['POST', 'PUT', 'DELETE', 'PATCH'].includes(req.method)) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Missing or invalid authorization header' });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: 'Server configuration error: JWT_SECRET not set' });
    return;
  }

  try {
    // Basic token structure validation
    const parts = token.split('.');
    if (parts.length !== 3) {
      res.status(401).json({ error: 'Invalid token format' });
      return;
    }

    const [header, payload, signature] = parts;

    // Verify signature
    const expectedSignature = createHmac('sha256', secret)
      .update(`${header}.${payload}`)
      .digest('base64url');

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(expectedSignature, 'base64url'),
      Buffer.from(signature, 'base64url')
    );

    if (!isValid) {
      res.status(401).json({ error: 'Invalid token signature' });
      return;
    }

    // If we get here, the token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: 'Token verification failed' });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST, PUT, PATCH, DELETE requests
  if (!['POST', 'PUT', 'PATCH', 'DELETE'].includes(req.method)) {
    next();
    return;
  }

  // Validate and sanitize input data
  if (req.body) {
    sanitizeBody(req.body);
  }

  // Validate query parameters
  if (req.query) {
    sanitizeQuery(req.query);
  }

  next();
}

function sanitizeBody(body: any): void {
  if (typeof body === 'object' && body !== null) {
    for (const [key, value] of Object.entries(body)) {
      if (typeof value === 'string') {
        // Basic XSS protection: escape HTML characters
        body[key] = value
          .replace(/&/g, '&amp;')
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;')
          .replace(/"/g, '&quot;')
          .replace(/'/g, '&#x27;');

        // Basic SQL injection protection: remove dangerous patterns
        body[key] = body[key]
          .replace(/(union|select|insert|update|delete|drop|create|alter|exec|execute)/gi, '');
      } else if (typeof value === 'object') {
        sanitizeBody(value);
      }
    }
  }
}

function sanitizeQuery(query: any): void {
  if (typeof query === 'object' && query !== null) {
    for (const [key, value] of Object.entries(query)) {
      if (typeof value === 'string') {
        // Basic XSS protection: escape HTML characters
        query[key] = value
          .replace(/&/g, '&amp;')
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;')
          .replace(/"/g, '&quot;')
          .replace(/'/g, '&#x27;');

        // Basic SQL injection protection: remove dangerous patterns
        query[key] = query[key]
          .replace(/(union|select|insert|update|delete|drop|create|alter|exec|execute)/gi, '');
      }
    }
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// In-memory storage for rate limits (in production, use Redis or similar)
const rateLimits = new Map<string, { count: number; resetTime: number }>();

// Configuration
const MAX_REQUESTS = 100;
const TIME_WINDOW_MS = 15 * 60 * 1000; // 15 minutes

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply rate limiting to POST, PUT, DELETE requests
  if (!['POST', 'PUT', 'DELETE'].includes(req.method)) {
    next();
    return;
  }

  // Get client IP address
  const clientIP = req.ip || req.connection.remoteAddress || "unknown";

  // Create a unique key based on IP and current time window
  const now = Date.now();
  const timeWindowStart = Math.floor(now / TIME_WINDOW_MS) * TIME_WINDOW_MS;
  const key = `${clientIP}:${timeWindowStart}`;

  // Initialize or update rate limit tracking
  let limitInfo = rateLimits.get(key);
  if (!limitInfo) {
    limitInfo = { count: 0, resetTime: timeWindowStart + TIME_WINDOW_MS };
    rateLimits.set(key, limitInfo);
  }

  // Check if we're over the limit
  if (limitInfo.count >= MAX_REQUESTS) {
    res.status(429).json({
      error: "Too Many Requests",
      message: "You have exceeded the maximum number of requests allowed in a time window."
    });
    return;
  }

  // Increment the counter
  limitInfo.count += 1;

  // Set headers for rate limit info
  res.setHeader("X-RateLimit-Limit", MAX_REQUESTS);
  res.setHeader("X-RateLimit-Remaining", MAX_REQUESTS - limitInfo.count);
  res.setHeader("X-RateLimit-Reset", limitInfo.resetTime);

  next();
}

