import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = new Map<string, { email: string; role: string }>();

// Mock session store
const sessions = new Map<string, { userId: string; expiresAt: Date }>();

// Helper to generate session ID
const generateSessionId = () => Math.random().toString(36).substring(2, 15);

// Registration route
router.post("/register", (req: Request, res: Response) => {
  const { email, password, role = "member" } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  if (users.has(email)) {
    return res.status(400).json({ error: "User already exists" });
  }

  users.set(email, { email, role });
  return res.status(201).json({ email, role });
});

// Login route
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  const user = users.get(email);
  if (!user) {
    return res.status(400).json({ error: "Invalid credentials" });
  }

  // In a real app, we'd verify password hash here
  const sessionId = generateSessionId();
  const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000); // 24 hours
  sessions.set(sessionId, { userId: email, expiresAt });

  return res.json({ sessionId });
});

// Get current user info
router.get("/me", (req: Request, res: Response) => {
  const sessionId = req.headers.authorization?.split(" ")[1];

  if (!sessionId) {
    return res.status(401).json({ error: "No session found" });
  }

  const session = sessions.get(sessionId);
  if (!session) {
    return res.status(401).json({ error: "Invalid session" });
  }

  if (new Date() > session.expiresAt) {
    sessions.delete(sessionId);
    return res.status(401).json({ error: "Session expired" });
  }

  const user = users.get(session.userId);
  if (!user) {
    return res.status(401).json({ error: "User not found" });
  }

  return res.json({ email: user.email, role: user.role });
});

// Logout route
router.post("/logout", (req: Request, res: Response) => {
  const sessionId = req.headers.authorization?.split(" ")[1];

  if (sessionId) {
    sessions.delete(sessionId);
  }

  return res.json({ message: "Logged out successfully" });
});

