    if (!name || !dueDate) {
      return res.status(400).json({ error: "Name and due date are required" });
    }

    const newTaskId = insertTask({ name, description, dueDate, completed, plantId });

    // Fetch the created task to send back
    const createdTask = getTaskById(newTaskId);
    if (!createdTask) {
      return res.status(500).json({ error: "Failed to retrieve created task" });
    }

    res.status(201).json(createdTask);
  } catch (error) {
    res.status(500).json({ error: "Failed to create task" });
