  } catch (error) {
    res.status(500).json({ error: "Failed to delete task" });
  }
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as authRouter } from "../routes/authentication-service";
import { router as gardenPlanRouter } from "../routes/garden-plan-api";
import { router as plantRouter } from "../routes/plant-api";
import { router as calendarRouter } from "../routes/calendar-api";

const AUTH_PATHS = [
  "/login",
  "/register",
];

const GARDEN_PLAN_PATHS = [
  "/garden-plans",
  "/garden-plans/:id",
];

const PLANT_PATHS = [
  "/plants",
  "/plants/:id",
];

const CALENDAR_PATHS = [
  "/calendar",
  "/calendar/:id",
];

function isAuthPath(path: string): boolean {
  return AUTH_PATHS.some(authPath => path.startsWith(authPath));
}

function isGardenPlanPath(path: string): boolean {
  return GARDEN_PLAN_PATHS.some(gardenPlanPath => path.startsWith(gardenPlanPath));
}

function isPlantPath(path: string): boolean {
  return PLANT_PATHS.some(plantPath => path.startsWith(plantPath));
}

function isCalendarPath(path: string): boolean {
  return CALENDAR_PATHS.some(calendarPath => path.startsWith(calendarPath));
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for auth routes
  if (isAuthPath(req.path)) {
    return next();
  }

  const token = req.header("Authorization")?.replace("Bearer ", "");

  if (!token) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    return res.status(401).json({ error: "Invalid token" });
  }

  const payload = token.split(".")[1];

  if (!payload) {
    return res.status(401).json({ error: "Invalid token" });
  }

  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64");

  const actualSignature = token.split(".")[2];

  if (!actualSignature) {
    return res.status(401).json({ error: "Invalid token" });
  }

  const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64");
  const actualSignatureBuffer = Buffer.from(actualSignature, "base64");

  try {
    const isValid = timingSafeEqual(expectedSignatureBuffer, actualSignatureBuffer);

    if (!isValid) {
      return res.status(401).json({ error: "Invalid token" });
    }
  } catch {
    return res.status(401).json({ error: "Invalid token" });
  }

  // Check if the request is for garden plan, plant, or calendar routes
  if (
    isGardenPlanPath(req.path) ||
    isPlantPath(req.path) ||
    isCalendarPath(req.path)
  ) {
    // For now, we'll allow all authenticated users to access these routes
    // In a more complex system, we might check user roles here
    return next();
  }

  // If it's not an auth route and not a protected route, proceed
  return next();
}

import type { Request, Response, NextFunction } from "express";
import { Router } from "express";
import { router as authRouter } from "../routes/authentication-service";
import { router as gardenPlanRouter } from "../routes/garden-plan-api";
import { router as plantRouter } from "../routes/plant-api";
import { router as calendarRouter } from "../routes/calendar-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for authentication routes
  if (req.path.startsWith("/auth")) {
    return next();
  }

  // Skip validation for garden plan API routes
  if (req.path.startsWith("/garden-plans")) {
    return next();
  }

  // Skip validation for plant API routes
  if (req.path.startsWith("/plants")) {
    return next();
  }

  // Skip validation for calendar API routes
  if (req.path.startsWith("/calendar")) {
    return next();
  }

  // For all other routes, validate input data
  if (req.method === "POST" || req.method === "PUT" || req.method === "PATCH") {
    // Basic validation for request body
    if (req.body) {
      try {
        // Check for potentially dangerous patterns in string fields
        const validateString = (value: unknown): boolean => {
          if (typeof value !== "string") return true;
          // Check for common injection patterns
          const dangerousPatterns = [/<script/i, /<iframe/i, /on\w+\s*=\s*['"]/i];
          return !dangerousPatterns.some(pattern => pattern.test(value));
        };

        const isValid = Object.values(req.body).every(validateString);
        if (!isValid) {
          return res.status(400).json({ message: "Invalid input data" });
        }
      } catch (error) {
        return res.status(400).json({ message: "Invalid input data" });
      }
    }
  }

  // If we reach here, continue with the next middleware
  return next();
}

