interface Task {
  id: string;
  title: string;
  date: string;
  description: string;
}

export function Calendar() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newTask, setNewTask] = useState({
    title: "",
    date: "",
    description: ""
  });

  useEffect(() => {
    fetchTasks();
  }, []);

  const fetchTasks = async () => {
    try {
      const response = await fetch("/api/calendar-api/tasks");
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setTasks(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setNewTask(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/calendar-api/tasks", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newTask)
      });
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      await fetchTasks(); // Refresh the task list
      setNewTask({ title: "", date: "", description: "" }); // Reset form
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Garden Task Calendar</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2>Add New Task</h2>
        <input
          type="text"
          name="title"
          placeholder="Task Title"
          value={newTask.title}
          onChange={handleInputChange}
          style={{ width: "100%", padding: "10px", marginBottom: "10px", borderRadius: "4px", border: "1px solid #ddd" }}
          required
        />
        <input
          type="date"
          name="date"
          value={newTask.date}
          onChange={handleInputChange}
          style={{ width: "100%", padding: "10px", marginBottom: "10px", borderRadius: "4px", border: "1px solid #ddd" }}
          required
        />
        <textarea
          name="description"
          placeholder="Description"
          value={newTask.description}
          onChange={handleInputChange}
          style={{ width: "100%", padding: "10px", marginBottom: "10px", borderRadius: "4px", border: "1px solid #ddd" }}
        />
        <button type="submit" style={{ padding: "10px 20px", backgroundColor: "#4CAF50", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}>Add Task</button>
      </form>

      <h2>Upcoming Tasks</h2>
      {tasks.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No tasks scheduled yet.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {tasks.map(task => (
            <div key={task.id} style={{ padding: "15px", border: "1px solid #ccc", borderRadius: "8px" }}>
              <h3>{task.title}</h3>
              <p><strong>Date:</strong> {task.date}</p>
              <p><strong>Description:</strong> {task.description}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { Router, type Request, type Response } from "express";
import { getAllPlants, getPlantById, insertPlant, updatePlant, deletePlant } from "../db/plants-table";

export const router = Router();

// GET /plants - Get all plants
router.get("/plants", (req: Request, res: Response) => {
  try {
    const plants = getAllPlants();
    res.json(plants);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch plants" });
  }
});

// GET /plants/:id - Get a specific plant by ID
router.get("/plants/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid plant ID" });
    }

    const plant = getPlantById(id);
    if (!plant) {
      return res.status(404).json({ error: "Plant not found" });
    }

    res.json(plant);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch plant" });
  }
});

// POST /plants - Create a new plant
router.post("/plants", (req: Request, res: Response) => {
  try {
    const { name, species, careInstructions, plantingDate } = req.body;

    if (!name || !species) {
      return res.status(400).json({ error: "Name and species are required" });
    }

    const newPlantId = insertPlant({
      name,
      species,
      careInstructions: careInstructions || null,
      plantingDate: plantingDate || null
    });

    const createdPlant = getPlantById(newPlantId);
    res.status(201).json(createdPlant);
  } catch (error) {
    res.status(500).json({ error: "Failed to create plant" });
  }
});

// PUT /plants/:id - Update an existing plant
router.put("/plants/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid plant ID" });
    }

    const existingPlant = getPlantById(id);
    if (!existingPlant) {
      return res.status(404).json({ error: "Plant not found" });
    }

    const { name, species, careInstructions, plantingDate } = req.body;

    const updated = updatePlant(id, {
      name: name || existingPlant.name,
      species: species || existingPlant.species,
      careInstructions: careInstructions || existingPlant.careInstructions,
      plantingDate: plantingDate || existingPlant.plantingDate
    });

    if (!updated) {
      return res.status(500).json({ error: "Failed to update plant" });
    }

    const updatedPlant = getPlantById(id);
    res.json(updatedPlant);
  } catch (error) {
    res.status(500).json({ error: "Failed to update plant" });
  }
});

// DELETE /plants/:id - Delete a plant
router.delete("/plants/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid plant ID" });
    }

    const deleted = deletePlant(id);
    if (!deleted) {
      return res.status(404).json({ error: "Plant not found" });
    }

    res.json({ message: "Plant deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete plant" });
  }
});

