          const dangerousPatterns = [/<script/i, /<iframe/i, /on\w+\s*=\s*['"]/i];
          return !dangerousPatterns.some(pattern => pattern.test(value));
        };

        const isValid = Object.values(req.body).every(validateString);
        if (!isValid) {
          return res.status(400).json({ message: "Invalid input data" });
        }
      } catch (error) {
        return res.status(400).json({ message: "Invalid input data" });
      }
    }
  }

  // If we reach here, continue with the next middleware
  return next();
}

