import { useEffect, useState } from "react";

interface MoodEntry {
  id: number;
  date: string;
  mood: string;
  notes: string;
}

export function MoodEntryList() {
  const [entries, setEntries] = useState<MoodEntry[]>([]);
  const [filteredEntries, setFilteredEntries] = useState<MoodEntry[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchMoodEntries();
  }, []);

  const fetchMoodEntries = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/mood-entries");
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status}`);
      }
      const data = await response.json();
      setEntries(data);
      setFilteredEntries(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
    const term = e.target.value;
    setSearchTerm(term);

    if (term === "") {
      setFilteredEntries(entries);
    } else {
      const filtered = entries.filter(entry => 
        entry.mood.toLowerCase().includes(term.toLowerCase()) ||
        entry.notes.toLowerCase().includes(term.toLowerCase())
      );
      setFilteredEntries(filtered);
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Mood Journal</h1>

      <div style={{ marginBottom: "20px" }}>
        <input
          type="text"
          placeholder="Search by mood or notes..."
          value={searchTerm}
          onChange={handleSearch}
          style={{
            width: "100%",
            padding: "10px",
            borderRadius: "4px",
            border: "1px solid #ccc",
            fontSize: "16px"
          }}
        />
      </div>

      {filteredEntries.length === 0 ? (
        <div style={{ textAlign: "center", padding: "20px" }}>
          No mood entries found.
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {filteredEntries.map(entry => (
            <div 
              key={entry.id} 
              style={{
                border: "1px solid #ddd",
                borderRadius: "8px",
                padding: "15px",
                backgroundColor: "#f9f9f9"
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <h3 style={{ margin: "0", color: "#333" }}>{entry.mood}</h3>
                <span style={{ color: "#666", fontSize: "14px" }}>{entry.date}</span>
              </div>
              <p style={{ margin: "10px 0 0", color: "#555" }}>{entry.notes}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

