const mockDatabase = {
  recipes: [
    { id: 1, name: "Pasta", ingredients: [{ name: "Noodles", quantity: 100, unit: "g", pricePerUnit: 0.05 }, { name: "Sauce", quantity: 50, unit: "ml", pricePerUnit: 0.1 }] },
    { id: 2, name: "Salad", ingredients: [{ name: "Lettuce", quantity: 200, unit: "g", pricePerUnit: 0.03 }, { name: "Tomato", quantity: 150, unit: "g", pricePerUnit: 0.08 }] }
  ],

  getRecipeById(id: number) {
    return this.recipes.find(recipe => recipe.id === id);
  },

  getAllRecipes() {
    return this.recipes;
  },

  createRecipe(name: string, ingredients: { name: string; quantity: number; unit: string; pricePerUnit: number }[]) {
    const newId = Math.max(...this.recipes.map(r => r.id)) + 1;
    const newRecipe = { id: newId, name, ingredients };
    this.recipes.push(newRecipe);
    return newRecipe;
  },

  updateRecipe(id: number, name: string, ingredients: { name: string; quantity: number; unit: string; pricePerUnit: number }[]) {
    const index = this.recipes.findIndex(recipe => recipe.id === id);
    if (index === -1) return null;
    this.recipes[index] = { id, name, ingredients };
    return this.recipes[index];
  },

  deleteRecipe(id: number) {
    const index = this.recipes.findIndex(recipe => recipe.id === id);
    if (index === -1) return false;
    this.recipes.splice(index, 1);
    return true;
  }
};

// Calculate total recipe cost
function calculateTotalCost(ingredients: { quantity: number; pricePerUnit: number }[]): number {
  return ingredients.reduce((total, ingredient) => {
    return total + (ingredient.quantity * ingredient.pricePerUnit);
  }, 0);
}

// GET /recipes - Get all recipes with their costs
router.get("/recipes", (req: Request, res: Response) => {
  try {
    const recipes = mockDatabase.getAllRecipes().map(recipe => ({
      ...recipe,
      totalCost: calculateTotalCost(recipe.ingredients)
    }));
    res.json(recipes);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// GET /recipes/:id - Get a specific recipe by ID with its cost
router.get("/recipes/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid recipe ID" });
    }

    const recipe = mockDatabase.getRecipeById(id);
    if (!recipe) {
      return res.status(404).json({ error: "Recipe not found" });
