// PUT /recipes/:id - Update an existing recipe
router.put("/recipes/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { name, ingredients } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid recipe ID" });
