// Calculate recipe cost based on ingredient quantities and unit costs
router.post("/calculate-cost", (req: Request, res: Response) => {
  const { recipeId } = req.body;

  if (!recipeId) {
    return res.status(400).json({ error: "Recipe ID is required" });
  }

  const recipe = recipes.find(r => r.id === Number(recipeId));

  if (!recipe) {
    return res.status(404).json({ error: "Recipe not found" });
  }

  let totalCost = 0;

  for (const item of recipe.ingredients) {
    const ingredient = ingredients.find(i => i.id === item.ingredientId);
    if (ingredient) {
      totalCost += ingredient.unitCost * item.quantity;
    }
  }

  return res.json({ recipeId, totalCost });
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SECRET = process.env.JWT_SECRET;

function isValidToken(token: string): boolean {
  if (!SECRET) return false;

  const parts = token.split(".");
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;

  const expectedSignature = createHmac("sha256", SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const expectedBytes = Buffer.from(expectedSignature, "base64url");
    const actualBytes = Buffer.from(signature, "base64url");

    return timingSafeEqual(expectedBytes, actualBytes);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check authentication for POST /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  if (!isValidToken(token)) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  next();
}

