import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data structures to simulate database operations
const loans: Record<string, any> = {};
const books: Record<string, any> = {};
const members: Record<string, any> = {};

// Helper function to calculate due date (14 days from now)
const calculateDueDate = () => {
  const date = new Date();
  date.setDate(date.getDate() + 14);
  return date;
};

// Helper function to calculate fine (10 cents per day overdue)
const calculateFine = (returnDate: Date, dueDate: Date) => {
  if (returnDate <= dueDate) return 0;
  const diffTime = Math.abs(returnDate.getTime() - dueDate.getTime());
  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  return diffDays * 0.1;
};

// Create a new loan
router.post("/loans", (req: Request, res: Response) => {
  const { bookId, memberId } = req.body;

  if (!bookId || !memberId) {
    return res.status(400).json({ error: "Book ID and Member ID are required" });
  }

  // Check if book exists
  if (!books[bookId]) {
    return res.status(404).json({ error: "Book not found" });
  }

  // Check if member exists
  if (!members[memberId]) {
    return res.status(404).json({ error: "Member not found" });
  }

  // Check if book is already on loan
  const existingLoan = Object.values(loans).find(
    (loan: any) => loan.bookId === bookId && !loan.returned
  );

  if (existingLoan) {
    return res.status(400).json({ error: "Book is already on loan" });
  }

  const loanId = Date.now().toString();
  const dueDate = calculateDueDate();

  const newLoan = {
    id: loanId,
    bookId,
    memberId,
    dueDate,
    returned: false,
    fine: 0
  };

  loans[loanId] = newLoan;

  return res.status(201).json(newLoan);
});

