});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function verifyToken(token: string): boolean {
  if (!JWT_SECRET) return false;

  const [header, payload, signature] = token.split(".");
  if (!header || !payload || !signature) return false;

  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const expectedBytes = Buffer.from(expectedSignature, "base64url");
    const actualBytes = Buffer.from(signature, "base64url");
    return timingSafeEqual(expectedBytes, actualBytes);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if request has a body with username and password
  if (!req.body || typeof req.body.username !== "string" || typeof req.body.password !== "string") {
    res.status(400).json({ error: "Username and password required" });
    return;
  }

  // In a real implementation, we would verify credentials against a database
  // For now, we'll just simulate a successful login
  const { username, password } = req.body;

  // Simulate valid user credentials
  if (username === "admin" && password === "password") {
    // Generate a mock token
    const token = `header.payload.${createHmac("sha256", JWT_SECRET || "").update("header.payload").digest("base64url")}`;
    res.json({ token });
  } else {
    res.status(401).json({ error: "Invalid credentials" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply RBAC to POST /loans and PUT /loans routes
  if (!(req.method === "POST" && req.path === "/loans") && !(req.method === "PUT" && req.path === "/loans")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  try {
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    const payloadObj = JSON.parse(Buffer.from(payload, "base64url").toString());
    const role = payloadObj.role;
    if (!role) {
      res.status(401).json({ error: "Missing role in token" });
      return;
    }

    if (role !== "staff") {
      res.status(403).json({ error: "Insufficient permissions" });
      return;
    }

    next();
  } catch (err) {
    res.status(401).json({ error: "Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for GET requests and static assets
  if (req.method === "GET" || req.path.startsWith("/static")) {
    return next();
  }

  // Only validate POST, PUT, PATCH requests with a body
  if ((req.method === "POST" || req.method === "PUT" || req.method === "PATCH") && req.body) {
    // Basic validation for required fields
    if (typeof req.body.title !== "string" || req.body.title.trim().length === 0) {
      return res.status(400).json({ error: "Title is required" });
    }

    if (typeof req.body.author !== "string" || req.body.author.trim().length === 0) {
      return res.status(400).json({ error: "Author is required" });
    }

    if (typeof req.body.isbn !== "string" || !/^(978|979)-?\d{1,5}-?\d{1,7}-?\d{1,7}-?\d$/.test(req.body.isbn)) {
      return res.status(400).json({ error: "Valid ISBN is required" });
    }

    if (typeof req.body.copies !== "number" || req.body.copies < 0) {
      return res.status(400).json({ error: "Number of copies must be a non-negative integer" });
    }
  }

  // If we reach here, all validations passed
  return next();
}

import { useEffect, useState } from "react";

interface Book {
  id: number;
  title: string;
  author: string;
  isbn: string;
  copies: number;
}

export function BookListPage() {
  const [books, setBooks] = useState<Book[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchBooks();
  }, []);

  const fetchBooks = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/books");
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setBooks(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
  };

  const filteredBooks = books.filter(book =>
    book.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
    book.author.toLowerCase().includes(searchTerm.toLowerCase())
  );

