export function SlotBookingPage() {
  const [timeSlots, setTimeSlots] = useState<TimeSlot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchTimeSlots();
  }, []);

  const fetchTimeSlots = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/slots');
      if (!response.ok) {
        throw new Error('Failed to fetch time slots');
      }
      const slots = await response.json();
      setTimeSlots(slots);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleBookSlot = async (slotId: string) => {
    try {
      const response = await fetch(`/api/slots/${slotId}/book`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error('Failed to book slot');
      }

      // Refresh the slot list after booking
      await fetchTimeSlots();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'system-ui, sans-serif',
    }}>
      <h1 style={{ textAlign: 'center' }}>Available Time Slots</h1>

      {timeSlots.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No available time slots.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {timeSlots.map((slot) => (
            <div 
              key={slot.id} 
              style={{
                border: '1px solid #ccc',
                borderRadius: '8px',
                padding: '15px',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                backgroundColor: slot.isBooked ? '#f0f0f0' : '#fff',
              }}
            >
              <div>
                <strong>{slot.startTime} - {slot.endTime}</strong>
                {!slot.isBooked && (
                  <span style={{ color: 'green', marginLeft: '10px' }}>
                    Available
                  </span>
                )}
              </div>

              {!slot.isBooked && (
                <button 
                  onClick={() => handleBookSlot(slot.id)}
                  style={{
                    backgroundColor: '#007bff',
                    color: 'white',
                    border: 'none',
                    borderRadius: '4px',
                    padding: '8px 16px',
                    cursor: 'pointer',
                  }}
                >
                  Book Slot
                </button>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

