import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const protectedPaths = [
    "/bookings",
    "/bookings/:id",
    "/staff/bookings",
    "/staff/bookings/:id"
  ];

  const isProtectedPath = protectedPaths.some(path => {
    if (path.includes(":")) {
      const pathWithoutParams = path.replace(/:\w+/g, ".*");
      const regex = new RegExp(`^${pathWithoutParams}$`);
      return regex.test(req.path);
    }
    return req.path === path;
  });

  // Skip validation for non-protected paths
  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role based on path
  const userRole = req.headers["x-user-role"] as string | undefined;
  const userId = req.headers["x-user-id"] as string | undefined;

  // If no user info, allow access (let other middleware handle auth)
  if (!userId || !userRole) {
    next();
    return;
  }

  // Define role requirements per path
  const roleRequirements: Record<string, string[]> = {
    "/bookings": ["customer"],
    "/bookings/:id": ["customer"],
    "/staff/bookings": ["staff"],
    "/staff/bookings/:id": ["staff"]
  };

  let requiredRoles: string[] = [];

  // Determine required roles based on path
  if (req.path.startsWith("/staff/bookings")) {
    requiredRoles = roleRequirements["/staff/bookings"];
  } else if (req.path.startsWith("/bookings")) {
    requiredRoles = roleRequirements["/bookings"];
  }

  // If no role requirements defined, allow access
  if (requiredRoles.length === 0) {
    next();
    return;
  }

  // Validate user role
  if (requiredRoles.includes(userRole)) {
    next();
  } else {
    res.status(403).json({ message: "Forbidden: Insufficient permissions" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHash, scrypt, randomBytes, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to handle password hashing for user registration
  // It should only process POST requests to the /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  const password = req.body.password;

  // Generate salt
  const salt = randomBytes(16).toString("hex");

  // Hash password with salt
  scrypt(password, salt, 64, (err, derivedKey) => {
    if (err) {
      next(err);
      return;
    }

    // Store hashed password and salt in request body
    req.body.hashedPassword = derivedKey.toString("hex");
    req.body.salt = salt;

    next();
  });
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /logout endpoint
  if (req.method !== "POST" || req.path !== "/logout") {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;

  if (!jwtSecret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const [header, payload, signature] = parts;

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // If we get here, token is valid - proceed to logout logic
    next();
  } catch (error) {
    res.status(401).json({ error: "Token verification failed" });
  }
}

