    { id: 2, name: "Jane Smith", email: "jane@example.com" }
  ],
  getCustomerById: async (id: number) => {
    const customers = await mockDatabase.getAllCustomers();
    return customers.find(customer => customer.id === id) || null;
  },
  createCustomer: async (customerData: { name: string; email: string }) => {
    const customers = await mockDatabase.getAllCustomers();
    const newId = Math.max(0, ...customers.map(c => c.id)) + 1;
    const newCustomer = {
      id: newId,
      name: customerData.name,
      email: customerData.email
    };
    return newCustomer;
  },
  updateCustomer: async (id: number, customerData: { name?: string; email?: string }) => {
    const customers = await mockDatabase.getAllCustomers();
    const customerIndex = customers.findIndex(customer => customer.id === id);
    if (customerIndex === -1) return null;

    const updatedCustomer = {
      ...customers[customerIndex],
      ...customerData
    };

    customers[customerIndex] = updatedCustomer;
    return updatedCustomer;
  },
  deleteCustomer: async (id: number) => {
    const customers = await mockDatabase.getAllCustomers();
    const customerIndex = customers.findIndex(customer => customer.id === id);
    if (customerIndex === -1) return false;

    customers.splice(customerIndex, 1);
    return true;
  }
};

