import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const ADMIN_ROLE = "admin";
const STAFF_ROLE = "staff";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to inventory management routes
  const inventoryPaths = ["/inventory", "/inventory/"];
  const isInventoryRoute = inventoryPaths.some(path => 
    req.path.startsWith(path) || 
    req.path === path
  );

  // Skip validation for non-inventory routes
  if (!isInventoryRoute) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  // For now, we'll allow both admin and staff to access inventory
  // In a real implementation, this would be more restrictive
  if (userRole === ADMIN_ROLE || userRole === STAFF_ROLE) {
    next();
    return;
  }

  // If no valid role is found, deny access
  res.status(403).json({ error: "Access denied: insufficient permissions" });
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT_SECRET is set
  if (!JWT_SECRET) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simulate token verification (in a real implementation, you'd decode and verify)
  const token = req.headers.authorization?.split(" ")[1];
  if (!token) {
    res.status(401).json({ error: "Missing token" });
    return;
  }

  // Verify token signature using HMAC-SHA256
  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(token.split(".")[0] + "." + token.split(".")[1])
    .digest();

  const actualSignature = Buffer.from(token.split(".")[2], "base64");

  try {
    const isValid = timingSafeEqual(expectedSignature, actualSignature);
    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  next();
}

