import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const contests = new Map<string, any>();

const createContest = (id: string, title: string, description: string, startTime: string, endTime: string) => {
  const contest = { id, title, description, startTime, endTime };
  contests.set(id, contest);
  return contest;
};

const getContest = (id: string) => {
  return contests.get(id);
};

const updateContest = (id: string, title?: string, description?: string, startTime?: string, endTime?: string) => {
  const existing = contests.get(id);
  if (!existing) return null;

  const updated = {
    ...existing,
    ...(title !== undefined && { title }),
    ...(description !== undefined && { description }),
    ...(startTime !== undefined && { startTime }),
    ...(endTime !== undefined && { endTime })
  };

  contests.set(id, updated);
  return updated;
};

const deleteContest = (id: string) => {
  return contests.delete(id);
};

// GET /contests - List all contests
router.get("/contests", (req: Request, res: Response) => {
  const contestList = Array.from(contests.values());
  res.json(contestList);
});

// GET /contests/:id - Get a specific contest by ID
router.get("/contests/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const contest = getContest(id);

  if (!contest) {
    return res.status(404).json({ error: "Contest not found" });
  }

  res.json(contest);
});

// POST /contests - Create a new contest
router.post("/contests", (req: Request, res: Response) => {
  const { id, title, description, startTime, endTime } = req.body;

  if (!id || !title || !description || !startTime || !endTime) {
    return res.status(400).json({ error: "Missing required fields: id, title, description, startTime, endTime" });
  }

  const existing = getContest(id);
  if (existing) {
    return res.status(400).json({ error: "Contest with this ID already exists" });
  }

  const newContest = createContest(id, title, description, startTime, endTime);
  res.status(201).json(newContest);
});

// PUT /contests/:id - Update an existing contest
router.put("/contests/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const { title, description, startTime, endTime } = req.body;

  const updated = updateContest(id, title, description, startTime, endTime);

  if (!updated) {
    return res.status(404).json({ error: "Contest not found" });
  }

  res.json(updated);
});

// DELETE /contests/:id - Delete a contest
router.delete("/contests/:id", (req: Request, res: Response) => {
  const id = req.params.id;

  const deleted = deleteContest(id);

  if (!deleted) {
    return res.status(404).json({ error: "Contest not found" });
  }

  res.json({ message: "Contest deleted successfully" });
});

