import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data structure to simulate leaderboard calculation
const participants = [
  { id: 1, name: "Alice", score: 100, submissionTime: 10 },
  { id: 2, name: "Bob", score: 150, submissionTime: 20 },
  { id: 3, name: "Charlie", score: 120, submissionTime: 15 },
];

// Helper function to calculate rankings
const calculateRankings = () => {
  return [...participants]
    .sort((a, b) => {
      if (b.score !== a.score) {
        return b.score - a.score; // Higher score first
      }
      return a.submissionTime - b.submissionTime; // Earlier submission time if scores are equal
    })
    .map((participant, index) => ({
      ...participant,
      rank: index + 1,
    }));
};

// GET /leaderboard - Get current leaderboard
router.get("/leaderboard", (req: Request, res: Response) => {
  try {
    const rankings = calculateRankings();
    return res.json(rankings);
  } catch (error) {
    return res.status(500).json({ error: "Failed to calculate leaderboard" });
  }
});

// POST /leaderboard - Update participant score and recalculate leaderboard
router.post("/leaderboard", (req: Request, res: Response) => {
  try {
    const { id, score, submissionTime } = req.body;

    if (!id || !score || !submissionTime) {
      return res.status(400).json({ error: "Missing required fields: id, score, submissionTime" });
    }

    const participantIndex = participants.findIndex(p => p.id === id);

    if (participantIndex === -1) {
      return res.status(404).json({ error: "Participant not found" });
    }

    participants[participantIndex] = {
      ...participants[participantIndex],
      score,
      submissionTime,
    };

    const rankings = calculateRankings();
    return res.status(201).json(rankings);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update leaderboard" });
  }
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT secret is set
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  // Simulate token verification (in a real implementation, you'd decode and verify the token)
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);

  // Verify token signature using HMAC-SHA256
  const expectedSignature = createHmac("sha256", jwtSecret)
    .update(token.split(".")[0] + "." + token.split(".")[1])
    .digest("hex");

  const actualSignature = token.split(".")[2];

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "hex");
    const actualBuffer = Buffer.from(actualSignature, "hex");

    if (timingSafeEqual(expectedBuffer, actualBuffer)) {
      next();
    } else {
      res.status(401).json({ error: "Unauthorized" });
    }
  } catch (error) {
    res.status(401).json({ error: "Unauthorized" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const isContestRoute = req.path.startsWith('/contest/') || req.path.startsWith('/admin/');

  if (!isContestRoute) {
    next();
    return;
  }

  // Check if user has proper role
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Unauthorized: Missing or invalid token' });
    return;
  }

  const token = authHeader.substring(7);

  try {
    // Simple token validation - in a real app, you'd decode and verify JWT properly
    const [userId, role] = token.split(':');

    if (!userId || !role) {
      res.status(401).json({ error: 'Unauthorized: Invalid token format' });
      return;
    }

    // For demo purposes, we'll just check if role is valid
    if (role !== 'participant' && role !== 'administrator') {
      res.status(403).json({ error: 'Forbidden: Invalid role' });
      return;
    }

    // Store role in request for later use
    (req as any).userRole = role;

    // Allow access for participants to contest routes
    if (role === 'participant' && req.path.startsWith('/contest/')) {
      next();
      return;
    }

    // Allow administrators full access
    if (role === 'administrator') {
      next();
      return;
    }

    // Deny access otherwise
    res.status(403).json({ error: 'Forbidden: Insufficient permissions' });
  } catch (error) {
    res.status(401).json({ error: 'Unauthorized: Invalid token' });
  }
}

