export const db = new DatabaseSync("./short-story-platform.db");

interface UserRow {
  id: number;
  username: string;
  email: string;
  password_hash: string;
  role: string;
  profile: string | null;
}

const createUsersTable = `
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE NOT NULL,
    email TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL,
    profile TEXT
  );
`;

db.exec(createUsersTable);

export const getAllUsers = (): UserRow[] => {
  const stmt = db.prepare("SELECT * FROM users");
  return stmt.all() as unknown as UserRow[];
};

export const getUserById = (id: number): UserRow | undefined => {
  const stmt = db.prepare("SELECT * FROM users WHERE id = ?");
  return stmt.get(id) as unknown as UserRow | undefined;
};

export const getUserByUsername = (username: string): UserRow | undefined => {
  const stmt = db.prepare("SELECT * FROM users WHERE username = ?");
  return stmt.get(username) as unknown as UserRow | undefined;
};

export const insertUser = (
  username: string,
  email: string,
  passwordHash: string,
  role: string,
  profile: string | null = null
): number => {
  const stmt = db.prepare(
    "INSERT INTO users (username, email, password_hash, role, profile) VALUES (?, ?, ?, ?, ?)"
  );
  const result = stmt.run(username, email, passwordHash, role, profile);
  return Number(result.lastInsertRowid);
};

export const updateUser = (
  id: number,
  username: string,
  email: string,
  passwordHash: string,
  role: string,
  profile: string | null = null
): boolean => {
  const stmt = db.prepare(
    "UPDATE users SET username = ?, email = ?, password_hash = ?, role = ?, profile = ? WHERE id = ?"
  );
  const result = stmt.run(username, email, passwordHash, role, profile, id);
  return result.changes > 0;
};

export const deleteUser = (id: number): boolean => {
  const stmt = db.prepare("DELETE FROM users WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
};

