import { Router, type Request, type Response } from "express";
import { insertStory, updateStory, getStoryById, getAllStories, deleteStory } from "../db/stories-table";
import { getUserByUsername } from "../db/users-table";

export const router = Router();

// Get all stories
router.get("/", (req: Request, res: Response) => {
  try {
    const stories = getAllStories();
    return res.json(stories);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch stories" });
  }
});

// Get a story by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid story ID" });
    }

    const story = getStoryById(id);
    if (!story) {
      return res.status(404).json({ error: "Story not found" });
    }

    return res.json(story);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch story" });
  }
});

// Create a new story
router.post("/", (req: Request, res: Response) => {
  try {
    const { title, content, author, status } = req.body;

    if (!title || !content || !author) {
      return res.status(400).json({ error: "Title, content, and author are required" });
    }

    const user = getUserByUsername(author);
    if (!user) {
      return res.status(404).json({ error: "Author not found" });
    }

    const author_id = user.id;
    const newStoryId = insertStory(title, content, author_id, status || "draft", new Date().toISOString(), null);

    return res.status(201).json({ id: newStoryId });
  } catch (error) {
    return res.status(500).json({ error: "Failed to create story" });
  }
});

// Update a story
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid story ID" });
    }

    const existingStory = getStoryById(id);
    if (!existingStory) {
      return res.status(404).json({ error: "Story not found" });
    }

    const { title, content, status } = req.body;

    updateStory(id, title || existingStory.title, content || existingStory.content, status || existingStory.status, existingStory.created_at, existingStory.updated_at);

    return res.json({ message: "Story updated successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to update story" });
  }
});

// Delete a story
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid story ID" });
    }

    const existingStory = getStoryById(id);
    if (!existingStory) {
      return res.status(404).json({ error: "Story not found" });
    }

    deleteStory(id);

    return res.json({ message: "Story deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete story" });
  }
});

