import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as authRouter } from "../routes/authentication-service";
import { router as storyRouter } from "../routes/story-management-service";
import { router as userRouter } from "../routes/user-management-service";
import { router as mediaRouter } from "../routes/media-management-service";

const JWT_SECRET = process.env.JWT_SECRET;

function decodeToken(token: string): { userId: string; role: string } | null {
  try {
    const payload = token.split(".")[1];
    const decoded = Buffer.from(payload, "base64").toString();
    return JSON.parse(decoded);
  } catch (err) {
    return null;
  }
}

function verifySignature(token: string, secret: string): boolean {
  const [header, payload, signature] = token.split(".");
  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  const signatureBuffer = Buffer.from(signature, "base64url");
  const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

  return timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to authentication routes
  if (!(req.method === "POST" && (
    req.path.startsWith("/auth") ||
    req.path.startsWith("/stories") ||
    req.path.startsWith("/users") ||
    req.path.startsWith("/media")
  ))) {
    return next();
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const token = authHeader.substring(7);

  if (!JWT_SECRET) {
    return res.status(500).json({ error: "Server configuration error" });
  }

  const decoded = decodeToken(token);
  if (!decoded) {
    return res.status(401).json({ error: "Invalid token" });
  }

  if (!verifySignature(token, JWT_SECRET)) {
    return res.status(401).json({ error: "Invalid token" });
  }

  // Token is valid, proceed
  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as authRouter } from "../routes/authentication-service";
import { router as storyRouter } from "../routes/story-management-service";
import { router as userRouter } from "../routes/user-management-service";
import { router as mediaRouter } from "../routes/media-management-service";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for authentication routes
  const authPaths = [authRouter, storyRouter, userRouter, mediaRouter];
  const isAuthRoute = authPaths.some(router => 
    req.path.startsWith((router as any).stack?.[0]?.route?.path || '')
  );

  if (isAuthRoute) {
    return next();
  }

  // For non-auth routes, validate input
  if (req.method === "POST" || req.method === "PUT" || req.method === "PATCH") {
    if (req.body) {
      // Basic sanitization - remove script tags and other dangerous content
      const sanitize = (str: string): string => {
        return str
          .replace(/<script[^>]*>.*?<\/script>/gi, '')
          .replace(/<iframe[^>]*>.*?<\/iframe>/gi, '')
          .replace(/<object[^>]*>.*?<\/object>/gi, '')
          .replace(/<embed[^>]*>.*?<\/embed>/gi, '');
      };

      // Sanitize body fields
      const sanitizedBody = { ...req.body };
      Object.keys(sanitizedBody).forEach(key => {
        if (typeof sanitizedBody[key] === 'string') {
          sanitizedBody[key] = sanitize(sanitizedBody[key]);
        }
      });

      // Validate required fields
      if (req.body.title && typeof req.body.title !== 'string') {
        return res.status(400).json({ error: 'Title must be a string' });
      }

      if (req.body.content && typeof req.body.content !== 'string') {
        return res.status(400).json({ error: 'Content must be a string' });
      }

      // If we get here, everything looks good
      req.body = sanitizedBody;
      return next();
    }
  }

  // For all other requests, continue normally
  return next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const MAX_REQUESTS = 100;
const TIME_WINDOW_MS = 15 * 60 * 1000; // 15 minutes

// In-memory storage for tracking requests
const requestCounts: Map<string, { count: number; windowStart: number }> = new Map();

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply rate limiting to specific routes
  const isUserRoute = req.path.startsWith("/users") ||
                      req.path.startsWith("/stories") ||
                      req.path.startsWith("/media") ||
                      req.path.startsWith("/auth");

  if (!isUserRoute) {
    next();
    return;
  }

  const clientIP = getClientIP(req);
  const now = Date.now();

  // Initialize or update request count for this IP
  const stored = requestCounts.get(clientIP);
  let count = 0;
  let windowStart = now;

  if (stored) {
    if (now - stored.windowStart < TIME_WINDOW_MS) {
      count = stored.count + 1;
      windowStart = stored.windowStart;
    } else {
      count = 1;
      windowStart = now;
    }
  } else {
    count = 1;
    windowStart = now;
  }

  // Update the stored data
  requestCounts.set(clientIP, { count, windowStart });

  // Check if limit exceeded
  if (count > MAX_REQUESTS) {
    res.status(429).json({ error: "Too many requests" });
    return;
  }

  next();
}

function getClientIP(req: Request): string {
  return (
    req.headers["x-forwarded-for"]?.toString().split(",")[0]?.trim() ||
    req.connection.remoteAddress ||
    req.socket.remoteAddress ||
    (req.connection as any).socket?.remoteAddress ||
    ""
  );
}

import { useState, useEffect } from "react";

export function StoryEditor() {
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
