  const [newTag, setNewTag] = useState("");
  const [isSaving, setIsSaving] = useState(false);
  const [saveMessage, setSaveMessage] = useState("");

  // Load existing story if editing
  useEffect(() => {
    const savedTitle = localStorage.getItem("storyTitle");
    const savedContent = localStorage.getItem("storyContent");
    const savedTags = localStorage.getItem("storyTags");

    if (savedTitle) setTitle(savedTitle);
    if (savedContent) setContent(savedContent);
    if (savedTags) setTags(JSON.parse(savedTags));
  }, []);

  const handleAddTag = () => {
    if (newTag.trim() && !tags.includes(newTag.trim())) {
      setTags([...tags, newTag.trim()]);
      setNewTag("");
    }
  };

  const handleRemoveTag = (tagToRemove: string) => {
    setTags(tags.filter(tag => tag !== tagToRemove));
  };

  const handleSave = async () => {
    setIsSaving(true);
    setSaveMessage("");

    try {
      // Save to localStorage for demo purposes
      localStorage.setItem("storyTitle", title);
      localStorage.setItem("storyContent", content);
      localStorage.setItem("storyTags", JSON.stringify(tags));

      setSaveMessage("Story saved successfully!");
      setTimeout(() => setSaveMessage(""), 3000);
