          id="content"
          value={content}
          onChange={(e) => setContent(e.target.value)}
          style={{
            width: "100%",
            height: "300px",
            padding: "10px",
            borderRadius: "4px",
            border: "1px solid #ccc",
            fontFamily: "inherit"
          }}
          placeholder="Start writing your story here..."
        />
