        <label htmlFor="tags" style={{ display: "block", marginBottom: "5px" }}>
          Tags
        </label>
        <div style={{ display: "flex", gap: "10px", marginBottom: "10px" }}>
          <input
            id="tags"
            type="text"
            value={newTag}
            onChange={(e) => setNewTag(e.target.value)}
            style={{
              flex: 1,
              padding: "10px",
              borderRadius: "4px",
              border: "1px solid #ccc"
            }}
            placeholder="Add a tag"
          />
          <button
