            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";

interface Story {
  id: string;
  title: string;
  lastModified: string;
  wordCount: number;
}

interface Activity {
  id: string;
  description: string;
  timestamp: string;
}

export function Dashboard() {
  const [stories, setStories] = useState<Story[]>([]);
  const [activities, setActivities] = useState<Activity[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        // Fetch user's stories
        const storiesResponse = await fetch('/api/user-management-service/users/:userId/stories');
        if (!storiesResponse.ok) throw new Error('Failed to fetch stories');
        const storiesData: Story[] = await storiesResponse.json();
        setStories(storiesData);

        // Fetch recent activities
        const activitiesResponse = await fetch('/api/user-management-service/users/:userId/media');
        if (!activitiesResponse.ok) throw new Error('Failed to fetch activities');
        const activitiesData: Activity[] = await activitiesResponse.json();
        setActivities(activitiesData);

        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Your Dashboard</h1>

      <section style={{ marginBottom: '30px' }}>
        <h2>My Stories</h2>
        {stories.length === 0 ? (
          <p>No stories yet. Start writing!</p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
            {stories.map((story) => (
              <div 
                key={story.id} 
                style={{ 
                  border: '1px solid #ccc', 
                  borderRadius: '8px', 
                  padding: '15px', 
                  display: 'flex', 
                  justifyContent: 'space-between', 
                  alignItems: 'center'
                }}
              >
                <div>
                  <h3>{story.title}</h3>
                  <p>Last modified: {new Date(story.lastModified).toLocaleDateString()}</p>
                </div>
                <button 
                  style={{ 
                    backgroundColor: '#007bff', 
                    color: 'white', 
                    border: 'none', 
                    borderRadius: '4px', 
                    padding: '8px 16px', 
                    cursor: 'pointer'
                  }}
                >
                  Edit
                </button>
              </div>
            ))}
          </div>
        )}
      </section>

      <section style={{ marginBottom: '30px' }}>
        <h2>Recent Activity</h2>
        {activities.length === 0 ? (
          <p>No recent activity.</p>
        ) : (
          <ul style={{ listStyle: 'none', padding: 0 }}>
            {activities.map((activity) => (
              <li 
                key={activity.id} 
                style={{ 
                  borderBottom: '1px solid #eee', 
                  padding: '10px 0'
                }}
              >
                <p>{activity.description}</p>
                <small>{new Date(activity.timestamp).toLocaleString()}</small>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h2>Quick Tools</h2>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
          <button 
            style={{ 
              backgroundColor: '#28a745', 
              color: 'white', 
              border: 'none', 
              borderRadius: '4px', 
              padding: '10px 15px', 
              cursor: 'pointer'
            }}
          >
            New Story
