import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to POST, PUT, DELETE requests
  // to newspaper management routes
  const isManagementRequest = 
    (req.method === "POST" || req.method === "PUT" || req.method === "DELETE") &&
    req.path.startsWith("/newspapers");

  if (!isManagementRequest) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  // Verify JWT signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  // Simple verification of token structure (basic validation)
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  const [header, payload, signature] = parts;

  try {
    // Create expected signature
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const expectedBuffer = Buffer.from(expectedSignature, "utf8");
    const actualBuffer = Buffer.from(signature, "utf8");

    if (!timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Token verification failed" });
    return;
  }

  // Decode payload to check role (simplified for this example)
  try {
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString("utf8"));

    // Check if user has staff role
    if (decodedPayload.role !== "staff") {
      res.status(403).json({ error: "Forbidden: Staff access required" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token payload" });
    return;
  }

  // If we get here, the user is authorized
  next();
}

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to the upload endpoint
  if (req.method !== "POST" || req.path !== "/upload") {
    next();
    return;
  }

  // Check if file upload is present
  if (!req.files || Object.keys(req.files).length === 0) {
    res.status(400).json({ error: "No file uploaded" });
    return;
  }

  // Get the file from the request
  const file = Array.isArray(req.files.file) ? req.files.file[0] : req.files.file;

  // Validate file type - only allow PDF, JPG, PNG
  const allowedTypes = ["application/pdf", "image/jpeg", "image/png"];
  if (!allowedTypes.includes(file.mimetype)) {
    res.status(400).json({ error: "Invalid file type" });
    return;
  }

  // Validate file size - max 10MB
  const maxSize = 10 * 1024 * 1024; // 10MB in bytes
  if (file.size > maxSize) {
    res.status(400).json({ error: "File too large" });
    return;
  }

  // If we reach here, the file is valid
  next();
}

