import { Router, type Request, type Response } from "express";

export const router = Router();

// In-memory cart storage (in a real app, this would be a database)
const carts: Record<string, { itemId: string; quantity: number }[]> = {};

// Helper to get cart for user
const getUserCart = (userId: string) => {
  if (!carts[userId]) {
    carts[userId] = [];
  }
  return carts[userId];
};

// Add item to cart
router.post("/:userId/items", (req: Request, res: Response) => {
  const { userId } = req.params;
  const { itemId, quantity } = req.body;

  if (!itemId || quantity === undefined || quantity <= 0) {
    return res.status(400).json({ error: "Item ID and valid quantity required" });
  }

  const userCart = getUserCart(userId);
  const existingItemIndex = userCart.findIndex(item => item.itemId === itemId);

  if (existingItemIndex >= 0) {
    userCart[existingItemIndex].quantity += quantity;
  } else {
    userCart.push({ itemId, quantity });
  }

  return res.status(201).json({ message: "Item added to cart", cart: userCart });
});

// Update item quantity in cart
router.put("/:userId/items/:itemId", (req: Request, res: Response) => {
  const { userId, itemId } = req.params;
  const { quantity } = req.body;

  if (quantity === undefined || quantity <= 0) {
    return res.status(400).json({ error: "Valid quantity required" });
  }

  const userCart = getUserCart(userId);
  const itemIndex = userCart.findIndex(item => item.itemId === itemId);

  if (itemIndex < 0) {
    return res.status(404).json({ error: "Item not found in cart" });
  }

  userCart[itemIndex].quantity = quantity;
  return res.json({ message: "Item quantity updated", cart: userCart });
});

// Remove item from cart
router.delete("/:userId/items/:itemId", (req: Request, res: Response) => {
  const { userId, itemId } = req.params;

  const userCart = getUserCart(userId);
  const itemIndex = userCart.findIndex(item => item.itemId === itemId);

  if (itemIndex < 0) {
    return res.status(404).json({ error: "Item not found in cart" });
  }

  userCart.splice(itemIndex, 1);
