import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply security checks to payment-related routes
  if (!req.path.startsWith("/payment") || req.method !== "POST") {
    next();
    return;
  }

  // Check if card data is present in request body
  const cardData = req.body?.card;
  if (!cardData) {
    // If no card data, allow the request to proceed
    next();
    return;
  }

  // Validate required card fields according to PCI DSS requirements
  const requiredFields = ["number", "expiry", "cvv"];
  const missingFields = requiredFields.filter(field => !cardData[field]);

  if (missingFields.length > 0) {
    // Reject requests with incomplete card data
    res.status(400).json({
      error: "Incomplete card information provided",
      missingFields
    });
    return;
  }

  // Basic validation of card number format (13-19 digits)
  const cardNumber = cardData.number.replace(/\s/g, "");
  if (!/^[0-9]{13,19}$/.test(cardNumber)) {
    res.status(400).json({
      error: "Invalid card number format"
    });
    return;
  }

  // Basic validation of expiry date format (MM/YY)
  const expiry = cardData.expiry;
  if (!/^(0[1-9]|1[0-2])\/([0-9]{2})$/.test(expiry)) {
    res.status(400).json({
      error: "Invalid expiry date format. Expected MM/YY"
    });
    return;
  }

  // Basic validation of CVV (3-4 digits)
  const cvv = cardData.cvv;
  if (!/^[0-9]{3,4}$/.test(cvv)) {
    res.status(400).json({
      error: "Invalid CVV format. Expected 3-4 digits"
    });
    return;
  }

  // If we reach here, the card data appears to be valid according to basic PCI DSS requirements
  // In a real implementation, additional validations and security measures would be applied
  next();
}

