        setPaymentMethods([
          { id: "1", type: "Visa", lastFour: "1234", expiry: "12/25" },
          { id: "2", type: "Mastercard", lastFour: "5678", expiry: "08/24" }
        ]);

        setLoading(false);
      } catch (err) {
        setError("Failed to load user data");
        setLoading(false);
      }
