                  <span>{order.date}</span>
                </div>
                <div style={{ display: "flex", justifyContent: "space-between", marginTop: "10px" }}>
                  <span>Total: ${order.total.toFixed(2)}</span>
                  <span>Status: {order.status}</span>
                </div>
              </div>
            ))}
