      <div>
        <h2>Saved Payment Methods</h2>
        {paymentMethods.length > 0 ? (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {paymentMethods.map(method => (
              <div key={method.id} style={{ border: "1px solid #ddd", padding: "15px", borderRadius: "8px" }}>
                <div style={{ display: "flex", justifyContent: "space-between" }}>
                  <span><strong>{method.type}</strong></span>
                  <span>•••• {method.lastFour}</span>
                </div>
                <div style={{ display: "flex", justifyContent: "space-between", marginTop: "10px" }}>
                  <span>Expiry: {method.expiry}</span>
                  <button style={{ backgroundColor: "#007bff", color: "white", border: "none", padding: "5px 10px", borderRadius: "4px", cursor: "pointer" }}>
                    Remove
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p>No saved payment methods.</p>
        )}

        <button style={{ marginTop: "20px", backgroundColor: "#28a745", color: "white", border: "none", padding: "10px 20px", borderRadius: "4px", cursor: "pointer", width: "100%" }}>
          Add New Payment Method
        </button>
      </div>
    </div>
  );
}

