  const id = req.params.id;
  const { name, startDate, endDate, location, status } = req.body;

  const tournamentIndex = tournaments.findIndex(t => t.id === id);

  if (tournamentIndex === -1) {
    return res.status(404).json({ message: "Tournament not found" });
  }

  // Validate tournament data
  const updatedTournament = {
    ...tournaments[tournamentIndex],
    name: name || tournaments[tournamentIndex].name,
    startDate: startDate || tournaments[tournamentIndex].startDate,
    endDate: endDate || tournaments[tournamentIndex].endDate,
