import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (!(req.method === "POST" && req.path === "/login")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
  }

  const token = authHeader.substring(7);

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return res.status(500).json({ error: "Internal Server Error: JWT_SECRET not configured" });
  }

  const parts = token.split(".");
  if (parts.length !== 3) {
    return res.status(401).json({ error: "Unauthorized: Invalid token format" });
  }

  const [header, payload, signature] = parts;

  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  const signatureBuffer = Buffer.from(signature, "base64url");
  const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

  try {
    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      return res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    }
  } catch {
    return res.status(401).json({ error: "Unauthorized: Invalid token" });
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply RBAC to POST, PUT, DELETE requests
  if (!['POST', 'PUT', 'DELETE'].includes(req.method)) {
    next();
    return;
  }

  // Define protected routes
  const protectedPaths = [
    '/tournaments',
    '/fixtures'
  ];

  // Check if request path is protected
  const isProtectedPath = protectedPaths.some(path => 
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Get authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Verify token signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: 'Server configuration error' });
    return;
  }

  // Simple token verification (in a real app, use proper JWT library)
  try {
    const [payload, signature] = token.split('.');
    if (!payload || !signature) {
      res.status(401).json({ error: 'Invalid token format' });
      return;
    }

    // Recreate signature
    const expectedSignature = createHmac('sha256', secret)
      .update(payload)
      .digest('base64url');

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(signature, 'base64url'),
      Buffer.from(expectedSignature, 'base64url')
    );

    if (!isValid) {
      res.status(401).json({ error: 'Invalid token' });
      return;
    }

    // Decode payload to check role
    const payloadBuffer = Buffer.from(payload, 'base64url');
    const payloadStr = payloadBuffer.toString('utf-8');
    const payloadObj = JSON.parse(payloadStr);

    // Check if user has required role
    if (payloadObj.role !== 'admin') {
      res.status(403).json({ error: 'Insufficient permissions' });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for GET requests without body
  if (req.method === "GET" && !req.body) {
    return next();
  }

  // Only validate POST, PUT, PATCH requests
  if (!['POST', 'PUT', 'PATCH'].includes(req.method)) {
    return next();
  }

  // Basic input validation - check for potentially dangerous patterns
  const dangerousPatterns = [
    /<script[^>]*>.*?<\/script>/i,
    /javascript:/i,
    /vbscript:/i,
    /on\w+\s*=\s*['"][^'"]*['"]/, // event handlers
    /<[^>]*on\w+\s*=\s*[^>]*>/i, // HTML event attributes
  ];

  const requestBody = JSON.stringify(req.body);

  for (const pattern of dangerousPatterns) {
    if (pattern.test(requestBody)) {
      return res.status(400).json({ error: 'Invalid input detected' });
    }
  }

  // If we get here, input is valid
  next();
}

import { useEffect, useState } from "react";

interface Tournament {
  id: number;
  name: string;
  startDate: string;
  endDate: string;
  location: string;
}

export function TournamentListPage() {
  const [tournaments, setTournaments] = useState<Tournament[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchTournaments();
  }, []);

  const fetchTournaments = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/tournaments`);
      if (!response.ok) {
        throw new Error(`Failed to fetch tournaments: ${response.status}`);
      }
      const data = await response.json();
      setTournaments(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const filteredTournaments = tournaments.filter(tournament =>
    tournament.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    tournament.location.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={containerStyle}>
      <h1 style={{ textAlign: "center", marginBottom: "20px" }}>Tournaments</h1>

      <div style={{ marginBottom: "20px" }}>
        <input
          type="text"
          placeholder="Search tournaments..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={searchInputStyle}
        />
      </div>

      <div style={{ display: "flex", justifyContent: "center", marginBottom: "20px" }}>
        <button 
          onClick={() => window.location.href = "/create-tournament"}
          style={createButtonStyle}
        >
          Create New Tournament
        </button>
      </div>

      {filteredTournaments.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No tournaments found.</p>
      ) : (
        <div style={gridStyle}>
          {filteredTournaments.map(tournament => (
            <div key={tournament.id} style={cardStyle}>
              <h3 style={{ margin: "0 0 10px 0" }}>{tournament.name}</h3>
              <p style={{ margin: "5px 0" }}>
                <strong>Location:</strong> {tournament.location}
              </p>
              <p style={{ margin: "5px 0" }}>
                <strong>Dates:</strong> {new Date(tournament.startDate).toLocaleDateString()} - {new Date(tournament.endDate).toLocaleDateString()}
              </p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

