  status: 'scheduled' | 'completed' | 'postponed';
}

interface Tournament {
  id: number;
  name: string;
}

export function FixtureListPage() {
  const [tournaments, setTournaments] = useState<Tournament[]>([]);
  const [selectedTournamentId, setSelectedTournamentId] = useState<number | null>(null);
  const [fixtures, setFixtures] = useState<Fixture[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Fetch tournaments
  useEffect(() => {
    const fetchTournaments = async () => {
      try {
        // Simulate API call
        await new Promise(resolve => setTimeout(resolve, 500));
        setTournaments([
          { id: 1, name: 'Premier League' },
          { id: 2, name: 'Championship' },
          { id: 3, name: 'League One' },
        ]);
      } catch (err) {
        setError('Failed to load tournaments');
      } finally {
        setLoading(false);
      }
    };

    fetchTournaments();
  }, []);

  // Fetch fixtures when tournament changes
  useEffect(() => {
    if (selectedTournamentId === null) return;

    const fetchFixtures = async () => {
      setLoading(true);
      try {
        // Simulate API call
        await new Promise(resolve => setTimeout(resolve, 500));
        setFixtures([
          {
            id: 1,
            homeTeam: 'Manchester United',
            awayTeam: 'Liverpool',
            date: '2023-10-15T15:00:00Z',
            venue: 'Old Trafford',
            status: 'scheduled'
          },
          {
            id: 2,
            homeTeam: 'Chelsea',
            awayTeam: 'Arsenal',
            date: '2023-10-16T17:30:00Z',
            venue: 'Stamford Bridge',
            status: 'completed'
          },
          {
            id: 3,
            homeTeam: 'Manchester City',
            awayTeam: 'Tottenham',
            date: '2023-10-17T14:00:00Z',
            venue: 'Etihad Stadium',
            status: 'postponed'
          }
        ]);
      } catch (err) {
        setError('Failed to load fixtures');
      } finally {
        setLoading(false);
      }
    };

    fetchFixtures();
  }, [selectedTournamentId]);

  const filteredFixtures = fixtures
    .filter(fixture => {
      const matchesSearch = 
        fixture.homeTeam.toLowerCase().includes(searchTerm.toLowerCase()) ||
        fixture.awayTeam.toLowerCase().includes(searchTerm.toLowerCase()) ||
        fixture.venue.toLowerCase().includes(searchTerm.toLowerCase());

      const matchesStatus = statusFilter === 'all' || fixture.status === statusFilter;

      return matchesSearch && matchesStatus;
    });

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', {
      weekday: 'short',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'completed': return '#4ade80';
      case 'postponed': return '#f87171';
      default: return '#fbbf24';
    }
  };

  if (loading) {
    return (
      <div style={{
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        minHeight: '200px',
        fontFamily: 'system-ui, sans-serif',
        fontSize: '18px'
      }}>
        Loading...
      </div>
    );
  }

  return (
    <div style={{
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <h1 style={{
        textAlign: 'center',
        marginBottom: '30px',
        fontSize: '24px',
        fontWeight: 'bold'
      }}>
        Tournament Fixtures
