import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (!(req.method === "POST" && req.path === "/login")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
  }

  const token = authHeader.substring(7);

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return res.status(500).json({ error: "Internal Server Error: JWT_SECRET not configured" });
  }

  const parts = token.split(".");
  if (parts.length !== 3) {
    return res.status(401).json({ error: "Unauthorized: Invalid token format" });
  }

  const [header, payload, signature] = parts;

  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  const signatureBuffer = Buffer.from(signature, "base64url");
  const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

  try {
    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      return res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    }
  } catch {
    return res.status(401).json({ error: "Unauthorized: Invalid token" });
  }

  next();
}

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for GET requests without body
  if (req.method === "GET" && !req.body) {
    return next();
  }

  // Only validate POST, PUT, PATCH requests
  if (!['POST', 'PUT', 'PATCH'].includes(req.method)) {
    return next();
  }

  // Basic input validation - check for potentially dangerous patterns
  const dangerousPatterns = [
    /<script[^>]*>.*?<\/script>/i,
    /javascript:/i,
    /vbscript:/i,
    /on\w+\s*=\s*['"][^'"]*['"]/, // event handlers
    /<[^>]*on\w+\s*=\s*[^>]*>/i, // HTML event attributes
  ];

  const requestBody = JSON.stringify(req.body);

  for (const pattern of dangerousPatterns) {
    if (pattern.test(requestBody)) {
      return res.status(400).json({ error: 'Invalid input detected' });
    }
  }

  // If we get here, input is valid
  next();
}

