import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST /login and GET /profile routes
  if (!(req.method === "POST" && req.path === "/login") && !(req.method === "GET" && req.path === "/profile")) {
    return next();
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
  }

  const token = authHeader.substring(7);

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return res.status(500).json({ error: "Internal Server Error: JWT secret not configured" });
  }

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) {
      return res.status(401).json({ error: "Unauthorized: Invalid token format" });
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      return res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    }

    // If we get here, the token is valid
    next();
  } catch (error) {
    return res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply RBAC to protected routes
  const protectedPaths = [
    /^\/api\/courses\/.*/,
    /^\/api\/lessons\/.*/,
    /^\/api\/enrollments\/.*/
  ];

  const isProtectedPath = protectedPaths.some(path => path.test(req.path));

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has proper role for the action
  const userRole = req.headers["x-user-role"] as string | undefined;
  const userPermissions = req.headers["x-user-permissions"] as string | undefined;

  if (!userRole) {
    res.status(401).json({ error: "Unauthorized: Missing role header" });
    return;
  }

  // Define role permissions
  const rolePermissions: Record<string, string[]> = {
    student: ["read"],
    instructor: ["read", "write"],
    admin: ["read", "write", "delete"]
  };

  const requiredPermission = getRequiredPermission(req.method);
  const userPerms = userPermissions ? userPermissions.split(",") : [];
  const userRolePerms = rolePermissions[userRole] || [];

  // Check if user has permission
  if (!userPerms.includes(requiredPermission) && !userRolePerms.includes(requiredPermission)) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  next();
}

function getRequiredPermission(method: string): string {
  switch (method) {
    case "GET":
      return "read";
    case "POST":
    case "PUT":
    case "PATCH":
      return "write";
    case "DELETE":
      return "delete";
    default:
      return "read";
  }
}

