  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center", marginBottom: "20px" }}>{property.title}</h1>

      <div style={{ marginBottom: "20px" }}>
        {property.images.length > 0 ? (
          <img 
            src={property.images[0]} 
            alt={property.title} 
            style={{ width: "100%", borderRadius: "8px" }} 
          />
        ) : (
          <div style={{ height: "300px", backgroundColor: "#f0f0f0", borderRadius: "8px", display: "flex", alignItems: "center", justifyContent: "center" }}>
            No image available
          </div>
        )}
      </div>

      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "20px", flexWrap: "wrap" }}>
        <div style={{ flex: "1", minWidth: "200px", marginRight: "20px" }}>
          <h2 style={{ marginTop: 0 }}>Description</h2>
          <p>{property.description}</p>
        </div>

        <div style={{ flex: "1", minWidth: "200px" }}>
          <h2 style={{ marginTop: 0 }}>Details</h2>
          <p><strong>Price:</strong> ${property.price}/month</p>
          <p><strong>Bedrooms:</strong> {property.bedrooms}</p>
          <p><strong>Bathrooms:</strong> {property.bathrooms}</p>
