import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user data storage
const users = new Map<string, { email: string; password: string; role: string }>();

// Mock session storage
const sessions = new Map<string, { userId: string; expiresAt: Date }>();

// Helper to generate a mock session ID
const generateSessionId = () => Math.random().toString(36).substring(2, 15);

// User Registration
router.post("/register", (req: Request, res: Response) => {
  const { email, password, role = "user" } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  if (users.has(email)) {
    return res.status(400).json({ error: "User already exists" });
  }

  users.set(email, { email, password, role });
  return res.status(201).json({ email, role });
});

// User Login
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  const user = users.get(email);
  if (!user || user.password !== password) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Create a mock session
  const sessionId = generateSessionId();
  const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000); // 24 hours
  sessions.set(sessionId, { userId: email, expiresAt });

  res.cookie("sessionId", sessionId, { httpOnly: true, maxAge: 24 * 60 * 60 * 1000 });
  return res.json({ message: "Login successful", role: user.role });
});

// Session Management - Check if user is authenticated
router.get("/me", (req: Request, res: Response) => {
  const sessionId = req.cookies.sessionId;

  if (!sessionId) {
    return res.status(401).json({ error: "No active session" });
  }

  const session = sessions.get(sessionId);
  if (!session || session.expiresAt < new Date()) {
    sessions.delete(sessionId);
    return res.status(401).json({ error: "Session expired" });
  }

  const user = users.get(session.userId);
  if (!user) {
    return res.status(401).json({ error: "User not found" });
  }

  return res.json({ email: user.email, role: user.role });
});

// Role-based Access Control - Middleware to check role
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    const sessionId = req.cookies.sessionId;

    if (!sessionId) {
      return res.status(401).json({ error: "No active session" });
    }

    const session = sessions.get(sessionId);
    if (!session || session.expiresAt < new Date()) {
      sessions.delete(sessionId);
      return res.status(401).json({ error: "Session expired" });
    }

    const user = users.get(session.userId);
    if (!user || user.role !== requiredRole) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }

    next();
  };
};

// Example protected route for admin only
router.get("/admin", requireRole("admin"), (req: Request, res: Response) => {
  return res.json({ message: "Admin access granted" });
});

// Logout
router.post("/logout", (req: Request, res: Response) => {
  const sessionId = req.cookies.sessionId;

  if (sessionId) {
    sessions.delete(sessionId);
    res.clearCookie("sessionId");
  }

  return res.json({ message: "Logged out successfully" });
});

