// Mock database functions - in a real app these would connect to a database
const mockDatabase = {
  findAll: (): Promise<Book[]> => Promise.resolve([
    { id: 1, title: "1984", author: "George Orwell", isbn: "978-0-452-28423-4", coverImage: "https://example.com/1984.jpg" },
    { id: 2, title: "To Kill a Mockingbird", author: "Harper Lee", isbn: "978-0-06-112008-4", coverImage: "https://example.com/mockingbird.jpg" }
  ]),
  findById: (id: number): Promise<Book | null> => Promise.resolve(
    [{ id: 1, title: "1984", author: "George Orwell", isbn: "978-0-452-28423-4", coverImage: "https://example.com/1984.jpg" },
     { id: 2, title: "To Kill a Mockingbird", author: "Harper Lee", isbn: "978-0-06-112008-4", coverImage: "https://example.com/mockingbird.jpg" }]
      .find(book => book.id === id) || null
  ),
  create: (book: Omit<Book, "id">): Promise<Book> => Promise.resolve({
    id: Date.now(),
    ...book
  }),
  update: (id: number, book: Partial<Omit<Book, "id">>): Promise<Book | null> => {
    const existingBook = [{ id: 1, title: "1984", author: "George Orwell", isbn: "978-0-452-28423-4", coverImage: "https://example.com/1984.jpg" },
                         { id: 2, title: "To Kill a Mockingbird", author: "Harper Lee", isbn: "978-0-06-112008-4", coverImage: "https://example.com/mockingbird.jpg" }]
                      .find(b => b.id === id);
    if (!existingBook) return Promise.resolve(null);
    return Promise.resolve({
      ...existingBook,
      ...book
    });
  },
  delete: (id: number): Promise<boolean> => {
    const books = [{ id: 1, title: "1984", author: "George Orwell", isbn: "978-0-452-28423-4", coverImage: "https://example.com/1984.jpg" },
                   { id: 2, title: "To Kill a Mockingbird", author: "Harper Lee", isbn: "978-0-06-112008-4", coverImage: "https://example.com/mockingbird.jpg" }];
    const index = books.findIndex(b => b.id === id);
    if (index === -1) return Promise.resolve(false);
    books.splice(index, 1);
    return Promise.resolve(true);
  }
};

interface Book {
  id: number;
  title: string;
  author: string;
  isbn: string;
  coverImage: string;
}

