import { useState } from "react";

export function ReviewFormPage() {
  const [rating, setRating] = useState<number | null>(null);
  const [reviewText, setReviewText] = useState<string>("");
  const [tags, setTags] = useState<string[]>([]);
  const [newTag, setNewTag] = useState<string>("");
  const [isSubmitting, setIsSubmitting] = useState<boolean>(false);
  const [submitSuccess, setSubmitSuccess] = useState<boolean>(false);

  const handleRatingSelect = (value: number) => {
    setRating(value);
  };

  const handleTagAdd = () => {
    if (newTag.trim() !== "" && !tags.includes(newTag.trim())) {
      setTags([...tags, newTag.trim()]);
      setNewTag("");
    }
  };

  const handleTagRemove = (tagToRemove: string) => {
    setTags(tags.filter(tag => tag !== tagToRemove));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!rating || reviewText.trim() === "") return;

    setIsSubmitting(true);

    // In a real app, this would be an API call
    // For now, we'll just simulate success
    try {
      await new Promise(resolve => setTimeout(resolve, 500));
      setSubmitSuccess(true);
      // Reset form
      setRating(null);
      setReviewText("");
      setTags([]);
    } catch (error) {
      // Handle error if needed
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div style={styles.container}>
      <div style={styles.formContainer}>
        <h1 style={styles.title}>Write a Review</h1>

        {submitSuccess ? (
          <div style={styles.successMessage}>
            <p>Review submitted successfully!</p>
          </div>
        ) : (
          <form onSubmit={handleSubmit} style={styles.form}>
            <div style={styles.fieldGroup}>
              <label style={styles.label}>Rating:</label>
              <div style={styles.ratingContainer}>
                {[1, 2, 3, 4, 5].map((star) => (
                  <button
                    key={star}
                    type="button"
                    onClick={() => handleRatingSelect(star)}
                    style={
                      rating && rating >= star
                        ? styles.selectedStar
                        : styles.star
                    }
                  >
                    ★
                  </button>
                ))}
              </div>
            </div>

            <div style={styles.fieldGroup}>
              <label style={styles.label}>Review Text:</label>
              <textarea
                value={reviewText}
                onChange={(e) => setReviewText(e.target.value)}
                placeholder="Share your thoughts about the book..."
                style={styles.textarea}
                rows={4}
                required
              />
            </div>

            <div style={styles.fieldGroup}>
              <label style={styles.label}>Tags (optional):</label>
              <div style={styles.tagsContainer}>
                {tags.map((tag) => (
                  <span key={tag} style={styles.tag}>
                    {tag}
                    <button
                      type="button"
                      onClick={() => handleTagRemove(tag)}
                      style={styles.removeTagButton}
                    >
                      ×
                    </button>
                  </span>
                ))}
              </div>
              <div style={styles.tagInputContainer}>
                <input
                  type="text"
                  value={newTag}
                  onChange={(e) => setNewTag(e.target.value)}
                  placeholder="Add a tag..."
                  style={styles.tagInput}
                />
                <button
                  type="button"
                  onClick={handleTagAdd}
                  style={styles.addTagButton}
                >
                  Add Tag
                </button>
              </div>
            </div>

            <button
              type="submit"
              disabled={isSubmitting || !rating || reviewText.trim() === ""}
              style={
                isSubmitting || !rating || reviewText.trim() === ""
                  ? styles.submitButtonDisabled
                  : styles.submitButton
              }
            >
              {isSubmitting ? "Submitting..." : "Submit Review"}
            </button>
          </form>
        )}
      </div>
    </div>
  );
}

