  const { name, email, phone, address } = req.body;

  if (!name || !email || !phone || !address) {
    return res.status(400).json({ error: "Name, email, phone, and address are required" });
  }

  const newFarmer = createFarmer({ name, email, phone, address });
  res.status(201).json(newFarmer);
});

// Update a farmer
router.put("/:id", (req: Request, res: Response) => {
  const { name, email, phone, address } = req.body;

  const farmer = findFarmerById(req.params.id);
  if (!farmer) {
    return res.status(404).json({ error: "Farmer not found" });
  }

  const updatedFarmer = updateFarmer(req.params.id, { name, email, phone, address });
  if (!updatedFarmer) {
    return res.status(404).json({ error: "Farmer not found" });
  }

  res.json(updatedFarmer);
});

// Delete a farmer
router.delete("/:id", (req: Request, res: Response) => {
  const deleted = deleteFarmer(req.params.id);
  if (!deleted) {
    return res.status(404).json({ error: "Farmer not found" });
  }
  res.json({ message: "Farmer deleted successfully" });
});

