import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT secret is set
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // For demonstration purposes, we'll simulate token verification
  // In a real implementation, you would decode and verify the JWT signature
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);

  // Simulate token verification using HMAC-SHA256
  const expectedSignature = createHmac("sha256", jwtSecret)
    .update(token.split(".")[0] + "." + token.split(".")[1])
    .digest();

  const actualSignature = Buffer.from(token.split(".")[2], "base64");

  try {
    const isValid = timingSafeEqual(expectedSignature, actualSignature);
    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // If token is valid, proceed to next middleware
    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes and methods
  const protectedPaths = ["/api/milk", "/api/collectors", "/api/managers"];
  const protectedMethods = ["POST", "PUT", "DELETE"];

  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath || !protectedMethods.includes(req.method)) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Verify JWT signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  try {
    // Simple verification - in a real app, use a proper JWT library
    const [header, payload, signature] = token.split(".");

    if (!header || !payload || !signature) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    // Create expected signature
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // Decode payload to get user role
    const payloadDecoded = Buffer.from(payload, "base64url").toString("utf-8");
    const payloadObj = JSON.parse(payloadDecoded);

    const userRole = payloadObj.role;
    if (!userRole) {
      res.status(401).json({ error: "Unauthorized: Role not found in token" });
      return;
    }

    // Define role hierarchy
    const allowedRoles: Record<string, string[]> = {
      "collector": ["collector"],
      "manager": ["collector", "manager"],
      "admin": ["collector", "manager", "admin"]
    };

    // Check if user has required permissions
    const requiredRoles = ["collector", "manager", "admin"];

    if (!allowedRoles[userRole] || !allowedRoles[userRole].some(role => requiredRoles.includes(role))) {
      res.status(403).json({ error: "Forbidden: Insufficient permissions" });
      return;
    }

    // Attach user info to request for downstream middleware/routes
    (req as any).user = {
      role: userRole,
      id: payloadObj.id
    };

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

import { useState } from "react";

export function MilkCollectionForm() {
  const [quantity, setQuantity] = useState<string>("");
  const [date, setDate] = useState<string>("");
  const [quality, setQuality] = useState<string>("good");
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [message, setMessage] = useState<string>("");

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setMessage("");

    try {
      const response = await fetch("/api/milk-collections", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          quantity: Number(quantity),
          date,
          quality
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to submit: ${response.status}`);
      }

      setMessage("Milk collection recorded successfully!");
      setQuantity("");
      setDate("");
    } catch (error) {
      setMessage(`Error: ${(error as Error).message}`);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div style={{
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      maxWidth: 600,
      margin: "0 auto",
      padding: 20
    }}>
      <h1 style={{ textAlign: "center" }}>Milk Collection Form</h1>

      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: 15 }}>
        <div>
          <label htmlFor="quantity" style={{ display: "block", marginBottom: 5, fontWeight: "bold" }}>
            Quantity (liters)
          </label>
          <input
            id="quantity"
            type="number"
            value={quantity}
            onChange={(e) => setQuantity(e.target.value)}
            style={{ width: "100%", padding: 8, borderRadius: 4, border: "1px solid #ccc" }}
            required
            min="0"
            step="0.1"
          />
        </div>

        <div>
          <label htmlFor="date" style={{ display: "block", marginBottom: 5, fontWeight: "bold" }}>
            Date
          </label>
          <input
            id="date"
            type="date"
            value={date}
            onChange={(e) => setDate(e.target.value)}
            style={{ width: "100%", padding: 8, borderRadius: 4, border: "1px solid #ccc" }}
            required
          />
        </div>

        <div>
          <label htmlFor="quality" style={{ display: "block", marginBottom: 5, fontWeight: "bold" }}>
            Quality
          </label>
          <select
            id="quality"
            value={quality}
            onChange={(e) => setQuality(e.target.value)}
            style={{ width: "100%", padding: 8, borderRadius: 4, border: "1px solid #ccc" }}
          >
            <option value="excellent">Excellent</option>
            <option value="good">Good</option>
            <option value="fair">Fair</option>
            <option value="poor">Poor</option>
          </select>
        </div>

        <button
          type="submit"
          disabled={isLoading}
          style={{
            padding: 10,
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            borderRadius: 4,
            cursor: isLoading ? "not-allowed" : "pointer",
            fontWeight: "bold"
          }}
        >
          {isLoading ? "Recording..." : "Record Collection"}
        </button>
      </form>

      {message && (
        <div style={{
          marginTop: 20,
          padding: 15,
          backgroundColor: message.includes("successfully") ? "#d4edda" : "#f8d7da",
          color: message.includes("successfully") ? "#155724" : "#721c24",
          borderRadius: 4,
          border: message.includes("successfully") ? "1px solid #c3e6cb" : "1px solid #f5c6cb"
        }}>
          {message}
        </div>
      )}
    </div>
  );
}

