import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  const protectedPaths = ["/transactions", "/users", "/inventory"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has proper role for the action
  const userRole = req.headers["x-user-role"] as string | undefined;
  const userPermissions = req.headers["x-user-permissions"] as string | undefined;

  if (!userRole) {
    res.status(401).json({ error: "Unauthorized: Missing role header" });
    return;
  }

  // Define role permissions
  const rolePermissions: Record<string, string[]> = {
    student: ["view_own_data"],
    staff: ["process_transactions", "view_own_data"],
    admin: ["manage_all"]
  };

  const requiredPermissions = getRequiredPermissions(req.method);

  // Check if user has required permissions
  const userPerms = userPermissions ? userPermissions.split(",") : [];
  const hasPermission = requiredPermissions.every(permission =>
    userPerms.includes(permission)
  );

  if (!hasPermission) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  next();
}

function getRequiredPermissions(method: string): string[] {
  switch (method) {
    case "GET":
      return ["view_own_data"];
    case "POST":
      return ["process_transactions"];
    case "PUT":
    case "DELETE":
      return ["manage_all"];
    default:
      return [];
  }
}

