export const router = Router();

// Mock database functions - in a real app these would come from a database module
const mockGames = [
  { id: 1, title: "The Legend of Zelda: Ocarina of Time", genre: "Adventure", releaseYear: 1998 },
  { id: 2, title: "Super Mario Bros. 3", genre: "Platformer", releaseYear: 1988 },
];

let nextId = 3;

const findGameById = (id: number) => {
  return mockGames.find(game => game.id === id);
};

const createGame = (game: Omit<Game, "id">) => {
  const newGame = { ...game, id: nextId++ };
  mockGames.push(newGame);
  return newGame;
};

const updateGame = (id: number, updatedGame: Partial<Game>) => {
  const index = mockGames.findIndex(game => game.id === id);
  if (index === -1) return null;

  mockGames[index] = { ...mockGames[index], ...updatedGame };
  return mockGames[index];
};

const deleteGame = (id: number) => {
  const index = mockGames.findIndex(game => game.id === id);
  if (index === -1) return false;

  mockGames.splice(index, 1);
  return true;
};

interface Game {
  id: number;
  title: string;
  genre: string;
  releaseYear: number;
}

// GET /games
router.get("/games", (req: Request, res: Response) => {
  res.json(mockGames);
});

// GET /games/:id
router.get("/games/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid game ID" });
  }

  const game = findGameById(id);

  if (!game) {
    return res.status(404).json({ error: "Game not found" });
  }

  res.json(game);
});

// POST /games
router.post("/games", (req: Request, res: Response) => {
  const { title, genre, releaseYear } = req.body;

  if (!title || !genre || !releaseYear) {
    return res.status(400).json({ error: "Title, genre, and release year are required" });
  }

  const newGame = createGame({
    title,
    genre,
    releaseYear: Number(releaseYear)
  });

  res.status(201).json(newGame);
});

// PUT /games/:id
router.put("/games/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid game ID" });
  }

  const game = findGameById(id);

  if (!game) {
    return res.status(404).json({ error: "Game not found" });
  }

  const { title, genre, releaseYear } = req.body;

  const updatedGame = updateGame(id, {
    title,
    genre,
    releaseYear: releaseYear ? Number(releaseYear) : undefined
  });

  if (!updatedGame) {
    return res.status(404).json({ error: "Game not found" });
  }

  res.json(updatedGame);
});

// DELETE /games/:id
router.delete("/games/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid game ID" });
  }

  const deleted = deleteGame(id);

  if (!deleted) {
    return res.status(404).json({ error: "Game not found" });
  }

  res.json({ message: "Game deleted successfully" });
});

