import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // In a real implementation, we would verify JWT token signature here
  // For now, we'll just check if the request has a valid token header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);

  // Simulate token verification - in reality, this would use HMAC-SHA256
  // with the secret from process.env.JWT_SECRET
  try {
    // This is a simplified mock - in practice, you'd decode and verify the JWT
    const expectedToken = createHmac("sha256", jwtSecret)
      .update("mocked_token_payload")
      .digest("hex");

    // Mock timing-safe comparison (in real code, use timingSafeEqual)
    const isValid = token === expectedToken;

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to POST, PUT, DELETE requests
  if (!['POST', 'PUT', 'DELETE'].includes(req.method)) {
    next();
    return;
  }

  // Define protected routes
  const protectedPaths = [
    '/api/users',
    '/api/games',
    '/api/genres',
    '/api/platforms'
  ];

  // Check if current path is protected
  const isProtectedPath = protectedPaths.some(path => 
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Get authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Unauthorized: Missing or invalid token' });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  try {
    // Simple token validation - in a real app, you'd decode and verify JWT properly
    // For this implementation, we'll just check if it has the right format
    const [userId, role] = token.split('|');

    if (!userId || !role) {
      res.status(401).json({ error: 'Unauthorized: Invalid token format' });
      return;
    }

    // Check if role is allowed (admin or staff only)
    if (role !== 'admin' && role !== 'staff') {
      res.status(403).json({ error: 'Forbidden: Insufficient permissions' });
      return;
    }

    // Attach user info to request for downstream middleware/routes
    (req as any).user = { id: userId, role };
    next();
  } catch (error) {
    res.status(401).json({ error: 'Unauthorized: Invalid token' });
  }
}

