import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data structures to simulate database operations
const interviews = new Map<string, any>();
let nextId = 1;

// Helper function to validate interview data
const validateInterviewData = (data: any): string | null => {
  if (!data.title || typeof data.title !== 'string') {
    return 'Title is required and must be a string';
  }

  if (!data.date || typeof data.date !== 'string') {
    return 'Date is required and must be a string';
  }

  if (!data.startTime || typeof data.startTime !== 'string') {
    return 'Start time is required and must be a string';
  }

  if (!data.endTime || typeof data.endTime !== 'string') {
    return 'End time is required and must be a string';
  }

  // Basic time format validation (HH:MM)
  const timeRegex = /^([0-1]?[0-9]|2[0-3]):[0-5][0-9]$/;
  if (!timeRegex.test(data.startTime)) {
    return 'Start time must be in HH:MM format';
  }

  if (!timeRegex.test(data.endTime)) {
    return 'End time must be in HH:MM format';
  }

  // Ensure end time is after start time
  const [startHours, startMinutes] = data.startTime.split(':').map(Number);
  const [endHours, endMinutes] = data.endTime.split(':').map(Number);

  if (endHours < startHours || (endHours === startHours && endMinutes <= startMinutes)) {
    return 'End time must be after start time';
  }

  return null;
};

// Helper function to check for time conflicts
const hasTimeConflict = (newInterview: any): boolean => {
  const newDate = new Date(newInterview.date);

  for (const [id, existingInterview] of interviews.entries()) {
    if (existingInterview.date === newInterview.date) {
      const existingStart = existingInterview.startTime.split(':').map(Number);
      const existingEnd = existingInterview.endTime.split(':').map(Number);
      const newStart = newInterview.startTime.split(':').map(Number);
      const newEnd = newInterview.endTime.split(':').map(Number);

      // Check if times overlap
      if ((newStart[0] < existingEnd[0] || (newStart[0] === existingEnd[0] && newStart[1] < existingEnd[1])) &&
          (newEnd[0] > existingStart[0] || (newEnd[0] === existingStart[0] && newEnd[1] > existingStart[1]))) {
        return true;
      }
    }
  }

  return false;
};

// GET /interviews - List all interviews
router.get('/', (req: Request, res: Response) => {
  const interviewList = Array.from(interviews.values());
  return res.json(interviewList);
});

// GET /interviews/:id - Get a specific interview by ID
router.get('/:id', (req: Request, res: Response) => {
  const id = req.params.id;
  const interview = interviews.get(id);

  if (!interview) {
    return res.status(404).json({ error: 'Interview not found' });
  }

  return res.json(interview);
});

// POST /interviews - Create a new interview
router.post('/', (req: Request, res: Response) => {
  const { title, date, startTime, endTime } = req.body;

  const validationError = validateInterviewData({ title, date, startTime, endTime });
  if (validationError) {
    return res.status(400).json({ error: validationError });
  }

  // Check for time conflicts
  const newInterview = { id: nextId.toString(), title, date, startTime, endTime };
  if (hasTimeConflict(newInterview)) {
    return res.status(400).json({ error: 'Time conflict detected with existing interview' });
  }

  interviews.set(nextId.toString(), newInterview);
  nextId++;

  return res.status(201).json(newInterview);
});

// PUT /interviews/:id - Update an existing interview
router.put('/:id', (req: Request, res: Response) => {
  const id = req.params.id;
  const { title, date, startTime, endTime } = req.body;

  const existingInterview = interviews.get(id);

  if (!existingInterview) {
    return res.status(404).json({ error: 'Interview not found' });
  }

  const validationError = validateInterviewData({ title, date, startTime, endTime });
  if (validationError) {
    return res.status(400).json({ error: validationError });
  }

  // Check for time conflicts
  const updatedInterview = { ...existingInterview, title, date, startTime, endTime };
  if (hasTimeConflict(updatedInterview)) {
    return res.status(400).json({ error: 'Time conflict detected with existing interview' });
  }

  interviews.set(id, updatedInterview);

  return res.json(updatedInterview);
});

// DELETE /interviews/:id - Delete an interview
router.delete('/:id', (req: Request, res: Response) => {
  const id = req.params.id;

  const interview = interviews.get(id);

  if (!interview) {
    return res.status(404).json({ error: 'Interview not found' });
  }

  interviews.delete(id);

  return res.json({ message: 'Interview deleted successfully' });
});

