router.get("/candidates/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const candidate = candidates.find(c => c.id === id);

  if (!candidate) {
    return res.status(404).json({ error: "Candidate not found" });
  }

  res.json(candidate);
});

// POST /candidates - Create a new candidate
router.post("/candidates", (req: Request, res: Response) => {
  const { name, email, phone, resumeUrl } = req.body;

  const newCandidate = {
    id: (candidates.length + 1).toString(),
    name,
    email,
    phone,
    resumeUrl
  };

  if (!validateCandidate(newCandidate)) {
    return res.status(400).json({ error: "Invalid candidate data" });
  }

  candidates.push(newCandidate);
  res.status(201).json(newCandidate);
});

// PUT /candidates/:id - Update a candidate
router.put("/candidates/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const candidateIndex = candidates.findIndex(c => c.id === id);

  if (candidateIndex === -1) {
    return res.status(404).json({ error: "Candidate not found" });
  }

  const updatedCandidate = { ...candidates[candidateIndex], ...req.body };

  if (!validateCandidate(updatedCandidate)) {
    return res.status(400).json({ error: "Invalid candidate data" });
  }

  candidates[candidateIndex] = updatedCandidate;
  res.json(updatedCandidate);
});

// DELETE /candidates/:id - Delete a candidate
router.delete("/candidates/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const candidateIndex = candidates.findIndex(c => c.id === id);

  if (candidateIndex === -1) {
    return res.status(404).json({ error: "Candidate not found" });
  }

  candidates.splice(candidateIndex, 1);
  res.json({ message: "Candidate deleted successfully" });
});

