export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const protectedPaths = [
    "/interviews",
    "/candidates",
    "/interviewers",
    "/admin"
  ];

  const isProtectedPath = protectedPaths.some(path => 
    req.path.startsWith(path) || 
    req.path === path
  );

  // Skip validation for non-protected paths
  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (!userRole) {
    res.status(401).json({ error: "Authorization header missing" });
    return;
  }

  // Validate role
  const validRoles = ["admin", "interviewer", "candidate"];
  if (!validRoles.includes(userRole)) {
    res.status(403).json({ error: "Invalid role" });
    return;
  }

  // For admin-only routes
  if (req.path.startsWith("/admin") && userRole !== "admin") {
    res.status(403).json({ error: "Admin access required" });
    return;
  }

  // For interviewer-only routes
  if (
    (req.path.startsWith("/interviews") || 
     req.path.startsWith("/interviewers")) && 
    userRole !== "admin" && 
    userRole !== "interviewer"
  ) {
    res.status(403).json({ error: "Interviewer access required" });
    return;
  }

  // For candidate-only routes
  if (
    req.path.startsWith("/candidates") && 
    userRole !== "admin" && 
    userRole !== "candidate"
  ) {
    res.status(403).json({ error: "Candidate access required" });
    return;
  }

  // If we reach here, the user has appropriate permissions
  next();
}

