import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST, PUT, PATCH requests that contain a body
  if (!['POST', 'PUT', 'PATCH'].includes(req.method) || !req.body) {
    return next();
  }

  // Validate and sanitize input data
  if (req.body && typeof req.body === 'object') {
    sanitizeAndValidateBody(req.body);
  }

  next();
}

function sanitizeAndValidateBody(body: Record<string, any>): void {
  for (const [key, value] of Object.entries(body)) {
    // Skip validation for non-string fields
    if (typeof value !== 'string') {
      continue;
    }

    // Check for potential script tags or other malicious content
    if (/<script/i.test(value)) {
      // In a real implementation, we might want to reject or escape these
      // For now, we'll just log and continue
      // This is a simplified example - in practice, you'd want to handle this more robustly
    }

    // Basic sanitization: remove common injection patterns
    const sanitized = value
      .replace(/<script[^>]*>.*?<\/script>/gi, '')
      .replace(/<iframe[^>]*>.*?<\/iframe>/gi, '')
      .replace(/<object[^>]*>.*?<\/object>/gi, '')
      .replace(/<embed[^>]*>.*?<\/embed>/gi, '');

    // Update the body with sanitized value
    (body as any)[key] = sanitized;
  }
}

