import { useEffect, useState } from "react";

interface Candidate {
  id: number;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  interviewHistory: Interview[];
}

interface Interview {
  id: number;
  date: string;
  status: string;
}

export function CandidateManagementPage() {
  const [candidates, setCandidates] = useState<Candidate[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchCandidates();
  }, []);

  const fetchCandidates = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/candidates');
      if (!response.ok) {
        throw new Error('Failed to fetch candidates');
      }
      const data = await response.json();
      setCandidates(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (candidates.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No candidates found.</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Candidate Management</h1>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
        {candidates.map(candidate => (
          <div key={candidate.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px' }}>
            <h2>{candidate.firstName} {candidate.lastName}</h2>
            <p><strong>Email:</strong> {candidate.email}</p>
            <p><strong>Phone:</strong> {candidate.phone}</p>
            <h3>Interview History</h3>
            {candidate.interviewHistory.length > 0 ? (
              <ul style={{ paddingLeft: '20px' }}>
                {candidate.interviewHistory.map(interview => (
                  <li key={interview.id}>
                    {new Date(interview.date).toLocaleDateString()} - {interview.status}
                  </li>
                ))}
              </ul>
            ) : (
              <p>No interviews scheduled.</p>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";

interface Interview {
  id: number;
  date: string;
  interviewer: string;
  candidateStatus: "scheduled" | "completed" | "cancelled";
}

export function InterviewListPage() {
  const [interviews, setInterviews] = useState<Interview[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filterDate, setFilterDate] = useState("");
  const [filterInterviewer, setFilterInterviewer] = useState("");
  const [filterStatus, setFilterStatus] = useState("");

  useEffect(() => {
    const fetchInterviews = async () => {
      try {
        // Simulate API call
        await new Promise(resolve => setTimeout(resolve, 500));

        // Mock data
        const mockData: Interview[] = [
          {
            id: 1,
            date: "2023-06-15",
            interviewer: "John Smith",
            candidateStatus: "scheduled"
          },
          {
            id: 2,
            date: "2023-06-16",
            interviewer: "Jane Doe",
            candidateStatus: "completed"
          },
          {
            id: 3,
            date: "2023-06-17",
            interviewer: "Bob Johnson",
            candidateStatus: "scheduled"
          }
        ];

        setInterviews(mockData);
        setLoading(false);
      } catch (err) {
        setError("Failed to load interviews");
        setLoading(false);
      }
    };

    fetchInterviews();
  }, []);

  const filteredInterviews = interviews.filter(interview => {
    const matchesDate = filterDate ? interview.date === filterDate : true;
    const matchesInterviewer = filterInterviewer ? interview.interviewer === filterInterviewer : true;
    const matchesStatus = filterStatus ? interview.candidateStatus === filterStatus : true;
    return matchesDate && matchesInterviewer && matchesStatus;
  });

  const uniqueInterviewers = [...new Set(interviews.map(i => i.interviewer))];

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Upcoming Interviews</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="date"
          placeholder="Filter by date"
          value={filterDate}
          onChange={(e) => setFilterDate(e.target.value)}
          style={{ width: "100%", padding: "8px" }}
        />

        <select
          value={filterInterviewer}
          onChange={(e) => setFilterInterviewer(e.target.value)}
          style={{ width: "100%", padding: "8px" }}
        >
          <option value="">All Interviewers</option>
          {uniqueInterviewers.map(interviewer => (
            <option key={interviewer} value={interviewer}>{interviewer}</option>
          ))}
        </select>

        <select
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value)}
          style={{ width: "100%", padding: "8px" }}
        >
          <option value="">All Statuses</option>
          <option value="scheduled">Scheduled</option>
          <option value="completed">Completed</option>
          <option value="cancelled">Cancelled</option>
        </select>
      </div>

      {filteredInterviews.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No interviews found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {filteredInterviews.map(interview => (
            <div 
              key={interview.id} 
              style={{ 
                border: "1px solid #ccc", 
                borderRadius: "8px", 
                padding: "15px", 
                backgroundColor: "#f9f9f9"
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <h3 style={{ margin: "0 0 5px 0" }}>Interview #{interview.id}</h3>
                  <p style={{ margin: "0 0 5px 0" }}><strong>Date:</strong> {interview.date}</p>
                  <p style={{ margin: "0 0 5px 0" }}><strong>Interviewer:</strong> {interview.interviewer}</p>
                  <p style={{ margin: "0 0 5px 0" }}><strong>Status:</strong> {interview.candidateStatus}</p>
                </div>
                <div style={{ display: "flex", gap: "5px" }}>
                  <button 
                    style={{ 
                      backgroundColor: "#007bff", 
                      color: "white", 
                      border: "none", 
                      borderRadius: "4px", 
                      padding: "5px 10px", 
                      cursor: "pointer"
                    }}
                  >
                    View Details
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

