    const attractions = await this.getAllAttractions();
    const index = attractions.findIndex(attraction => attraction.id === id);
    if (index === -1) return null;
    attractions[index] = { ...attractions[index], ...updates };
    return attractions[index];
  },

  async deleteAttraction(id: number) {
    const attractions = await this.getAllAttractions();
    const index = attractions.findIndex(attraction => attraction.id === id);
    if (index === -1) return false;
    attractions.splice(index, 1);
    return true;
  }
