import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (!(req.method === "POST" && req.path === "/login")) {
    next();
    return;
  }

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "JWT secret not configured" });
    return;
  }

  // In a real implementation, we would verify the JWT signature here
  // For now, we just check that the secret exists
  // This is a placeholder implementation

  // Simulate JWT verification (in reality, this would decode and verify)
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7);

  // Verify token signature (simplified for example)
  const expectedSignature = createHmac("sha256", secret)
    .update(token.split(".")[0] + "." + token.split(".")[1])
    .digest("hex");

  const actualSignature = token.split(".")[2];

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "hex");
    const actualBuffer = Buffer.from(actualSignature, "hex");

    if (expectedBuffer.length !== actualBuffer.length ||
        !timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHash, scrypt, randomBytes, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to handle password hashing for user registration
  // It should only process POST requests to the /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  const password = req.body.password;

  // Generate salt
  const salt = randomBytes(16).toString("hex");

  // Hash password with scrypt
  scrypt(password, salt, 64, (err, derivedKey) => {
    if (err) {
      next(err);
      return;
    }

    // Store hashed password and salt
    req.body.hashedPassword = derivedKey.toString("hex");
    req.body.salt = salt;

    next();
  });
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST, PUT, PATCH requests that have a body
  if (!['POST', 'PUT', 'PATCH'].includes(req.method) || !req.body) {
    return next();
  }

  // Sanitize and validate input fields
  if (typeof req.body.title === 'string') {
    req.body.title = sanitizeString(req.body.title);
  }

  if (typeof req.body.description === 'string') {
    req.body.description = sanitizeString(req.body.description);
  }

  if (typeof req.body.location === 'string') {
    req.body.location = sanitizeString(req.body.location);
  }

  if (typeof req.body.category === 'string') {
    req.body.category = sanitizeString(req.body.category);
  }

  next();
}

function sanitizeString(str: string): string {
  // Remove potentially dangerous characters
  return str
    .replace(/<script[^>]*>.*?<\/script>/gi, '')
    .replace(/<[^>]*>/g, '')
    .replace(/(\b)(on\w+)=/gi, '$1')
    .trim();
}

