}

export function UserProfilePage() {
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newPreference, setNewPreference] = useState("");

  useEffect(() => {
    fetchProfile();
  }, []);

  const fetchProfile = async () => {
    try {
      setLoading(true);
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 500));

      // Mock data - in a real app this would come from an API
      const mockProfile: UserProfile = {
        preferences: ["museums", "parks", "restaurants"],
        savedAttractions: [
          {
            id: 1,
            name: "City Museum",
            description: "Explore local history and culture",
            category: "museums"
          },
          {
            id: 2,
            name: "Central Park",
            description: "Beautiful green space in the heart of the city",
            category: "parks"
          }
        ],
        viewHistory: [
          {
            id: 3,
            name: "Historic Theater",
            description: "Iconic performing arts venue",
            category: "entertainment"
          }
        ]
      };

      setProfile(mockProfile);
    } catch (err) {
      setError("Failed to load profile");
    } finally {
      setLoading(false);
    }
  };

  const handleAddPreference = () => {
    if (!newPreference.trim() || !profile) return;

    const updatedProfile = {
      ...profile,
      preferences: [...profile.preferences, newPreference.trim()]
    };

    setProfile(updatedProfile);
    setNewPreference("");
  };

  const handleRemovePreference = (preference: string) => {
    if (!profile) return;

    const updatedProfile = {
      ...profile,
      preferences: profile.preferences.filter(p => p !== preference)
    };

    setProfile(updatedProfile);
  };

  const handleRemoveSavedAttraction = (id: number) => {
    if (!profile) return;

    const updatedProfile = {
      ...profile,
      savedAttractions: profile.savedAttractions.filter(attraction => attraction.id !== id)
    };

    setProfile(updatedProfile);
  };

  const handleRemoveViewedAttraction = (id: number) => {
    if (!profile) return;

    const updatedProfile = {
      ...profile,
      viewHistory: profile.viewHistory.filter(attraction => attraction.id !== id)
    };

    setProfile(updatedProfile);
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (!profile) {
    return <div style={{ textAlign: "center", padding: "20px" }}>No profile data available</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>My Profile</h1>

      <div style={{ marginBottom: "30px" }}>
        <h2>Preferences</h2>
        <div style={{ display: "flex", gap: "10px", marginBottom: "10px" }}>
          <input
            type="text"
            value={newPreference}
            onChange={(e) => setNewPreference(e.target.value)}
            placeholder="Add new preference"
            style={{ flex: 1, padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
          <button 
            onClick={handleAddPreference}
            style={{ padding: "8px 16px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
          >
            Add
          </button>
        </div>

        <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
          {profile.preferences.map((pref, index) => (
            <span 
              key={index}
              style={{ 
                backgroundColor: "#e9ecef", 
                padding: "4px 8px", 
                borderRadius: "4px", 
                display: "flex", 
                alignItems: "center", 
                gap: "5px"
              }}
            >
              {pref}
              <button 
                onClick={() => handleRemovePreference(pref)}
                style={{ 
                  background: "none", 
                  border: "none", 
                  color: "#dc3545", 
                  cursor: "pointer", 
                  fontSize: "14px"
                }}
              >
                ×
              </button>
            </span>
          ))}
        </div>
      </div>

      <div style={{ marginBottom: "30px" }}>
        <h2>Saved Attractions</h2>
        {profile.savedAttractions.length === 0 ? (
          <p>No saved attractions yet</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {profile.savedAttractions.map(attraction => (
              <div 
                key={attraction.id} 
                style={{ 
                  border: "1px solid #dee2e6", 
                  borderRadius: "4px", 
                  padding: "10px", 
                  display: "flex", 
                  justifyContent: "space-between", 
                  alignItems: "center"
                }}
              >
                <div>
                  <h3>{attraction.name}</h3>
                  <p>{attraction.description}</p>
                  <small>{attraction.category}</small>
                </div>
                <button 
                  onClick={() => handleRemoveSavedAttraction(attraction.id)}
                  style={{ 
                    padding: "4px 8px", 
                    backgroundColor: "#dc3545", 
                    color: "white", 
                    border: "none", 
                    borderRadius: "4px", 
                    cursor: "pointer"
                  }}
                >
                  Remove
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      <div>
        <h2>View History</h2>
        {profile.viewHistory.length === 0 ? (
          <p>No viewed attractions yet</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {profile.viewHistory.map(attraction => (
              <div 
                key={attraction.id} 
                style={{ 
                  border: "1px solid #dee2e6", 
                  borderRadius: "4px", 
                  padding: "10px", 
                  display: "flex", 
                  justifyContent: "space-between", 
                  alignItems: "center"
                }}
              >
                <div>
                  <h3>{attraction.name}</h3>
                  <p>{attraction.description}</p>
                  <small>{attraction.category}</small>
                </div>
                <button 
                  onClick={() => handleRemoveViewedAttraction(attraction.id)}
                  style={{ 
                    padding: "4px 8px", 
                    backgroundColor: "#dc3545", 
                    color: "white", 
                    border: "none", 
                    borderRadius: "4px", 
                    cursor: "pointer"
                  }}
                >
                  Remove
                </button>
              </div>
            ))}
          </div>
        )}
