import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  { id: "1", email: "admin@example.com", password: "hashed-admin-password", role: "admin" },
  { id: "2", email: "user@example.com", password: "hashed-user-password", role: "user" }
];

// Middleware to check if user is authenticated
const authenticate = (req: Request, res: Response, next: Function) => {
  // In a real app, this would verify a JWT token
  const token = req.header("Authorization")?.replace("Bearer ", "");
  if (!token) {
    return res.status(401).json({ error: "Access denied. No token provided." });
  }

  // Mock authentication - in reality, decode and verify JWT
  const user = users.find(u => u.id === "1"); // Mock: assuming admin user is authenticated
  if (!user) {
    return res.status(401).json({ error: "Invalid token." });
  }

  // Attach user to request object
  (req as any).user = user;
  next();
};

// Middleware to check roles
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    const user = (req as any).user;
    if (!user || !roles.includes(user.role)) {
      return res.status(403).json({ error: "Access denied. Insufficient permissions." });
    }
    next();
  };
};

// Register a new user
router.post("/register", (req: Request, res: Response) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required." });
  }

  // Check if user already exists
  const existingUser = users.find(u => u.email === email);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists." });
  }

  // Create new user (mock)
  const newUser = {
    id: `${users.length + 1}`,
    email,
    password: `hashed-${password}`, // In real app, hash the password
    role: "user"
  };

  users.push(newUser);

  res.status(201).json({ id: newUser.id, email: newUser.email, role: newUser.role });
});

// Login user
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required." });
  }

  // Find user
  const user = users.find(u => u.email === email && u.password === `hashed-${password}`);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials." });
  }

  // In a real app, generate JWT token here
  res.json({ 
    token: "mock-jwt-token",
    user: { id: user.id, email: user.email, role: user.role }
  });
});

