import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function isValidToken(token: string): boolean {
  if (!JWT_SECRET) return false;

  const parts = token.split(".");
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;

  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const expectedBytes = Buffer.from(expectedSignature, "base64url");
    const actualBytes = Buffer.from(signature, "base64url");
    return timingSafeEqual(expectedBytes, actualBytes);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check authentication for POST requests to /login
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if Authorization header exists
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  if (!isValidToken(token)) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // Token is valid, proceed to next middleware/route handler
  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const protectedPaths = ["/admin", "/student"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has proper role
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (!userRole) {
    res.status(401).json({ error: "Unauthorized: Missing role header" });
    return;
  }

  // Validate role
  if (userRole !== "student" && userRole !== "admin") {
    res.status(403).json({ error: "Forbidden: Invalid role" });
    return;
  }

  // For admin-only routes
  if (req.path.startsWith("/admin")) {
    if (userRole !== "admin") {
      res.status(403).json({ error: "Forbidden: Admin access required" });
      return;
    }
  }

  // For student-only routes
  if (req.path.startsWith("/student")) {
    if (userRole !== "student") {
      res.status(403).json({ error: "Forbidden: Student access required" });
      return;
    }
  }

  // If we reach here, the user has proper access
  next();
}

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for GET requests that don't have a body
  if (req.method === "GET" && !req.body) {
    return next();
  }

  // Only validate POST, PUT, PATCH requests
  if (!['POST', 'PUT', 'PATCH'].includes(req.method)) {
    return next();
  }

  // Validate request body for potential injection attacks
  if (req.body) {
    validateRequestBody(req.body);
  }

  // Validate query parameters
  if (req.query) {
    validateQueryParams(req.query);
  }

  next();
}

function validateRequestBody(body: any): void {
  if (typeof body === 'object' && body !== null) {
    Object.keys(body).forEach(key => {
      const value = body[key];

      // Check for potentially dangerous characters
      if (typeof value === 'string') {
        // Basic injection protection - reject common patterns
        if (value.includes('\\') || value.includes('\\\"') || value.includes("'") || value.includes(';')) {
          throw new Error('Invalid input detected');
        }
      }

      // Recursively validate nested objects
      if (typeof value === 'object' && value !== null) {
        validateRequestBody(value);
      }
    });
  }
}

function validateQueryParams(query: any): void {
  Object.keys(query).forEach(key => {
    const value = query[key];

    // Check for potentially dangerous characters in query params
    if (typeof value === 'string') {
      if (value.includes('\\') || value.includes('\\\"') || value.includes("'") || value.includes(';')) {
        throw new Error('Invalid query parameter detected');
      }
    }
  });
}

import type { Request, Response, NextFunction } from "express";

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB
const ALLOWED_MIME_TYPES = [
  "image/jpeg",
  "image/jpg",
  "image/png",
];

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check file uploads on POST requests to the upload endpoint
  if (req.method !== "POST" || req.path !== "/upload") {
    next();
    return;
  }

  // Check if file exists in request
  if (!req.file) {
    res.status(400).json({ error: "No file uploaded" });
    return;
  }

  // Check file size
  if (req.file.size > MAX_FILE_SIZE) {
    res.status(400).json({ error: "File too large" });
    return;
  }

  // Check MIME type
  if (!ALLOWED_MIME_TYPES.includes(req.file.mimetype)) {
    res.status(400).json({ error: "Invalid file type" });
    return;
  }

  next();
}

