import { useEffect, useState } from "react";

interface Request {
  id: number;
  studentName: string;
  studentId: string;
  status: "pending" | "approved" | "rejected";
  submissionDate: string;
}

export function RequestsList() {
  const [requests, setRequests] = useState<Request[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchRequests = async () => {
      try {
        const response = await fetch(`/api/requests`);
        if (!response.ok) {
          throw new Error(`Failed to fetch requests: ${response.status}`);
        }
        const data = await response.json();
        setRequests(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchRequests();
  }, []);

  const filteredRequests = requests.filter(request =>
    request.studentName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    request.studentId.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>ID Card Requests</h1>

      <div style={{ marginBottom: "20px" }}>
        <input
          type="text"
          placeholder="Search by student name or ID..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{
            width: "100%",
            padding: "10px",
            borderRadius: "4px",
            border: "1px solid #ccc",
            fontSize: "16px"
          }}
        />
      </div>

      {filteredRequests.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No requests found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {filteredRequests.map((request) => (
            <div 
              key={request.id} 
              style={{
                border: "1px solid #ddd",
                borderRadius: "8px",
                padding: "15px",
                backgroundColor: "#f9f9f9"
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <h3 style={{ margin: "0 0 5px 0" }}>{request.studentName}</h3>
                  <p style={{ margin: "0 0 5px 0", color: "#666" }}>
                    Student ID: {request.studentId}
                  </p>
                  <p style={{ margin: "0 0 5px 0", color: "#666" }}>
                    Submitted: {new Date(request.submissionDate).toLocaleDateString()}
                  </p>
                </div>
                <span 
                  style={{
                    padding: "5px 10px",
                    borderRadius: "4px",
                    fontWeight: "bold",
                    color: request.status === "approved" ? "green" : request.status === "rejected" ? "red" : "orange"
                  }}
                >
                  {request.status.charAt(0).toUpperCase() + request.status.slice(1)}
                </span>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import type { Request, Response, NextFunction } from "express";

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB
const ALLOWED_MIME_TYPES = [
  "image/jpeg",
  "image/jpg",
  "image/png",
];

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check file uploads on POST requests to the upload endpoint
  if (req.method !== "POST" || req.path !== "/upload") {
    next();
    return;
  }

  // Check if file exists in request
  if (!req.file) {
    res.status(400).json({ error: "No file uploaded" });
    return;
  }

  // Check file size
  if (req.file.size > MAX_FILE_SIZE) {
    res.status(400).json({ error: "File too large" });
    return;
  }

  // Check MIME type
  if (!ALLOWED_MIME_TYPES.includes(req.file.mimetype)) {
    res.status(400).json({ error: "Invalid file type" });
    return;
  }

  next();
}

