let campRegistrations = [
  { id: 1, name: "John Doe", email: "john@example.com", bloodType: "A+", donationDate: "2023-10-15" },
  { id: 2, name: "Jane Smith", email: "jane@example.com", bloodType: "O-", donationDate: "2023-10-16" }
];

let nextId = 3;

// GET /api/camp-registrations - List all camp registrations
router.get("/camp-registrations", (req: Request, res: Response) => {
  res.json(campRegistrations);
});

// GET /api/camp-registrations/:id - Get a specific camp registration by ID
router.get("/camp-registrations/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const registration = campRegistrations.find(r => r.id === id);

  if (!registration) {
    return res.status(404).json({ error: "Camp registration not found" });
  }

  res.json(registration);
});

// POST /api/camp-registrations - Create a new camp registration
router.post("/camp-registrations", (req: Request, res: Response) => {
  const { name, email, bloodType, donationDate } = req.body;

  // Basic validation
  if (!name || !email || !bloodType || !donationDate) {
    return res.status(400).json({ error: "Name, email, blood type, and donation date are required" });
  }

  const newRegistration = {
    id: nextId++,
    name,
    email,
    bloodType,
    donationDate
  };

  campRegistrations.push(newRegistration);

  res.status(201).json(newRegistration);
});

// PUT /api/camp-registrations/:id - Update a camp registration
router.put("/camp-registrations/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const index = campRegistrations.findIndex(r => r.id === id);

  if (index === -1) {
    return res.status(404).json({ error: "Camp registration not found" });
  }

  const { name, email, bloodType, donationDate } = req.body;

  // Basic validation
  if (!name || !email || !bloodType || !donationDate) {
    return res.status(400).json({ error: "Name, email, blood type, and donation date are required" });
  }

  campRegistrations[index] = {
    id,
    name,
    email,
    bloodType,
    donationDate
  };

  res.json(campRegistrations[index]);
});

// DELETE /api/camp-registrations/:id - Delete a camp registration
router.delete("/camp-registrations/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const index = campRegistrations.findIndex(r => r.id === id);

  if (index === -1) {
    return res.status(404).json({ error: "Camp registration not found" });
  }

  campRegistrations.splice(index, 1);

  res.json({ message: "Camp registration deleted successfully" });
});

