import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  if (!req.path.startsWith('/admin') && !req.path.startsWith('/donor-data')) {
    next();
    return;
  }

  // Check if JWT secret is set
  if (!JWT_SECRET) {
    res.status(500).json({ error: 'Server configuration error' });
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Missing or invalid authorization header' });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  try {
    // Basic token structure validation
    const parts = token.split('.');
    if (parts.length !== 3) {
      res.status(401).json({ error: 'Invalid token format' });
      return;
    }

    // Decode the payload (base64url)
    const payload = Buffer.from(parts[1], 'base64').toString('utf-8');
    const decodedPayload = JSON.parse(payload);

    // Verify signature
    const signature = parts[2];
    const expectedSignature = createHmac('sha256', JWT_SECRET)
      .update(`${parts[0]}.${parts[1]}`)
      .digest('base64url');

    const expectedBuffer = Buffer.from(expectedSignature, 'base64url');
    const actualBuffer = Buffer.from(signature, 'base64url');

    if (!timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: 'Invalid token signature' });
      return;
    }

    // Check if user has required role
    const requiredRole = req.path.startsWith('/admin') ? 'admin' : 'staff';

    if (decodedPayload.role !== requiredRole) {
      res.status(403).json({ error: 'Insufficient permissions' });
      return;
    }

    // Attach user info to request for downstream middleware/routes
    (req as any).user = decodedPayload;
    next();
  } catch (error) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

