import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes
const ACTIVE_SESSIONS = new Map<string, { expires: number }>();

function getCookieValue(cookieHeader: string | undefined, cookieName: string): string | null {
  if (!cookieHeader) return null;
  const cookies = cookieHeader.split(";").map(c => c.trim());
  for (const cookie of cookies) {
    const [name, value] = cookie.split("=");
    if (name === cookieName) {
      return value || null;
    }
  }
  return null;
}

function generateSessionId(): string {
  return Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);
}

function verifyToken(token: string): boolean {
  const secret = process.env.JWT_SECRET;
  if (!secret) return false;

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) return false;

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /logout
  if (req.method !== "POST" || req.path !== "/logout") {
    next();
    return;
  }

  const sessionId = getCookieValue(req.headers.cookie, "session_id");

  if (!sessionId) {
    res.status(401).json({ error: "No active session found" });
    return;
  }

  const session = ACTIVE_SESSIONS.get(sessionId);

  if (!session) {
    res.status(401).json({ error: "Invalid session ID" });
    return;
  }

  // Check if session has expired
  if (Date.now() > session.expires) {
    ACTIVE_SESSIONS.delete(sessionId);
    res.status(401).json({ error: "Session expired" });
    return;
  }

  // Verify token if present
  const token = getCookieValue(req.headers.cookie, "auth_token");
  if (token && !verifyToken(token)) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // Remove session on successful logout
  ACTIVE_SESSIONS.delete(sessionId);

  // Clear session cookie
  res.clearCookie("session_id");
  res.clearCookie("auth_token");

  res.json({ message: "Logged out successfully" });
}

