export function DonorList() {
  const [donors, setDonors] = useState<Donor[]>([]);
  const [filteredDonors, setFilteredDonors] = useState<Donor[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [bloodTypeFilter, setBloodTypeFilter] = useState("all");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchDonors = async () => {
      try {
        const response = await fetch("/api/donors");
        if (!response.ok) {
          throw new Error("Failed to fetch donors");
        }
        const data = await response.json();
        setDonors(data);
        setFilteredDonors(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchDonors();
  }, []);

  useEffect(() => {
    let result = donors;

    if (searchTerm) {
      const term = searchTerm.toLowerCase();
      result = result.filter(
        donor =>
          donor.name.toLowerCase().includes(term) ||
          donor.email.toLowerCase().includes(term)
      );
    }

    if (bloodTypeFilter !== "all") {
      result = result.filter(donor => donor.bloodType === bloodTypeFilter);
    }

    setFilteredDonors(result);
  }, [searchTerm, bloodTypeFilter, donors]);

  const bloodTypes = ["all", "A+", "A-", "B+", "B-", "AB+", "AB-", "O+", "O-"];

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px" }}>
      <h1 style={{ textAlign: "center", fontFamily: "sans-serif" }}>Donor List</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search donors by name or email..."
          value={searchTerm}
          onChange={e => setSearchTerm(e.target.value)}
          style={{
            width: "100%",
            padding: "10px",
            borderRadius: "4px",
            border: "1px solid #ccc",
            fontFamily: "sans-serif"
          }}
        />

        <select
          value={bloodTypeFilter}
          onChange={e => setBloodTypeFilter(e.target.value)}
          style={{
            width: "100%",
            padding: "10px",
            borderRadius: "4px",
            border: "1px solid #ccc",
            fontFamily: "sans-serif"
          }}
        >
          {bloodTypes.map(type => (
            <option key={type} value={type}>
              {type === "all" ? "All Blood Types" : type}
            </option>
          ))}
        </select>
      </div>

      {filteredDonors.length === 0 ? (
        <p style={{ textAlign: "center", fontFamily: "sans-serif" }}>
          No donors found.
        </p>
      ) : (
        <div
          style={{
