router.get('/:id', async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: 'Invalid ID format' });
    }

    const feedback = await mockFeedbackDatabase.getById(id);

    if (!feedback) {
      return res.status(404).json({ error: 'Feedback not found' });
    }

    return res.json(feedback);
  } catch (error) {
    return res.status(500).json({ error: 'Failed to fetch feedback' });
  }
});

// POST /api/feedback - Create new feedback
router.post('/', async (req: Request, res: Response) => {
  try {
    const { guestName, email, rating, comment } = req.body;

    const errors = validateFeedback({ guestName, email, rating, comment });

    if (errors.length > 0) {
      return res.status(400).json({ errors });
    }

    const newFeedback = await mockFeedbackDatabase.create({ guestName, email, rating, comment });

    return res.status(201).json(newFeedback);
  } catch (error) {
    return res.status(500).json({ error: 'Failed to create feedback' });
  }
});

// PUT /api/feedback/:id - Update feedback
router.put('/:id', async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: 'Invalid ID format' });
    }

    const { guestName, email, rating, comment } = req.body;

    const errors = validateFeedback({ guestName, email, rating, comment });

    if (errors.length > 0) {
      return res.status(400).json({ errors });
    }

    const updatedFeedback = await mockFeedbackDatabase.update(id, { guestName, email, rating, comment });

    if (!updatedFeedback) {
      return res.status(404).json({ error: 'Feedback not found' });
    }

    return res.json(updatedFeedback);
  } catch (error) {
    return res.status(500).json({ error: 'Failed to update feedback' });
  }
});

// DELETE /api/feedback/:id - Delete feedback
router.delete('/:id', async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: 'Invalid ID format' });
    }

    const deleted = await mockFeedbackDatabase.delete(id);

    if (!deleted) {
      return res.status(404).json({ error: 'Feedback not found' });
    }

    return res.json({ message: 'Feedback deleted successfully' });
  } catch (error) {
    return res.status(500).json({ error: 'Failed to delete feedback' });
