export const router = Router();

// Mock data structures to simulate database operations
const feedbackEntries: any[] = [];
const categories = ["complaint", "suggestion", "praise"];

// Helper function to categorize feedback
const categorizeFeedback = (text: string): string => {
  const lowerText = text.toLowerCase();
  if (lowerText.includes("bad") || lowerText.includes("terrible") || lowerText.includes("worst")) {
    return "complaint";
  }
  if (lowerText.includes("good") || lowerText.includes("excellent") || lowerText.includes("love")) {
    return "praise";
  }
  if (lowerText.includes("idea") || lowerText.includes("improve") || lowerText.includes("better")) {
    return "suggestion";
  }
  return "general";
};

// Helper function to generate summary report
const generateSummaryReport = (): any => {
  const report: any = {};
  categories.forEach(category => {
    report[category] = feedbackEntries.filter(entry => entry.category === category).length;
  });
  return report;
};

// POST /feedback - Process feedback submission
router.post("/feedback", (req: Request, res: Response) => {
  const { text, guestId } = req.body;

  if (!text || !guestId) {
    return res.status(400).json({ error: "Text and guestId are required" });
  }

  const category = categorizeFeedback(text);
  const newEntry = {
    id: feedbackEntries.length + 1,
    text,
    guestId,
    category,
    timestamp: new Date().toISOString()
  };

  feedbackEntries.push(newEntry);

  return res.status(201).json(newEntry);
});

// GET /feedback/report - Generate summary report
router.get("/feedback/report", (req: Request, res: Response) => {
  const report = generateSummaryReport();
  return res.json(report);
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-feedback routes
  if (!req.path.startsWith("/feedback")) {
    next();
    return;
  }

  // Check if user is authenticated
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token verification (in a real app, use a proper JWT library)
  const [payload, signature] = token.split(".");
  if (!payload || !signature) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  // Verify signature
  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64url");

  try {
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // Decode payload (simplified for this example)
  const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
  const userRole = decodedPayload.role;

  // Staff can access all feedback endpoints
  if (userRole === "staff") {
    next();
    return;
  }

  // Guest users can only submit feedback, not view or edit
  if (userRole === "guest" && req.method === "POST") {
    next();
    return;
  }

  // Reject unauthorized access
  res.status(403).json({ error: "Forbidden" });
}

