// Registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role } = req.body;

  if (!username || !password || !role) {
    return res.status(400).json({ error: "Username, password, and role are required" });
  }

  if (role !== "customer" && role !== "staff") {
    return res.status(400).json({ error: "Role must be either 'customer' or 'staff'" });
  }

  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "Username already exists" });
  }

  const newUser = {
    id: `${users.length + 1}`,
    username,
    password: hashPassword(password),
    role
  };

  users.push(newUser);
  return res.status(201).json({ id: newUser.id, username: newUser.username, role: newUser.role });
});

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === hashPassword(password));

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  return res.json({
    id: user.id,
    username: user.username,
    role: user.role
  });
});

// Role-based access control middleware
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    const token = req.headers.authorization?.split(" ")[1];
    if (!token) {
      return res.status(401).json({ error: "Access denied" });
    }

    // In a real app, we would decode the JWT and verify the role
    // For now, we'll just simulate checking the role
    const user = users.find(u => u.id === token);
    if (!user || user.role !== requiredRole) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }

    next();
  };
};

