import { useState } from "react";

export function OrderForm() {
  const [items, setItems] = useState([
    { id: 1, name: "Burger", price: 8.99 },
    { id: 2, name: "Fries", price: 3.99 },
    { id: 3, name: "Soda", price: 1.99 },
    { id: 4, name: "Salad", price: 6.99 },
  ]);

  const [order, setOrder] = useState<Record<number, number>>({});
  const [instructions, setInstructions] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);

  const handleQuantityChange = (itemId: number, quantity: number) => {
    if (quantity <= 0) {
      const newOrder = { ...order };
      delete newOrder[itemId];
      setOrder(newOrder);
    } else {
      setOrder({ ...order, [itemId]: quantity });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    // In a real app, this would be an API call
    // For demo purposes, we'll just simulate success
    await new Promise(resolve => setTimeout(resolve, 500));

    setIsSubmitting(false);
    setSubmitSuccess(true);

    // Reset form after successful submission
    setTimeout(() => {
      setOrder({});
      setInstructions("");
      setSubmitSuccess(false);
    }, 3000);
  };

  const total = Object.entries(order).reduce((sum, [id, qty]) => {
    const item = items.find(i => i.id === parseInt(id));
    return sum + (item ? item.price * qty : 0);
  }, 0);

  return (
    <div style={{
      maxWidth: 600,
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
    }}>
      <h1 style={{ textAlign: "center" }}>Place Your Order</h1>

      {submitSuccess ? (
        <div style={{
          backgroundColor: "#d4edda",
          color: "#155724",
          padding: "15px",
          borderRadius: "5px",
          textAlign: "center",
          marginBottom: "20px",
        }}>
          Order submitted successfully!
        </div>
      ) : null}

      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "20px" }}>
        <div>
          <h2>Menu Items</h2>
          {items.map(item => (
            <div 
              key={item.id}
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                padding: "10px 0",
                borderBottom: "1px solid #eee",
              }}
            >
              <div>
                <strong>{item.name}</strong>
                <span style={{ marginLeft: "10px", color: "#666" }}>
                  ${item.price.toFixed(2)}
                </span>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                <button
                  type="button"
                  onClick={() => handleQuantityChange(item.id, (order[item.id] || 0) - 1)}
                  disabled={(order[item.id] || 0) <= 0}
                  style={{
                    padding: "5px 10px",
                    border: "1px solid #ccc",
                    borderRadius: "3px",
                    cursor: (order[item.id] || 0) <= 0 ? "default" : "pointer",
                    backgroundColor: (order[item.id] || 0) <= 0 ? "#f0f0f0" : "#fff",
                  }}
                >
                  -
                </button>
                <span style={{ minWidth: "30px", textAlign: "center" }}>
                  {(order[item.id] || 0)}
                </span>
                <button
                  type="button"
                  onClick={() => handleQuantityChange(item.id, (order[item.id] || 0) + 1)}
                  style={{
                    padding: "5px 10px",
                    border: "1px solid #ccc",
                    borderRadius: "3px",
                    cursor: "pointer",
                    backgroundColor: "#fff",
                  }}
                >
                  +
                </button>
              </div>
            </div>
          ))}
        </div>

        <div>
          <h2>Special Instructions</h2>
          <textarea
            value={instructions}
            onChange={(e) => setInstructions(e.target.value)}
            placeholder="Any special requests or allergies?"
            style={{
              width: "100%",
              padding: "10px",
              borderRadius: "5px",
              border: "1px solid #ccc",
              minHeight: "100px",
              fontFamily: "inherit",
            }}
          />
        </div>

        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <h2>Total: ${total.toFixed(2)}</h2>
          </div>
          <button
            type="submit"
            disabled={isSubmitting || Object.keys(order).length === 0}
            style={{
              padding: "12px 24px",
              backgroundColor: "#007bff",
              color: "white",
              border: "none",
              borderRadius: "5px",
              cursor: isSubmitting || Object.keys(order).length === 0 ? "default" : "pointer",
              opacity: isSubmitting || Object.keys(order).length === 0 ? 0.6 : 1,
            }}
          >
            {isSubmitting ? "Submitting..." : "Submit Order"}
          </button>
        </div>
      </form>
    </div>
  );
}

