import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (!(req.method === "POST" && req.path === "/login")) {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;

  if (!jwtSecret) {
    res.status(500).json({ error: "JWT secret not configured" });
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const [header, payload, signature] = parts;

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // If we get here, the token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Authentication failed" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHash, scryptSync, randomBytes, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to handle password hashing for user registration
  // It should only process POST requests to the /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  // Hash the password using scrypt
  const salt = randomBytes(16).toString("hex");
  const key = scryptSync(req.body.password, salt, 32);
  const hashedPassword = key.toString("hex");

  // Replace the plain text password with the hashed one
  req.body.password = hashedPassword;
  req.body.salt = salt;

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST, PUT, PATCH requests that contain a body
  if (!['POST', 'PUT', 'PATCH'].includes(req.method) || !req.body) {
    return next();
  }

  // Validate and sanitize input fields
  if (req.body.email) {
    req.body.email = sanitizeEmail(req.body.email);
  }

  if (req.body.name) {
    req.body.name = sanitizeString(req.body.name);
  }

  if (req.body.title) {
    req.body.title = sanitizeString(req.body.title);
  }

  if (req.body.description) {
    req.body.description = sanitizeString(req.body.description);
  }

  if (req.body.isbn) {
    req.body.isbn = sanitizeString(req.body.isbn);
  }

  if (req.body.price !== undefined) {
    req.body.price = sanitizePrice(req.body.price);
  }

  if (req.body.quantity !== undefined) {
    req.body.quantity = sanitizeQuantity(req.body.quantity);
  }

  next();
}

function sanitizeEmail(email: string): string {
  // Remove leading/trailing whitespace
  email = email.trim();

  // Basic email validation regex
  const emailRegex = /^[\w\.-]+@[\w\.-]+\.[a-zA-Z]{2,}$/;
  if (!emailRegex.test(email)) {
    throw new Error('Invalid email format');
  }

  return email.toLowerCase();
}

function sanitizeString(str: string): string {
  // Remove leading/trailing whitespace
  str = str.trim();

  // Remove potentially dangerous characters
  str = str.replace(/[<>'"&]/g, '');

  return str;
}

function sanitizePrice(price: unknown): number {
  if (typeof price === 'string') {
    const num = parseFloat(price);
    if (isNaN(num) || num < 0) {
      throw new Error('Invalid price');
    }
    return num;
  }

  if (typeof price === 'number') {
    if (price < 0) {
      throw new Error('Invalid price');
    }
    return price;
  }

  throw new Error('Invalid price');
}

function sanitizeQuantity(quantity: unknown): number {
  if (typeof quantity === 'string') {
    const num = parseInt(quantity, 10);
    if (isNaN(num) || num < 0) {
      throw new Error('Invalid quantity');
    }
    return num;
  }

  if (typeof quantity === 'number') {
    if (quantity < 0) {
      throw new Error('Invalid quantity');
    }
    return quantity;
  }

  throw new Error('Invalid quantity');
}

