import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user data - in a real app this would come from a database
const mockUsers = [
  { id: "1", username: "admin", password: "admin123", role: "admin" },
  { id: "2", username: "staff", password: "staff123", role: "staff" }
];

// Middleware to check if user is authenticated
const authenticate = (req: Request, res: Response, next: Function) => {
  // In a real app, this would verify JWT or session token
  // For now, we'll simulate authentication with a header
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  // Mock token validation - in reality this would decode and validate a JWT
  const user = mockUsers.find(u => u.id === token);

  if (!user) {
    return res.status(401).json({ error: "Invalid token" });
  }

  // Attach user to request object
  (req as any).user = user;
  next();
};

// Role-based authorization middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    // Check if user is authenticated
    if (!(req as any).user) {
      return res.status(401).json({ error: "Unauthorized" });
    }

    const userRole = (req as any).user.role;

    if (!roles.includes(userRole)) {
      return res.status(403).json({ error: "Forbidden" });
    }

    next();
  };
};

// POST /login - Authenticate user and return token
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password required" });
  }

  const user = mockUsers.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // In a real app, generate a JWT token here
  // For demo purposes, we'll just return the user ID as a token
  res.json({ token: user.id });
});

// GET /profile - Get authenticated user profile
router.get("/profile", authenticate, (req: Request, res: Response) => {
  if (!(req as any).user) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const user = (req as any).user;

  res.json({
    id: user.id,
    username: user.username,
    role: user.role
  });
});

// GET /admin-only - Admin-only endpoint
router.get("/admin-only", authenticate, authorize(["admin"]), (req: Request, res: Response) => {
  if (!(req as any).user) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const user = (req as any).user;

  res.json({
    message: "Admin access granted",
    user: {
      id: user.id,
      username: user.username,
      role: user.role
    }
  });
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockTeams = [
  { id: "1", name: "Team A", coach: "John Doe", founded: 2000 },
  { id: "2", name: "Team B", coach: "Jane Smith", founded: 2005 }
];

const mockRosters = [
  { teamId: "1", playerId: "1", playerName: "Player One" },
  { teamId: "1", playerId: "2", playerName: "Player Two" },
  { teamId: "2", playerId: "3", playerName: "Player Three" }
];

// Helper to find team by ID
const findTeamById = (id: string) => {
  return mockTeams.find(team => team.id === id);
};

// Helper to find roster entries by team ID
const findRosterByTeamId = (teamId: string) => {
  return mockRosters.filter(entry => entry.teamId === teamId);
};

// List all teams
router.get("/", (req: Request, res: Response) => {
  res.json(mockTeams);
});

// Get a specific team by ID
router.get("/:id", (req: Request, res: Response) => {
  const team = findTeamById(req.params.id);
  if (!team) {
    return res.status(404).json({ error: "Team not found" });
  }
  res.json(team);
});

// Create a new team
router.post("/", (req: Request, res: Response) => {
  const { name, coach, founded } = req.body;

  if (!name || !coach || !founded) {
    return res.status(400).json({ error: "Name, coach, and founded are required" });
  }

  const newTeam = {
    id: String(mockTeams.length + 1),
    name,
    coach,
    founded: Number(founded)
  };

  mockTeams.push(newTeam);
  res.status(201).json(newTeam);
});

// Update a team
router.put("/:id", (req: Request, res: Response) => {
  const teamIndex = mockTeams.findIndex(team => team.id === req.params.id);

  if (teamIndex === -1) {
    return res.status(404).json({ error: "Team not found" });
  }

  const { name, coach, founded } = req.body;

  if (!name || !coach || !founded) {
    return res.status(400).json({ error: "Name, coach, and founded are required" });
  }

  mockTeams[teamIndex] = {
    id: req.params.id,
    name,
    coach,
    founded: Number(founded)
  };

  res.json(mockTeams[teamIndex]);
});

// Delete a team
router.delete("/:id", (req: Request, res: Response) => {
  const teamIndex = mockTeams.findIndex(team => team.id === req.params.id);

  if (teamIndex === -1) {
    return res.status(404).json({ error: "Team not found" });
  }

  mockTeams.splice(teamIndex, 1);
  res.json({ message: "Team deleted successfully" });
});

// Get team roster
router.get("/:id/roster", (req: Request, res: Response) => {
  const team = findTeamById(req.params.id);

  if (!team) {
    return res.status(404).json({ error: "Team not found" });
  }

  const roster = findRosterByTeamId(req.params.id);
