            name="amount"
            value={formData.amount}
            onChange={handleChange}
            required
            style={{
              width: "100%",
              padding: "10px",
              borderRadius: "5px",
              border: "1px solid #ccc",
            }}
          />
        </div>

        <div>
          <label htmlFor="date" style={{ display: "block", marginBottom: "5px" }}>
