import { useEffect, useState } from "react";

interface Expense {
  id: number;
  description: string;
  amount: number;
  date: string;
  category: string;
}

export function ExpenseList() {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [filteredExpenses, setFilteredExpenses] = useState<Expense[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("all");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchExpenses();
  }, []);

  const fetchExpenses = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/expenses");
      if (!response.ok) {
        throw new Error(`Failed to fetch expenses: ${response.status}`);
      }
      const data = await response.json();
      setExpenses(data);
      setFilteredExpenses(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    let result = expenses;

    if (searchTerm) {
      const term = searchTerm.toLowerCase();
      result = result.filter(expense => 
        expense.description.toLowerCase().includes(term) ||
        expense.category.toLowerCase().includes(term)
      );
    }

    if (categoryFilter !== "all") {
      result = result.filter(expense => expense.category === categoryFilter);
    }

    setFilteredExpenses(result);
  }, [searchTerm, categoryFilter, expenses]);

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/expenses/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to delete expense: ${response.status}`);
      }
      // Refresh the list after deletion
      fetchExpenses();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const categories = [...new Set(expenses.map(e => e.category))];

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Expense List</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search expenses..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        />

        <select
          value={categoryFilter}
          onChange={(e) => setCategoryFilter(e.target.value)}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="all">All Categories</option>
          {categories.map(category => (
            <option key={category} value={category}>{category}</option>
          ))}
        </select>
      </div>

      {filteredExpenses.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No expenses found.</p>
      ) : (
        <div style={{ overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", marginBottom: "20px" }}>
            <thead>
              <tr style={{ backgroundColor: "#f5f5f5" }}>
                <th style={{ border: "1px solid #ddd", padding: "12px", textAlign: "left" }}>Description</th>
                <th style={{ border: "1px solid #ddd", padding: "12px", textAlign: "left" }}>Amount</th>
                <th style={{ border: "1px solid #ddd", padding: "12px", textAlign: "left" }}>Date</th>
                <th style={{ border: "1px solid #ddd", padding: "12px", textAlign: "left" }}>Category</th>
                <th style={{ border: "1px solid #ddd", padding: "12px", textAlign: "left" }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredExpenses.map(expense => (
                <tr key={expense.id} style={{ borderBottom: "1px solid #ddd" }}>
                  <td style={{ border: "1px solid #ddd", padding: "12px" }}>{expense.description}</td>
                  <td style={{ border: "1px solid #ddd", padding: "12px" }}>${expense.amount.toFixed(2)}</td>
                  <td style={{ border: "1px solid #ddd", padding: "12px" }}>{expense.date}</td>
                  <td style={{ border: "1px solid #ddd", padding: "12px" }}>{expense.category}</td>
                  <td style={{ border: "1px solid #ddd", padding: "12px" }}>
                    <button 
                      onClick={() => handleDelete(expense.id)}
                      style={{ 
                        backgroundColor: "#dc3545", 
                        color: "white", 
                        border: "none", 
                        padding: "6px 12px", 
                        borderRadius: "4px", 
                        cursor: "pointer", 
                        marginRight: "5px" 
                      }}
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
