// Middleware function
export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE requests to /expenses
  if (!(req.method === "POST" || req.method === "PUT" || req.method === "DELETE") || !req.path.startsWith("/expenses")) {
    next();
    return;
  }

  // Get the token from headers
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);

  // Validate token signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  try {
    // Decode the token (simplified for example)
    const payload = decodeJwt(token);
    const userId = payload.userId;
    const userRoles = payload.roles;

    // Check if user has required role
    const requiredRole: UserRole = "editor"; // Example required role
    if (!userRoles.includes(requiredRole)) {
      res.status(403).json({ error: "Forbidden: Insufficient permissions" });
      return;
    }

    // If we reach here, user is authorized
    next();
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

