const mockPolls = [
  { id: 1, question: "What's your favorite color?", options: ["Red", "Blue", "Green"] },
  { id: 2, question: "Which framework do you prefer?", options: ["React", "Vue", "Angular"] }
];

const findPollIndex = (id: number) => {
  return mockPolls.findIndex(poll => poll.id === id);
};

// GET /polls - List all polls
