router.get("/polls/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const index = findPollIndex(id);

  if (index === -1) {
    return res.status(404).json({ error: "Poll not found" });
  }

  res.json(mockPolls[index]);
});

// POST /polls - Create a new poll
router.post("/polls", (req: Request, res: Response) => {
  const { question, options } = req.body;

  if (!question || !Array.isArray(options)) {
    return res.status(400).json({ error: "Question and options are required" });
  }

  const newId = mockPolls.length > 0 ? Math.max(...mockPolls.map(p => p.id)) + 1 : 1;
  const newPoll = { id: newId, question, options };

  mockPolls.push(newPoll);

  res.status(201).json(newPoll);
});

// PUT /polls/:id - Update a poll
router.put("/polls/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const index = findPollIndex(id);

  if (index === -1) {
    return res.status(404).json({ error: "Poll not found" });
  }

  const { question, options } = req.body;

  if (!question || !Array.isArray(options)) {
    return res.status(400).json({ error: "Question and options are required" });
  }

  mockPolls[index] = { id, question, options };

  res.json(mockPolls[index]);
});

// DELETE /polls/:id - Delete a poll
router.delete("/polls/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const index = findPollIndex(id);

  if (index === -1) {
    return res.status(404).json({ error: "Poll not found" });
  }

  mockPolls.splice(index, 1);

  res.json({ message: "Poll deleted successfully" });
});

