export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to the /polls/:id/vote endpoint
  if (req.method !== "POST" || !req.path.startsWith("/polls/")) {
    next();
    return;
  }

  // Validate that the request has a body with selections
  if (!req.body || !Array.isArray(req.body.selections)) {
    res.status(400).json({ error: "Invalid vote data: selections array required" });
