  }

  // Validate that selections is not empty
  if (req.body.selections.length === 0) {
    res.status(400).json({ error: "Vote must include at least one selection" });
    return;
  }

  // Validate that all selections are valid (non-empty strings)
  for (const selection of req.body.selections) {
    if (typeof selection !== "string" || selection.trim() === "") {
      res.status(400).json({ error: "Each selection must be a non-empty string" });
      return;
    }
  }

  // If we've made it this far, the vote data is valid
  next();
}

