import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  {
    id: "1",
    email: "customer@example.com",
    password: "hashedPassword123",
    role: "customer"
  },
  {
    id: "2",
    email: "walker@example.com",
    password: "hashedPassword456",
    role: "walker"
  }
];

// Mock registration function
const registerUser = (email: string, password: string, role: string) => {
  const newUser = {
    id: `${users.length + 1}`,
    email,
    password,
    role
  };
  users.push(newUser);
  return newUser;
};

// Mock login function
const loginUser = (email: string, password: string) => {
  return users.find(user => user.email === email && user.password === password);
};

// Registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { email, password, role } = req.body;

  if (!email || !password || !role) {
    return res.status(400).json({ error: "Email, password, and role are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.email === email);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Register new user
  const newUser = registerUser(email, password, role);
  return res.status(201).json(newUser);
});

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  const user = loginUser(email, password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  return res.json({
    id: user.id,
    email: user.email,
    role: user.role
  });
});

// Role-based access control middleware
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    const token = req.headers.authorization?.split(" ")[1];
    if (!token) {
      return res.status(401).json({ error: "Access denied" });
    }

    // In a real app, we would decode the JWT and verify the role
    // For now, we'll just simulate checking the role
    const user = users.find(u => u.id === token);
    if (!user || user.role !== requiredRole) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }

    next();
  };
};

// Customer-only route example
router.get("/customer/dashboard", requireRole("customer"), (req: Request, res: Response) => {
  return res.json({ message: "Customer dashboard accessed successfully" });
});

// Walker-only route example
router.get("/walker/dashboard", requireRole("walker"), (req: Request, res: Response) => {
  return res.json({ message: "Walker dashboard accessed successfully" });
});

