import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const protectedPaths = [
    "/bookings",
    "/walkers",
    "/customers",
    "/admin"
  ];

  const isProtectedPath = protectedPaths.some(path => 
    req.path.startsWith(path) || 
    req.path === path
  );

  // Skip validation for non-protected paths
  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;
  const requiredRoles = getRequiredRoles(req.method, req.path);

  if (!userRole || !requiredRoles.includes(userRole)) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  next();
}

function getRequiredRoles(method: string, path: string): string[] {
  // Define role requirements per route
  const roleMap: Record<string, string[]> = {
    "/bookings": ["customer", "walker", "admin"],
    "/walkers": ["admin"],
    "/customers": ["admin"],
    "/admin": ["admin"]
  };

  // Handle different HTTP methods
  if (method === "POST" && path === "/bookings") {
    return ["customer", "admin"];
  }

  if (method === "PUT" || method === "DELETE") {
    if (path.startsWith("/bookings/")) {
      return ["customer", "walker", "admin"];
    }
  }

  // Default to specific roles based on path
  const key = Object.keys(roleMap).find(k => path.startsWith(k));
  return key ? roleMap[key] : [];
}

