import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const todos = [
  { id: 1, title: "Buy groceries", priority: "high", dueDate: "2023-12-01" },
  { id: 2, title: "Walk the dog", priority: "medium", dueDate: "2023-12-02" },
];

const findTodoIndex = (id: number) => todos.findIndex(todo => todo.id === id);

// Get all todos
router.get("/", (req: Request, res: Response) => {
  res.json(todos);
});

// Get a single todo by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const todoIndex = findTodoIndex(id);

  if (todoIndex === -1) {
    return res.status(404).json({ error: "Todo not found" });
  }

  res.json(todos[todoIndex]);
});

// Create a new todo
router.post("/", (req: Request, res: Response) => {
  const { title, priority, dueDate } = req.body;

  // Validate required fields
  if (!title || !priority || !dueDate) {
    return res.status(400).json({ error: "Title, priority, and dueDate are required" });
  }

  // Validate priority
  if (!["low", "medium", "high"].includes(priority)) {
    return res.status(400).json({ error: "Priority must be low, medium, or high" });
  }

  // Create new todo
  const newId = todos.length > 0 ? Math.max(...todos.map(t => t.id)) + 1 : 1;
  const newTodo = { id: newId, title, priority, dueDate };
  todos.push(newTodo);

  res.status(201).json(newTodo);
});

// Update a todo
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const todoIndex = findTodoIndex(id);

  if (todoIndex === -1) {
    return res.status(404).json({ error: "Todo not found" });
  }

  const { title, priority, dueDate } = req.body;

  // Validate priority if provided
  if (priority && !['low', 'medium', 'high'].includes(priority)) {
    return res.status(400).json({ error: "Priority must be low, medium, or high" });
  }

  // Update todo
  todos[todoIndex] = {
    ...todos[todoIndex],
    ...(title && { title }),
    ...(priority && { priority }),
    ...(dueDate && { dueDate })
  };

  res.json(todos[todoIndex]);
});

// Delete a todo
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const todoIndex = findTodoIndex(id);

  if (todoIndex === -1) {
    return res.status(404).json({ error: "Todo not found" });
  }

  todos.splice(todoIndex, 1);
  res.json({ message: "Todo deleted successfully" });
});

