import { useEffect, useState } from "react";

interface Todo {
  id: number;
  title: string;
  description: string;
  priority: "low" | "medium" | "high";
  dueDate: string;
}

export function TodoListPage() {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchTodos();
  }, []);

  const fetchTodos = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/todos");
      if (!response.ok) {
        throw new Error(`Failed to fetch todos: ${response.status}`);
      }
      const data = await response.json();
      setTodos(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const filteredTodos = todos.filter(todo =>
    todo.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
    todo.description.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getPriorityColor = (priority: Todo["priority"]) => {
    switch (priority) {
      case "high":
        return "#ff4d4d";
      case "medium":
        return "#ffd633";
      case "low":
        return "#4dff88";
      default:
        return "#cccccc";
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Todo List</h1>

      <div style={{ marginBottom: "20px" }}>
        <input
          type="text"
          placeholder="Search todos..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{
            width: "100%",
            padding: "10px",
            borderRadius: "4px",
            border: "1px solid #ccc",
            fontSize: "16px"
          }}
        />
      </div>

      {filteredTodos.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No todos found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {filteredTodos.map(todo => (
            <div 
              key={todo.id} 
              style={{
                border: "1px solid #ddd",
                borderRadius: "8px",
                padding: "15px",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                backgroundColor: "#f9f9f9"
              }}
            >
              <div>
                <h3 style={{ margin: "0 0 5px 0" }}>{todo.title}</h3>
                <p style={{ margin: "0 0 5px 0", color: "#666" }}>{todo.description}</p>
                <div style={{ display: "flex", alignItems: "center", gap: "5px" }}>
                  <span style={{
                    display: "inline-block",
                    width: "12px",
                    height: "12px",
                    borderRadius: "50%",
                    backgroundColor: getPriorityColor(todo.priority)
                  }}></span>
                  <span style={{ textTransform: "capitalize" }}>{todo.priority} priority</span>
                </div>
                <p style={{ margin: "5px 0 0 0", color: "#666" }}>
                  Due: {new Date(todo.dueDate).toLocaleDateString()}
                </p>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

