import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  { id: 1, username: "admin", password: "admin123", role: "admin" },
  { id: 2, username: "chef", password: "chef123", role: "chef" },
  { id: 3, username: "waiter", password: "waiter123", role: "waiter" }
];

// Mock session store
const sessions = new Map<string, { userId: number; role: string; expiresAt: Date }>();

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate session token
  const token = Math.random().toString(36).substring(2, 15);
  const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000); // 24 hours

  sessions.set(token, {
    userId: user.id,
    role: user.role,
    expiresAt
  });

  return res.json({ token, role: user.role });
});

// Logout endpoint
router.post("/logout", (req: Request, res: Response) => {
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    return res.status(400).json({ error: "No session token provided" });
  }

  if (!sessions.has(token)) {
    return res.status(401).json({ error: "Invalid session token" });
  }

  sessions.delete(token);
  return res.json({ message: "Logged out successfully" });
});

// Middleware to verify session
const authenticate = (req: Request, res: Response, next: () => void) => {
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "No session token provided" });
  }

  const session = sessions.get(token);

  if (!session) {
    return res.status(401).json({ error: "Invalid session token" });
  }

  // Check if session has expired
  if (new Date() > session.expiresAt) {
    sessions.delete(token);
    return res.status(401).json({ error: "Session expired" });
  }

  // Attach user info to request
  (req as any).user = session;
  next();
};

// Role-based authorization middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: () => void) => {
    const user = (req as any).user;

    if (!user) {
      return res.status(401).json({ error: "Unauthorized" });
    }

    if (!roles.includes(user.role)) {
      return res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    }

    next();
  };
};

// Protected route example - requires authentication
router.get("/profile", authenticate, (req: Request, res: Response) => {
  const user = (req as any).user;
  return res.json({ userId: user.userId, role: user.role });
});

// Admin-only route example
router.get("/admin", authenticate, authorize(["admin"]), (req: Request, res: Response) => {
  return res.json({ message: "Admin access granted" });
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// Define the role map with explicit types
const roleMap: Record<string, string[]> = {
  "/orders": ["admin", "staff"],
  "/menu": ["admin", "staff"],
  "/users": ["admin"]
};

// Helper to check if user has required role
function hasRequiredRole(userRoles: string[], requiredRoles: string[]): boolean {
  return userRoles.some(role => requiredRoles.includes(role));
}

// Middleware function
export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check routes that are defined in roleMap
  const matchedRoute = Object.keys(roleMap).find(route => 
    req.path.startsWith(route)
  );

  // If no matching route found, skip validation
  if (!matchedRoute) {
    next();
    return;
  }

  // Get required roles for this route
  const requiredRoles = roleMap[matchedRoute];

  // Check if user has required role
  const userRoles = req.headers["x-user-roles"] as string | string[] || [];
  const rolesArray = Array.isArray(userRoles) ? userRoles : [userRoles];

  if (hasRequiredRole(rolesArray, requiredRoles)) {
    next();
  } else {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function isValidToken(token: string): boolean {
  if (!JWT_SECRET) return false;

  const parts = token.split(".");
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;

  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(signature, "base64url");

    return timingSafeEqual(expectedBuffer, actualBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests that contain a token in the header
  if (req.method !== "POST" || !req.headers.authorization) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Invalid authorization header format" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  if (!isValidToken(token)) {
    res.status(401).json({ error: "Invalid or expired token" });
    return;
  }

  next();
}

import { useEffect, useState } from "react";

