      // In a real app, this would be WebSocket or polling
      setOrders(prevOrders => {
        const updatedOrders = [...prevOrders];
        // Randomly update some orders
        if (updatedOrders.length > 0) {
          const randomIndex = Math.floor(Math.random() * updatedOrders.length);
          const statuses: Order["status"][] = ["pending", "preparing", "ready", "completed", "cancelled"];
          updatedOrders[randomIndex].status = statuses[Math.floor(Math.random() * statuses.length)];
