        </select>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(300px, 1fr))", gap: "20px" }}>
        {filteredOrders.length === 0 ? (
          <div style={{ textAlign: "center", gridColumn: "1 / -1", padding: "20px" }}>
