import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check role-based access for specific routes that require it
  const protectedPaths = ["/equipment", "/lending", "/users"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  // Define required roles for different paths
  const pathRoles: Record<string, string[]> = {
    "/equipment": ["admin", "lab-manager"],
    "/lending": ["admin", "lab-manager", "student"],
    "/users": ["admin"]
  };

  const requiredRoles = pathRoles[req.path] || [];

  // If no roles are required, allow access
  if (requiredRoles.length === 0) {
    next();
    return;
  }

  // Validate that userRole exists and is a string
  if (!userRole || typeof userRole !== "string") {
    res.status(403).json({ error: "Access denied: Invalid user role" });
    return;
  }

  // Check if user has required role
  if (requiredRoles.includes(userRole)) {
    next();
  } else {
    res.status(403).json({ error: "Access denied: Insufficient permissions" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT_SECRET is set
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // For demonstration purposes, we'll just check if the request has a valid body
  // In a real implementation, this would verify a JWT token signature
  if (!req.body || !req.body.token) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Simulate token verification - in reality, this would verify HMAC-SHA256 signature
  try {
    const token = req.body.token;
    const expectedSignature = createHmac("sha256", secret)
      .update(token.split(".")[0])
      .digest();

    const actualSignature = Buffer.from(token.split(".")[1], "base64");

    // This is a simplified check - in practice, you'd want to properly parse and verify
    // the JWT structure and signature using a proper library
    const isValid = timingSafeEqual(expectedSignature, actualSignature);

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }
  } catch (error) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  next();
}

