interface LoanRecord {
  id: number;
  userId: number;
  equipmentId: number;
  equipmentName: string;
  userName: string;
  loanDate: string;
  returnDate: string | null;
  status: "active" | "returned";
}

export function LendingRecordsPage() {
  const [records, setRecords] = useState<LoanRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [filterStatus, setFilterStatus] = useState<"all" | "active" | "returned">("all");

  useEffect(() => {
    fetchLendingRecords();
  }, []);

  const fetchLendingRecords = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/loans`);
      if (!response.ok) {
        throw new Error(`Failed to fetch records: ${response.status}`);
      }
      const data = await response.json();
      setRecords(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleReturn = async (loanId: number) => {
    try {
      const response = await fetch(`/api/loans/${loanId}/return`, {
        method: "PUT",
      });
      if (!response.ok) {
        throw new Error(`Failed to return item: ${response.status}`);
      }
      // Refresh the records after returning
      await fetchLendingRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const filteredRecords = records.filter(record => {
    const matchesSearch = 
      record.userName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      record.equipmentName.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = filterStatus === "all" || record.status === filterStatus;
    return matchesSearch && matchesStatus;
  });

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Equipment Lending Records</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search by user or equipment..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        />

        <select
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value as "all" | "active" | "returned")}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="all">All Statuses</option>
          <option value="active">Active</option>
          <option value="returned">Returned</option>
        </select>
      </div>

      {filteredRecords.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No lending records found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {filteredRecords.map(record => (
            <div 
              key={record.id} 
              style={{ 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                padding: "15px", 
                backgroundColor: record.status === "returned" ? "#f0f8f0" : "#fff8f0" 
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <h3>{record.equipmentName}</h3>
                  <p><strong>Borrowed by:</strong> {record.userName}</p>
                  <p><strong>Loan Date:</strong> {new Date(record.loanDate).toLocaleDateString()}</p>
                  {record.returnDate && (
                    <p><strong>Return Date:</strong> {new Date(record.returnDate).toLocaleDateString()}</p>
                  )}
                  <p><strong>Status:</strong> <span style={{ textTransform: "capitalize" }}>{record.status}</span></p>
                </div>

                {record.status === "active" && (
                  <button 
                    onClick={() => handleReturn(record.id)}
                    style={{ 
                      backgroundColor: "#4CAF50", 
                      color: "white", 
                      border: "none", 
                      padding: "8px 16px", 
                      borderRadius: "4px", 
                      cursor: "pointer" 
                    }}
                  >
                    Mark as Returned
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

