import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check role-based access for specific routes that require it
  const protectedPaths = ["/equipment", "/lending", "/users"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  // Define required roles for different paths
  const pathRoles: Record<string, string[]> = {
    "/equipment": ["admin", "lab-manager"],
    "/lending": ["admin", "lab-manager", "student"],
    "/users": ["admin"]
  };

  const requiredRoles = pathRoles[req.path] || [];

  // If no roles are required, allow access
  if (requiredRoles.length === 0) {
    next();
    return;
  }

  // Validate that userRole exists and is a string
  if (!userRole || typeof userRole !== "string") {
    res.status(403).json({ error: "Access denied: Invalid user role" });
    return;
  }

  // Check if user has required role
  if (requiredRoles.includes(userRole)) {
    next();
  } else {
    res.status(403).json({ error: "Access denied: Insufficient permissions" });
  }
}

