  const id = req.params.id;
  const { name, capacity, location } = req.body;

  const hallIndex = halls.findIndex(h => h.id === id);

  if (hallIndex === -1) {
    return res.status(404).json({ error: "Hall not found" });
  }

  if (!name || !capacity || !location) {
