import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-POST requests to /bookings
  if (req.method !== "POST" || !req.path.startsWith("/bookings")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT_SECRET not set" });
    return;
  }

  // Simple token verification (in a real app, use proper JWT library)
  const [payload, signature] = token.split(".");
  if (!payload || !signature) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  // Create expected signature
  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64url");

  // Use timingSafeEqual to prevent timing attacks
  const isValid = timingSafeEqual(
    Buffer.from(signature, "base64url"),
    Buffer.from(expectedSignature, "base64url")
  );

  if (!isValid) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  // Decode payload to get user role
  try {
    const decodedPayload = Buffer.from(payload, "base64url").toString("utf-8");
    const payloadObj = JSON.parse(decodedPayload);

    if (payloadObj.role === "staff") {
      // Staff can manage halls and approve bookings
      next();
    } else if (payloadObj.role === "user") {
      // Regular users can only view and book halls
      res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    } else {
      res.status(401).json({ error: "Unauthorized: Unknown role" });
    }
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token payload" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only validate POST, PUT, PATCH requests to booking routes
  if (!['POST', 'PUT', 'PATCH'].includes(req.method) || !req.path.startsWith('/bookings')) {
    next();
    return;
  }

  // Validate booking data structure
  if (req.body) {
    // Check for potential injection patterns in string fields
    const fieldsToCheck = ['hallId', 'bookingDate', 'startTime', 'endTime', 'bookerName'];

    for (const field of fieldsToCheck) {
      if (typeof req.body[field] === 'string') {
        const value = req.body[field];
        // Check for common injection patterns
        if (value.includes('\\') || value.includes('\\\\') || value.includes('\\0')) {
          res.status(400).json({ error: `Invalid characters in ${field}` });
          return;
        }

        // Check for SQL injection patterns
        const sqlPatterns = [/ (union|select|insert|update|delete|drop|create) /i,
                            /\b(\d+\s*\+\s*\d+)\b/];
        for (const pattern of sqlPatterns) {
          if (pattern.test(value)) {
            res.status(400).json({ error: `Potential SQL injection detected in ${field}` });
            return;
          }
        }
      }
    }

    // Validate date format
    if (req.body.bookingDate) {
      const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
      if (!dateRegex.test(req.body.bookingDate)) {
        res.status(400).json({ error: 'Invalid date format. Expected YYYY-MM-DD' });
        return;
      }

      // Validate date is not in the past
      const inputDate = new Date(req.body.bookingDate);
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      if (inputDate < today) {
        res.status(400).json({ error: 'Booking date cannot be in the past' });
        return;
      }
    }

    // Validate time format
    if (req.body.startTime || req.body.endTime) {
      const timeRegex = /^\d{2}:\d{2}$/;
      if (req.body.startTime && !timeRegex.test(req.body.startTime)) {
        res.status(400).json({ error: 'Invalid start time format. Expected HH:MM' });
        return;
      }
      if (req.body.endTime && !timeRegex.test(req.body.endTime)) {
        res.status(400).json({ error: 'Invalid end time format. Expected HH:MM' });
        return;
      }

      // Validate time range
      if (req.body.startTime && req.body.endTime) {
        const [startHour, startMinute] = req.body.startTime.split(':').map(Number);
        const [endHour, endMinute] = req.body.endTime.split(':').map(Number);

        if (startHour > endHour || (startHour === endHour && startMinute >= endMinute)) {
          res.status(400).json({ error: 'End time must be after start time' });
          return;
        }
      }
    }

    // Validate hall capacity
    if (req.body.hallCapacity !== undefined) {
      if (typeof req.body.hallCapacity !== 'number' || req.body.hallCapacity <= 0) {
        res.status(400).json({ error: 'Hall capacity must be a positive number' });
        return;
      }
    }
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes

interface Session {
  userId: string;
  createdAt: number;
}

const activeSessions = new Map<string, Session>();

function getSessionIdFromRequest(req: Request): string | null {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return null;
  }

  const token = authHeader.substring(7);
  return token;
}

function verifyTokenSignature(token: string): boolean {
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return false;
  }

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) {
      return false;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

function decodeToken(token: string): { userId: string } | null {
  try {
    const payload = token.split(".")[1];
    const decoded = Buffer.from(payload, "base64url").toString("utf-8");
    return JSON.parse(decoded);
  } catch {
    return null;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST /logout requests
  if (req.method !== "POST" || req.path !== "/logout") {
    next();
    return;
  }

  const sessionId = getSessionIdFromRequest(req);
  if (!sessionId) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  if (!verifyTokenSignature(sessionId)) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  const tokenData = decodeToken(sessionId);
  if (!tokenData) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  const session = activeSessions.get(sessionId);
  if (!session) {
    res.status(401).json({ error: "Session not found" });
    return;
  }

  // Check if session has timed out
  if (Date.now() - session.createdAt > SESSION_TIMEOUT) {
    activeSessions.delete(sessionId);
    res.status(401).json({ error: "Session expired" });
    return;
  }

  // Invalidate session on logout
  activeSessions.delete(sessionId);
  res.json({ message: "Logged out successfully" });
}

