import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  const protectedPaths = ["/bookings", "/patients"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  // Skip validation for non-protected routes
  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  // If no role header, deny access
  if (!userRole) {
    res.status(403).json({ error: "Access denied: role not provided" });
    return;
  }

  // Define role requirements for different paths
  const roleRequirements: Record<string, string[]> = {
    "/bookings": ["admin", "booking-manager"],
    "/patients": ["admin", "doctor", "nurse"]
  };

  // Determine required roles based on path
  let requiredRoles: string[] = [];
  for (const [path, roles] of Object.entries(roleRequirements)) {
    if (req.path.startsWith(path)) {
      requiredRoles = roles;
      break;
    }
  }

  // If no specific requirements found, allow admin access
  if (requiredRoles.length === 0) {
    if (userRole !== "admin") {
      res.status(403).json({ error: "Access denied: insufficient permissions" });
      return;
    }
  } else {
    // Check if user has one of the required roles
    if (!requiredRoles.includes(userRole)) {
      res.status(403).json({ error: "Access denied: insufficient permissions" });
      return;
    }
  }

  // If we reach here, user has proper role
  next();
}

