import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database - in a real app this would be a proper database
const users = [
  { id: 1, username: "admin", password: "admin123", role: "administrator" },
  { id: 2, username: "staff1", password: "staff123", role: "staff" },
  { id: 3, username: "staff2", password: "staff456", role: "staff" }
];

// Mock session store - in a real app this would be a proper session store
const sessions = new Map<string, { userId: number; role: string; expiresAt: Date }>();

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Find user by username and password
  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate a mock session ID
  const sessionId = Math.random().toString(36).substring(2, 15);

  // Create session
  const expiresAt = new Date();
  expiresAt.setHours(expiresAt.getHours() + 1); // Session expires in 1 hour
  sessions.set(sessionId, { userId: user.id, role: user.role, expiresAt });

  // Send response with session ID
  return res.json({ sessionId, role: user.role });
});

// Logout endpoint
router.post("/logout", (req: Request, res: Response) => {
  const { sessionId } = req.body;

  if (!sessionId) {
    return res.status(400).json({ error: "Session ID is required" });
  }

  // Remove session
  sessions.delete(sessionId);

  return res.json({ message: "Logged out successfully" });
});

// Middleware to verify session
const authenticateSession = (req: Request, res: Response, next: () => void) => {
  const { sessionId } = req.headers;

  if (!sessionId) {
    return res.status(401).json({ error: "No session provided" });
  }

  const session = sessions.get(sessionId as string);

  if (!session) {
    return res.status(401).json({ error: "Invalid session" });
  }

  // Check if session has expired
  if (new Date() > session.expiresAt) {
    sessions.delete(sessionId as string);
    return res.status(401).json({ error: "Session expired" });
  }

  // Attach user info to request
  (req as any).user = { id: session.userId, role: session.role };
  next();
};

// Role-based access control middleware
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: () => void) => {
    const user = (req as any).user;

    if (!user) {
      return res.status(401).json({ error: "Unauthorized" });
    }

    if (user.role !== requiredRole) {
      return res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    }

    next();
  };
};

// Protected route example - requires staff role
router.get("/profile", authenticateSession, (req: Request, res: Response) => {
  const user = (req as any).user;
  return res.json({ id: user.id, role: user.role });
});

// Admin-only route example
router.get("/admin", authenticateSession, requireRole("administrator"), (req: Request, res: Response) => {
  return res.json({ message: "Welcome, administrator!" });
});

