  const index = findIndexById(mockDatabase.meetings, req.params.id);
  if (index === -1) {
    return res.status(404).json({ error: "Meeting not found" });
  }

  const { title, date, agenda } = req.body;
  if (!title || !date || !agenda) {
    return res.status(400).json({ error: "Title, date, and agenda are required" });
