import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-protected routes
  if (req.method === "GET" && req.path === "/") {
    return next();
  }

  // Check if the request has an authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const token = authHeader.substring(7);

  // Check if JWT secret is set
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    return res.status(500).json({ error: "Server configuration error" });
  }

  // Basic token format validation
  const parts = token.split(".");
  if (parts.length !== 3) {
    return res.status(401).json({ error: "Invalid token format" });
  }

  const [header, payload, signature] = parts;

  // Verify the signature
  const expectedSignature = createHmac("sha256", jwtSecret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  const signatureBuffer = Buffer.from(signature, "base64url");
  const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

  try {
    const isValid = timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
    if (!isValid) {
      return res.status(401).json({ error: "Invalid token signature" });
    }
  } catch (err) {
    return res.status(401).json({ error: "Invalid token signature" });
  }

  // Decode the payload to get user info
  try {
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
    const { role, userId } = decodedPayload;

    // Apply role-based access control
    if (role === "customer") {
      // For customers, ensure they can only access their own orders
      if (req.path.includes("/orders/") && req.params.userId !== userId) {
        return res.status(403).json({ error: "Forbidden" });
      }
    } else if (role === "staff") {
      // Staff can access all resources
      if (req.path.includes("/products/") || req.path.includes("/orders/")) {
        // Allow staff to access all orders and products
      }
    } else {
      return res.status(401).json({ error: "Invalid token" });
    }

    // If we reach here, the request is valid
    next();
  } catch (err) {
    return res.status(401).json({ error: "Invalid token" });
  }
}

