import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes
const JWT_SECRET = process.env.JWT_SECRET;

// Helper to check if a string is a valid JWT (basic format check)
function isValidJwt(token: string): boolean {
  const parts = token.split(".");
  return parts.length === 3 &&
         parts[0].length > 0 &&
         parts[1].length > 0 &&
         parts[2].length > 0;
}

// Helper to extract payload from JWT (without verification)
function decodeJwtPayload(token: string): Record<string, unknown> | null {
  try {
    const payloadPart = token.split(".")[1];
    const payload = Buffer.from(payloadPart, "base64").toString();
    return JSON.parse(payload);
  } catch {
    return null;
  }
}

// Helper to verify JWT signature
function verifyJwtSignature(token: string): boolean {
  if (!JWT_SECRET || !isValidJwt(token)) {
    return false;
  }

  try {
    const [header, payload, signature] = token.split(".");
    const expectedSignature = createHmac("sha256", JWT_SECRET)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const actualSignature = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(actualSignature, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

// Helper to check if session has expired
function isSessionExpired(expirationTime: number): boolean {
  return Date.now() > expirationTime;
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT_SECRET is set
  if (!JWT_SECRET) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  // Check if authorization header exists
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Verify JWT signature
  if (!verifyJwtSignature(token)) {
    res.status(401).json({ error: "Invalid or tampered token" });
    return;
  }

  // Decode payload to check expiration
  const payload = decodeJwtPayload(token);
  if (!payload || typeof payload.exp !== "number") {
    res.status(401).json({ error: "Invalid token payload" });
    return;
  }

  // Check if session has expired
  if (isSessionExpired(payload.exp)) {
    res.status(401).json({ error: "Session expired" });
    return;
  }

  // If we get here, the session is valid
  next();
}

