import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const protectedPaths = [
    "/admin",
    "/staff",
    "/student",
    "/certificate-request",
    "/approval"
  ];

  const isProtectedPath = protectedPaths.some(path => 
    req.path.startsWith(path) || 
    req.path === path
  );

  // Skip middleware for non-protected paths
  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has proper role access
  const userRole = req.headers["x-user-role"] as string | undefined;

  // If no role header, deny access
  if (!userRole) {
    res.status(403).json({ error: "Access denied: Role not specified" });
    return;
  }

  // Define role requirements for different paths
  const roleRequirements: Record<string, string[]> = {
    "/admin": ["admin"],
    "/staff": ["staff", "admin"],
    "/student": ["student", "staff", "admin"],
    "/certificate-request": ["student", "staff", "admin"],
    "/approval": ["staff", "admin"]
  };

  // Determine required roles based on path
  let requiredRoles: string[] = [];
  for (const [path, roles] of Object.entries(roleRequirements)) {
    if (req.path.startsWith(path) || req.path === path) {
      requiredRoles = roles;
      break;
    }
  }

  // If no specific requirements found, allow access
  if (requiredRoles.length === 0) {
    next();
    return;
  }

  // Check if user has required role
  if (!requiredRoles.includes(userRole)) {
    res.status(403).json({ error: "Access denied: Insufficient permissions" });
    return;
  }

  // User has proper role, proceed
  next();
}

