import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  const protectedPaths = ["/admin", "/appointments", "/patients"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  // Verify JWT signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  try {
    // Simple verification of token structure (in a real app, use a proper JWT library)
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    const [header, payload, signature] = parts;
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(signature, "base64url"),
      Buffer.from(expectedSignature, "base64url")
    );

    if (!isValid) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // Decode payload (simplified for this example)
    const decodedPayload = JSON.parse(
      Buffer.from(payload, "base64url").toString()
    );

    // Check roles
    const userRole = decodedPayload.role;
    if (!userRole) {
      res.status(401).json({ error: "Unauthorized: Role not specified in token" });
      return;
    }

    // Allow access based on role
    if (userRole === "staff" && protectedPaths.includes(req.path)) {
      next();
      return;
    }

    if (userRole === "patient" && req.path.startsWith("/patients/")) {
      // For patient-specific routes, ensure the patient ID matches
      const pathParts = req.path.split("/");
      const requestedPatientId = pathParts[3];
      const authenticatedPatientId = decodedPayload.patientId;

      if (requestedPatientId === authenticatedPatientId) {
        next();
        return;
      }
    }

    // Deny access
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /appointments endpoint
  if (req.method !== "POST" || !req.path.startsWith("/appointments")) {
    next();
    return;
  }

  // Check if the request has a valid authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Verify the token signature
  const expectedSignature = createHmac("sha256", secret)
    .update(token.split(".")[0] + "." + token.split(".")[1])
    .digest();

  const actualSignature = Buffer.from(token.split(".")[2], "base64");

  try {
    if (!timingSafeEqual(expectedSignature, actualSignature)) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // If we reach here, the token is valid
  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes
const ACTIVE_SESSIONS = new Map<string, { expires: number }>();

function getSessionIdFromRequest(req: Request): string | null {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return null;
  }

  const token = authHeader.substring(7);
  return token;
}

function verifyTokenSignature(token: string): boolean {
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return false;
  }

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) {
      return false;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /appointments
  if (req.method !== "POST" || !req.path.startsWith("/appointments")) {
    next();
    return;
  }

  const sessionId = getSessionIdFromRequest(req);
  if (!sessionId) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const session = ACTIVE_SESSIONS.get(sessionId);
  if (!session) {
    res.status(401).json({ error: "Invalid session" });
    return;
  }

  if (Date.now() > session.expires) {
    ACTIVE_SESSIONS.delete(sessionId);
    res.status(401).json({ error: "Session expired" });
    return;
  }

  // Verify token signature
  if (!verifyTokenSignature(sessionId)) {
    ACTIVE_SESSIONS.delete(sessionId);
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // Refresh session timeout
  session.expires = Date.now() + SESSION_TIMEOUT;

  next();
}

