export const router = Router();

// Mock user database - in a real app this would be a proper database
const users = [
  {
    id: 1,
    username: "admin",
    password: "hashed_password_123",
    role: "administrator"
  },
  {
    id: 2,
    username: "staff1",
    password: "hashed_password_456",
    role: "staff"
  }
];

// Mock session store
const sessions = new Map<string, { userId: number; role: string }>();

// Register a new user
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user (in a real app, hash the password)
  const newUser = {
    id: users.length + 1,
    username,
    password,
    role: role || "staff"
  };

  users.push(newUser);

  return res.status(201).json({
    id: newUser.id,
    username: newUser.username,
    role: newUser.role
  });
});

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Find user
  const user = users.find(u => u.username === username && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate session token
  const token = `session_${Math.random().toString(36).substring(2, 15)}`;
  sessions.set(token, { userId: user.id, role: user.role });

  return res.json({
    token,
    user: {
      id: user.id,
      username: user.username,
      role: user.role
    }
  });
});

// Middleware to verify session
const authenticate = (req: Request, res: Response, next: Function) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Authorization header missing or invalid" });
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix
  const session = sessions.get(token);

  if (!session) {
    return res.status(401).json({ error: "Invalid or expired session" });
  }

  (req as any).user = session;
  next();
};

// Middleware to check role
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    const userRole = (req as any).user?.role;
    if (!userRole || userRole !== requiredRole) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }
    next();
  };
};

// Get current user info
router.get("/me", authenticate, (req: Request, res: Response) => {
  const user = (req as any).user;
  return res.json({
    id: user.userId,
    username: users.find(u => u.id === user.userId)?.username,
    role: user.role
  });
});

// Logout endpoint
router.post("/logout", authenticate, (req: Request, res: Response) => {
  const authHeader = req.headers.authorization;
  if (authHeader && authHeader.startsWith("Bearer ")) {
    const token = authHeader.substring(7);
    sessions.delete(token);
  }
  return res.json({ message: "Logged out successfully" });
});

// Get all users (admin only)
router.get("/users", authenticate, requireRole("administrator"), (req: Request, res: Response) => {
  return res.json(users.map(u => ({ id: u.id, username: u.username, role: u.role })));
});

