import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function isValidMethod(method: string): boolean {
  return ["GET", "POST", "PUT", "DELETE"].includes(method);
}

function isProtectedPath(path: string): boolean {
  return path.startsWith("/reports");
}

function verifyToken(token: string): boolean {
  if (!JWT_SECRET) return false;

  const secretBuffer = Buffer.from(JWT_SECRET, "utf-8");
  const tokenParts = token.split(".");

  if (tokenParts.length !== 3) return false;

  const [header, payload, signature] = tokenParts;

  const expectedSignature = createHmac("sha256", secretBuffer)
    .update(`${header}.${payload}`)
    .digest();

  const actualSignature = Buffer.from(signature, "base64");

  try {
    return timingSafeEqual(expectedSignature, actualSignature);
  } catch {
    return false;
  }
}

function getUserRole(token: string): string | null {
  try {
    const payload = token.split(".")[1];
    const decodedPayload = Buffer.from(payload, "base64").toString("utf-8");
    const parsedPayload = JSON.parse(decodedPayload);
    return parsedPayload.role || null;
  } catch {
    return null;
  }
}

function isCustomer(token: string): boolean {
  const role = getUserRole(token);
  return role === "customer";
}

function isAdminOrStaff(token: string): boolean {
  const role = getUserRole(token);
  return role === "admin" || role === "staff";
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-protected paths or non-protected methods
  if (!isValidMethod(req.method) || !isProtectedPath(req.path)) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  if (!verifyToken(token)) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  // Check if it's a customer trying to access reports
  if (isCustomer(token) && req.method !== "GET") {
    res.status(403).json({ error: "Forbidden: Customers can only view their own reports" });
    return;
  }

  // Check if it's admin or staff trying to access reports
  if (isAdminOrStaff(token)) {
    next();
    return;
  }

  // For other roles, deny access
  res.status(403).json({ error: "Forbidden: Insufficient permissions" });
}

