import { useEffect, useState } from "react";

interface Report {
  id: number;
  shopperName: string;
  storeName: string;
  reportDate: string;
  status: string;
}

export function ReportList() {
  const [reports, setReports] = useState<Report[]>([]);
  const [filteredReports, setFilteredReports] = useState<Report[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchReports();
  }, []);

  const fetchReports = async () => {
    try {
      const response = await fetch('/api/reports');
      if (!response.ok) {
        throw new Error('Failed to fetch reports');
      }
      const data = await response.json();
      setReports(data);
      setFilteredReports(data);
      setLoading(false);
    } catch (err) {
      setError('Error loading reports');
      setLoading(false);
    }
  };

  const handleSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
    const term = e.target.value;
    setSearchTerm(term);

    if (term === "") {
      setFilteredReports(reports);
    } else {
      const filtered = reports.filter(report => 
        report.shopperName.toLowerCase().includes(term.toLowerCase()) ||
        report.storeName.toLowerCase().includes(term.toLowerCase()) ||
        report.status.toLowerCase().includes(term.toLowerCase())
      );
      setFilteredReports(filtered);
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/reports/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error('Failed to delete report');
      }
      // Refresh the list after deletion
      fetchReports();
    } catch (err) {
      setError('Error deleting report');
    }
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  if (error) {
    return <div>{error}</div>;
  }

  const searchInputStyle = {
    width: '100%',
    padding: '8px',
    marginBottom: '16px',
    borderRadius: '4px',
    border: '1px solid #ccc',
    boxSizing: 'border-box'
  };

  const reportsContainerStyle = {
    display: 'flex',
    flexDirection: 'column',
    gap: '16px'
  };

  const reportCardStyle = {
    border: '1px solid #ddd',
    borderRadius: '8px',
    padding: '16px',
    backgroundColor: '#f9f9f9'
  };

  const actionsContainerStyle = {
    display: 'flex',
    gap: '8px',
    marginTop: '8px',
    flexWrap: 'wrap'
  };

  const buttonStyle = {
    padding: '4px 8px',
    borderRadius: '4px',
    border: '1px solid #007bff',
    backgroundColor: '#007bff',
    color: 'white',
    cursor: 'pointer'
  };

  const deleteButtonStyle = {
    padding: '4px 8px',
    borderRadius: '4px',
    border: '1px solid #dc3545',
    backgroundColor: '#dc3545',
    color: 'white',
    cursor: 'pointer'
  };

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '16px', fontFamily: 'system-ui' }}>
      <h1>Mystery Shopper Reports</h1>

      <input
        type="text"
        placeholder="Search reports..."
        value={searchTerm}
        onChange={handleSearch}
        style={searchInputStyle}
      />

      <div style={reportsContainerStyle}>
        {filteredReports.length === 0 ? (
          <p>No reports found.</p>
        ) : (
          filteredReports.map(report => (
            <div key={report.id} style={reportCardStyle}>
              <h3>{report.shopperName}</h3>
              <p><strong>Store:</strong> {report.storeName}</p>
              <p><strong>Date:</strong> {report.reportDate}</p>
              <p><strong>Status:</strong> {report.status}</p>
              <div style={actionsContainerStyle}>
                <button 
                  onClick={() => window.location.href = `/reports/${report.id}`}
                  style={buttonStyle}
                >
                  View
                </button>
                <button 
                  onClick={() => window.location.href = `/reports/${report.id}/edit`}
                  style={buttonStyle}
                >
                  Edit
                </button>
                <button 
                  onClick={() => handleDelete(report.id)}
                  style={deleteButtonStyle}
                >
                  Delete
                </button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

